// ReleaseTrail is a public, wallet-authenticated product release registry.
// It records immutable claims and independently signed reviews on Gno.land.
package releasetrail

import (
	"chain/runtime"
	"strconv"
	"strings"
)

const (
	maxReleases       = 1000
	maxReviews        = 4000
	maxTitleLength    = 80
	maxSummaryLength  = 240
	maxVersionLength  = 24
	maxEvidenceLength = 240
)

type Release struct {
	ID        int
	Author    address
	Project   string
	Version   string
	Summary   string
	Evidence  string
	Height    int64
	Verified  int
	Flagged   int
	Retracted bool
}

type ReviewRecord struct {
	ReleaseID int
	Reviewer  address
	Outcome   string
	Height    int64
}

var releases []*Release
var reviewRecords []*ReviewRecord
var reviewers = make(map[string]bool)
var reviewsCount int
var flagsCount int

// Publish records a release claim. Each release and its evidence link are immutable.
// The authentic calling realm/address is used as the author, never a user-supplied value.
func Publish(cur realm, project string, version string, summary string, evidenceURL string) int {
	if len(releases) >= maxReleases {
		panic("release registry is full")
	}
	if !validText(project, 3, maxTitleLength) {
		panic("project must be 3-80 safe ASCII characters")
	}
	if !validVersion(version) {
		panic("invalid version: use 1-24 letters, numbers, dots, dashes or underscores")
	}
	if !validText(summary, 10, maxSummaryLength) {
		panic("summary must be 10-240 safe ASCII characters")
	}
	if !validEvidenceURL(evidenceURL) {
		panic("evidence must be a safe https URL, up to 240 characters")
	}

	r := &Release{
		ID:       len(releases) + 1,
		Author:   cur.Previous().Address(),
		Project:  project,
		Version:  version,
		Summary:  summary,
		Evidence: evidenceURL,
		Height:   runtime.ChainHeight(),
	}
	releases = append(releases, r)
	return r.ID
}

// Review creates one public review per wallet, per release.
// A publisher cannot review their own release. Reviews cannot be changed.
func Review(cur realm, releaseID int, outcome string) string {
	r := lookup(releaseID)
	if r.Retracted {
		panic("cannot review a retracted release")
	}
	if len(reviewRecords) >= maxReviews {
		panic("review registry is full")
	}
	caller := cur.Previous().Address()
	if r.Author == caller {
		panic("you cannot review your own release")
	}
	if outcome != "verify" && outcome != "flag" {
		panic("outcome must be verify or flag")
	}
	key := strconv.Itoa(releaseID) + ":" + string(caller)
	if reviewers[key] {
		panic("one review per wallet per release")
	}
	reviewers[key] = true
	reviewRecords = append(reviewRecords, &ReviewRecord{
		ReleaseID: releaseID,
		Reviewer:  caller,
		Outcome:   outcome,
		Height:    runtime.ChainHeight(),
	})
	if outcome == "verify" {
		r.Verified++
		reviewsCount++
	} else {
		r.Flagged++
		flagsCount++
	}
	return "review recorded"
}

// Retract marks a release as withdrawn. The original claim and reviews remain
// visible in public history; deletion and revision are not possible.
func Retract(cur realm, releaseID int) string {
	r := lookup(releaseID)
	if r.Author != cur.Previous().Address() {
		panic("only the original publisher may retract")
	}
	if r.Retracted {
		panic("release already retracted")
	}
	r.Retracted = true
	return "release retracted, history retained"
}

// Count and Detail are read-only accessors for scripts and integrations.
func Count() int {
	return len(releases)
}

func Detail(releaseID int) string {
	r := lookup(releaseID)
	return describe(r)
}

// Render serves an entire live web interface through Gno.land's gnoweb.
// A path like /1 opens the full history for release #1.
func Render(path string) string {
	path = strings.TrimPrefix(path, "/")
	if path != "" {
		id, err := strconv.Atoi(path)
		if err != nil || id < 1 || id > len(releases) {
			return "# Release not found\n\n[Back to ReleaseTrail](.)"
		}
		return "# ReleaseTrail / Release #" + strconv.Itoa(id) + "\n\n" + describe(releases[id-1]) + "\n\n[Back to all releases](.)"
	}

	var out string
	out += "# ReleaseTrail\n\n"
	out += "**Ship with evidence. Verify with your wallet.**\n\n"
	out += "An open, on-chain public record of product releases, supporting evidence, independent reviews and retractions. No accounts, central database or proprietary API.\n\n"
	out += "## Registry at a glance\n\n"
	out += "| Releases | Independent verifications | Flags |\n| :--- | :--- | :--- |\n"
	out += "| **" + strconv.Itoa(len(releases)) + "** | **" + strconv.Itoa(reviewsCount) + "** | **" + strconv.Itoa(flagsCount) + "** |\n\n"
	out += "## Take action\n\n"
	out += "1. Open the **Actions** tab to call **Publish**, attaching an HTTPS link to a repository, changelog, audit or demo.\n"
	out += "2. As a different wallet, call **Review** with a release ID and `verify` or `flag`.\n"
	out += "3. The publisher may call **Retract**; their original record stays visible.\n\n"
	out += "**Important:** A verification is another wallet's opinion, not proof that an audit passed. Multiple wallets do not guarantee multiple people. Do not store private data.\n\n"
	out += "## Latest releases\n\n"
	if len(releases) == 0 {
		out += "No releases yet. Be the first to publish a product milestone.\n"
		return out
	}
	out += "| ID | Product | Version | Reviews | Status |\n| :--- | :--- | :--- | :--- | :--- |\n"
	start := len(releases) - 12
	if start < 0 {
		start = 0
	}
	for i := len(releases) - 1; i >= start; i-- {
		r := releases[i]
		status := "Active"
		if r.Retracted {
			status = "Retracted"
		}
		out += "| #" + strconv.Itoa(r.ID) + " | " + r.Project + " | " + r.Version + " | " + strconv.Itoa(r.Verified) + " verify / " + strconv.Itoa(r.Flagged) + " flag | " + status + " |\n"
	}
	out += "\nTo view a complete record, open the realm URL with `:" + "<release ID>" + "` after the realm path.\n"
	return out
}

func describe(r *Release) string {
	status := "Active"
	if r.Retracted {
		status = "Retracted - new reviews disabled"
	}
	var out string
	out += "## " + r.Project + " / " + r.Version + "\n\n"
	out += "**Status:** " + status + "\n\n"
	out += "**Published by:** `" + string(r.Author) + "`\n\n"
	out += "**Block height:** " + strconv.FormatInt(r.Height, 10) + "\n\n"
	out += "**Release notes:** " + r.Summary + "\n\n"
	out += "**Evidence:** [Open external evidence](" + r.Evidence + ")\n\n"
	out += "**Independent verifications:** " + strconv.Itoa(r.Verified) + "\n\n"
	out += "**Flags:** " + strconv.Itoa(r.Flagged) + "\n\n"
	out += "### Recent signed reviews\n\n"
	out += "| Wallet | Decision | Block |\n| :--- | :--- | :--- |\n"
	shown := 0
	for i := len(reviewRecords) - 1; i >= 0 && shown < 12; i-- {
		review := reviewRecords[i]
		if review.ReleaseID == r.ID {
			out += "| `" + string(review.Reviewer) + "` | " + review.Outcome + " | " + strconv.FormatInt(review.Height, 10) + " |\n"
			shown++
		}
	}
	if shown == 0 {
		out += "| - | No reviews yet | - |\n"
	}
	out += "\nEvidence is publisher-provided; reviews are pseudonymous wallet opinions. Claims are not independently validated by the contract.\n"
	return out
}

// Mutating entry points receive a runtime-created realm context.
// Immediate caller identity is taken from cur.Previous().Address(),
// not from a caller-supplied address. The cur.IsCurrent() assertion was
// redundant and is unavailable in some Playground VM builds.

func lookup(id int) *Release {
	if id < 1 || id > len(releases) {
		panic("release does not exist")
	}
	return releases[id-1]
}

// Prevent Markdown injection, HTML injection, line breaks and table delimiters.
func validText(s string, min int, max int) bool {
	if len(s) < min || len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			continue
		}
		if c == ' ' || c == '.' || c == ',' || c == ':' || c == ';' || c == '!' || c == '?' || c == '-' || c == '_' || c == '(' || c == ')' || c == '/' || c == '@' || c == '#' || c == '+' {
			continue
		}
		return false
	}
	return true
}

func validVersion(s string) bool {
	if len(s) < 1 || len(s) > maxVersionLength {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_' {
			continue
		}
		return false
	}
	return true
}

func validEvidenceURL(s string) bool {
	if !strings.HasPrefix(s, "https://") || len(s) < 12 || len(s) > maxEvidenceLength {
		return false
	}
	for i := 8; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			continue
		}
		if c == '/' || c == ':' || c == '.' || c == '-' || c == '_' || c == '?' || c == '=' || c == '&' || c == '%' || c == '#' || c == '~' || c == '+' {
			continue
		}
		return false
	}
	return true
}

// Package errata renders errata entries supplied by another package or realm.
package errata

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Entry describes an accepted correction. Link is the optional finder profile URL.
type Entry struct {
	Location string
	Text     string
	Finder   string
	FoundAt  int64
	Paid     int64
	Link     string
}

// RenderSection renders plain-text fields as a Markdown errata table.
func RenderSection(title string, entries []Entry) string {
	if strings.TrimSpace(title) == "" {
		title = "Errata"
	}
	var out strings.Builder
	out.WriteString("## " + sanitize.InlineText(title) + "\n\n")
	if len(entries) == 0 {
		out.WriteString("No errata yet.\n")
		return out.String()
	}

	out.WriteString("| Location | Correction | Finder | Height found | Paid |\n")
	out.WriteString("| --- | --- | --- | ---: | ---: |\n")
	for _, entry := range entries {
		finder := entry.Finder
		if sanitize.BechString(finder, "g") == finder && address(finder).IsValid() {
			finder = ShortAddr(finder)
		}
		finder = sanitize.TableCell(finder)
		if link := sanitize.URL(entry.Link); link != "" && finder != "" {
			finder = "[" + finder + "](" + link + ")"
		}
		out.WriteString(ufmt.Sprintf("| %s | %s | %s | %d | %s |\n",
			sanitize.TableCell(entry.Location), sanitize.TableCell(entry.Text),
			finder, entry.FoundAt, FormatUgnot(entry.Paid)))
	}
	return out.String()
}

// FormatUgnot displays both denominations using exact integer arithmetic.
func FormatUgnot(amount int64) string {
	const units = 1000000
	whole := strconv.FormatInt(amount/units, 10)
	fraction := amount % units
	if fraction < 0 {
		fraction = -fraction
		if amount > -units {
			whole = "-0"
		}
	}
	if fraction != 0 {
		digits := strconv.FormatInt(fraction, 10)
		digits = strings.Repeat("0", 6-len(digits)) + digits
		whole += "." + strings.TrimRight(digits, "0")
	}
	return ufmt.Sprintf("%s GNOT (%d ugnot)", whole, amount)
}

// ShortAddr abbreviates a display address, preserving its prefix and suffix.
func ShortAddr(addr string) string {
	runes := []rune(addr)
	if len(runes) <= 10 {
		return addr
	}
	return string(runes[:6]) + "…" + string(runes[len(runes)-4:])
}

package errata

import (
	"strings"
	"testing"
)

func TestFormatUgnot(t *testing.T) {
	tests := []struct {
		amount int64
		want   string
	}{
		{0, "0 GNOT (0 ugnot)"},
		{1, "0.000001 GNOT (1 ugnot)"},
		{2560000, "2.56 GNOT (2560000 ugnot)"},
		{2000000, "2 GNOT (2000000 ugnot)"},
		{-1, "-0.000001 GNOT (-1 ugnot)"},
		{-9223372036854775808, "-9223372036854.775808 GNOT (-9223372036854775808 ugnot)"},
	}
	for _, test := range tests {
		if got := FormatUgnot(test.amount); got != test.want {
			t.Errorf("FormatUgnot(%d) = %q, want %q", test.amount, got, test.want)
		}
	}
}

func TestShortAddr(t *testing.T) {
	if got := ShortAddr("g1abcdefghijklmnopqrstuvwxy"); got != "g1abcd…vwxy" {
		t.Errorf("unexpected abbreviated address: %q", got)
	}
	if got := ShortAddr("g1abcd"); got != "g1abcd" {
		t.Errorf("short address changed: %q", got)
	}
}

func TestRenderSection(t *testing.T) {
	if got := RenderSection("", nil); got != "## Errata\n\nNo errata yet.\n" {
		t.Errorf("unexpected empty section: %q", got)
	}
	entries := []Entry{
		{
			Location: "p. 42 | 43", Text: "*fix*\n[x](javascript:boom) <img>",
			Finder: "[reader]|test", FoundAt: 12, Paid: 2560000, Link: "javascript:boom",
		},
		{Location: "p. 50", Text: "Fix the example.", Finder: "reader",
			FoundAt: 13, Link: "/r/reader/errata/v0:finder/1"},
	}
	got := RenderSection("Errata\n# <unsafe>", entries)
	for _, want := range []string{"p\\. 42 \\| 43", "\\*fix\\*", "\\<img\\>",
		"2.56 GNOT (2560000 ugnot)", "[reader](/r/reader/errata/v0:finder/1)"} {
		if !strings.Contains(got, want) {
			t.Errorf("table missing %q in %q", want, got)
		}
	}
	for _, unwanted := range []string{"\n# <unsafe>", "[x](javascript:", "](javascript:", "<img>"} {
		if strings.Contains(got, unwanted) {
			t.Errorf("unsafe content %q in %q", unwanted, got)
		}
	}
	if lines := strings.Count(got, "\n"); lines != 6 {
		t.Errorf("expected one line per table row, got %d lines in %q", lines, got)
	}
}

// Tavern Poll — chain-on-chain voting realm
// Path: gno.land/r/g1rkauqxnulyry8h4p7epqmxr3a744gg4hchhvz2/tavernpoll
package tavernpoll

import (
	"sort"
	"strconv"
	"strings"
)

type PollOption struct {
	Option string
	Votes  int
}

type pollOptSorter []PollOption
func (s pollOptSorter) Len() int           { return len(s) }
func (s pollOptSorter) Less(i, j int) bool { return s[i].Votes > s[j].Votes }
func (s pollOptSorter) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

type Poll struct {
	ID        string
	Question  string
	Options   []PollOption
	Voters    []string
	Creator   string
	CreatedAt string
	Active    bool
}

var (
	polls []Poll
	seq   int
)

func findIdx(id string) int {
	for i := range polls {
		if polls[i].ID == id {
			return i
		}
	}
	return -1
}

// CreatePoll(cur realm, question, opts) string — opts is comma-separated
func CreatePoll(cur realm, question string, opts string) string {
	if question == "" {
		return "error: empty question"
	}
	raw := strings.Split(opts, ",")
	if len(raw) < 2 {
		return "error: need 2+ comma-separated options"
	}
	seq++
	id := "poll_" + strconv.Itoa(seq)
	options := make([]PollOption, 0, len(raw))
	for _, o := range raw {
		t := strings.TrimSpace(o)
		if t != "" {
			options = append(options, PollOption{Option: t, Votes: 0})
		}
	}
	if len(options) < 2 {
		return "error: need 2+ non-empty options"
	}
	creator := string(cur.Address())
	polls = append(polls, Poll{
		ID: id, Question: question, Options: options,
		Voters: nil, Creator: creator, CreatedAt: "block #0", Active: true,
	})
	return id
}

// Vote(cur realm, pollID, optionIndex) string
func Vote(cur realm, pollID string, optionIndex int) string {
	idx := findIdx(pollID)
	if idx < 0 {
		return "error: poll not found: " + pollID
	}
	if !polls[idx].Active {
		return "error: poll closed"
	}
	if optionIndex < 0 || optionIndex >= len(polls[idx].Options) {
		return "error: bad option index"
	}
	voter := string(cur.Address())
	for _, v := range polls[idx].Voters {
		if v == voter {
			return "error: already voted"
		}
	}
	polls[idx].Options[optionIndex].Votes++
	polls[idx].Voters = append(polls[idx].Voters, voter)
	return "voted!"
}

// ClosePoll(cur realm, pollID) string
func ClosePoll(cur realm, pollID string) string {
	idx := findIdx(pollID)
	if idx < 0 {
		return "error: poll not found"
	}
	if polls[idx].Creator != string(cur.Address()) {
		return "error: not creator"
	}
	polls[idx].Active = false
	return "closed: " + pollID
}

// GetPollJSON(pollID) string — hand-written JSON, because Gno stdlib 1.8.0 has no encoding/json
func GetPollJSON(pollID string) string {
	idx := findIdx(pollID)
	if idx < 0 {
		return "{\"error\":\"poll not found\"}"
	}
	p := &polls[idx]
	var sb strings.Builder
	sb.WriteString("{\"id\":\"")
	sb.WriteString(p.ID)
	sb.WriteString("\",\"question\":\"")
	sb.WriteString(p.Question)
	sb.WriteString("\",\"creator\":\"")
	sb.WriteString(p.Creator)
	sb.WriteString("\",\"active\":")
	sb.WriteString(strconv.FormatBool(p.Active))
	sb.WriteString(",\"options\":[")
	for i, o := range p.Options {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString("{\"option\":\"")
		sb.WriteString(o.Option)
		sb.WriteString("\",\"votes\":")
		sb.WriteString(strconv.Itoa(o.Votes))
		sb.WriteString("}")
	}
	sb.WriteString("]}")
	return sb.String()
}

// ListPollsJSON() string
func ListPollsJSON() string {
	var sb strings.Builder
	sb.WriteString("[")
	first := true
	for i := range polls {
		if !first {
			sb.WriteString(",")
		}
		first = false
		p := &polls[i]
		sb.WriteString("{\"id\":\"")
		sb.WriteString(p.ID)
		sb.WriteString("\",\"question\":\"")
		sb.WriteString(p.Question)
		sb.WriteString("\",\"creator\":\"")
		sb.WriteString(p.Creator)
		sb.WriteString("\",\"active\":")
		sb.WriteString(strconv.FormatBool(p.Active))
		sb.WriteString(",\"options\":[")
		for j, o := range p.Options {
			if j > 0 {
				sb.WriteString(",")
			}
			sb.WriteString("{\"option\":\"")
			sb.WriteString(o.Option)
			sb.WriteString("\",\"votes\":")
			sb.WriteString(strconv.Itoa(o.Votes))
			sb.WriteString("}")
		}
		sb.WriteString("]}")
	}
	sb.WriteString("]")
	return sb.String()
}

// GetPoll(pollID) string — plain text
func GetPoll(pollID string) string {
	idx := findIdx(pollID)
	if idx < 0 {
		return "not found"
	}
	p := &polls[idx]
	var sb strings.Builder
	sb.WriteString(p.ID)
	sb.WriteString(": ")
	sb.WriteString(p.Question)
	sb.WriteString(" [")
	sb.WriteString(p.Creator)
	sb.WriteString("]")
	return sb.String()
}

// ListPolls() string — plain text
func ListPolls() string {
	if len(polls) == 0 {
		return "No polls yet."
	}
	var sb strings.Builder
	for _, p := range polls {
		sb.WriteString("[")
		sb.WriteString(p.ID)
		sb.WriteString("] ")
		sb.WriteString(p.Question)
		sb.WriteString("\n")
	}
	return sb.String()
}

// Render(path) string — gnoweb
func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("<!doctype html><html><head><title>Tavern Poll</title></head><body>")
	sb.WriteString("<h1>🍺 Tavern Poll</h1>")
	sb.WriteString("<p>On-chain voting at the Gnome Tavern.</p>")
	if len(polls) == 0 {
		sb.WriteString("<p>No polls yet.</p>")
	} else {
		sb.WriteString("<ul>")
		for _, p := range polls {
			sorted := make([]PollOption, len(p.Options))
			copy(sorted, p.Options)
			sort.Sort(pollOptSorter(sorted))
			status := "open"
			if !p.Active {
				status = "closed"
			}
			sb.WriteString("<li><b>")
			sb.WriteString(p.Question)
			sb.WriteString("</b> (")
			sb.WriteString(status)
			sb.WriteString(") by ")
			sb.WriteString(p.Creator)
			sb.WriteString("<ul>")
			for _, o := range sorted {
				sb.WriteString("<li>")
				sb.WriteString(o.Option)
				sb.WriteString(" - ")
				sb.WriteString(strconv.Itoa(o.Votes))
				sb.WriteString("</li>")
			}
			sb.WriteString("</ul></li>")
		}
		sb.WriteString("</ul>")
	}
	sb.WriteString("</body></html>")
	return sb.String()
}

package ember

import (
	"chain"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const StarterAmount int64 = 100

var (
	token *grc20.Token
	ledger *grc20.PrivateLedger
	claimed avl.Tree
)

func init(cur realm) {
	token, ledger = grc20.NewToken("Hearthboard Ember", "EMBER", 0, 0, cur)
	grc20reg.Register(cross(cur), token, "")
}

func ClaimStarter(cur realm) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("use a direct wallet call")
	}
	owner := caller.Address()
	if ClaimedStarter(owner) {
		panic("starter EMBER already claimed")
	}
	check(ledger.Mint(owner, StarterAmount))
	claimed.Set(owner.String(), true)
	chain.Emit("StarterClaimed", "owner", owner.String())
}

func ClaimedStarter(owner address) bool { return claimed.Has(owner.String()) }
func BalanceOf(owner address) int64 { return token.BalanceOf(owner) }
func TotalSupply() int64 { return token.TotalSupply() }
func Allowance(owner, spender address) int64 { return token.Allowance(owner, spender) }

func Transfer(cur realm, to address, amount int64) {
	check(ledger.CallerTeller().Transfer(0, cur, to, amount))
}

func Approve(cur realm, spender address, amount int64) {
	check(ledger.CallerTeller().Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, from, to address, amount int64) {
	check(ledger.CallerTeller().TransferFrom(0, cur, from, to, amount))
}

func Render(path string) string {
	if path == "" {
		return "# Hearthboard Ember\n\nEMBER is a whole-unit GRC20 test token for quest bounties and tips. It has no monetary value.\n\n" +
			ufmt.Sprintf("**Supply:** %d EMBER · **Starter grant:** %d EMBER once per wallet.\n", TotalSupply(), StarterAmount)
	}
	if strings.HasPrefix(path, "balance/") {
		owner := strings.TrimPrefix(path, "balance/")
		if len(owner) == 40 && strings.HasPrefix(owner, "g1") {
			return ufmt.Sprintf("**Balance:** %d EMBER\n", BalanceOf(address(owner)))
		}
	}
	return "No such token page."
}

func check(err error) {
	if err != nil { panic(err.Error()) }
}

package cutpurse

import (
	"chain"
	"chain/banker"
)

// CreateJob opens a job and seats the creator (seat 0).
func CreateJob(cur realm, name string, fee int64) int64 {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	if _, busy := active[who]; busy {
		panic(ErrSameJob)
	}
	if liveCount >= LiveJobsMax {
		panic(ErrTooManyLive)
	}
	if fee < 0 {
		panic(ErrBadFee)
	}

	f := clampFee(fee)
	nm := cleanName(name)
	height := mustHeight()

	payIn(cur, f)

	id := nextID
	nextID++

	j := &Job{
		ID:       id,
		Name:     nm,
		Creator:  who,
		Fee:      f,
		Pot:      f,
		Phase:    PhaseOpen,
		Deadline: height + JoinBlocks,
		Traitor:  -1,
		OpenedAt: height,
	}
	j.Seats[0] = Seat{Addr: who}
	j.NSeats = 1

	jobs[id] = j
	active[who] = id
	liveCount++

	return id
}

// JoinJob seats the caller in an open job.
func JoinJob(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)

	if j.Phase != PhaseOpen {
		panic(ErrBadPhase)
	}
	if mustHeight() > j.Deadline {
		panic(ErrDeadlinePassed)
	}
	if j.NSeats >= Seats {
		panic(ErrFull)
	}
	if seatOf(j, who) >= 0 {
		panic(ErrAlreadySeated)
	}
	if _, busy := active[who]; busy {
		panic(ErrSameJob)
	}
	if j.Pot+j.Fee > int64(MaxFee*Seats) {
		panic(ErrPotCap)
	}

	payIn(cur, j.Fee)

	j.Seats[j.NSeats] = Seat{Addr: who}
	j.NSeats++
	j.Pot += j.Fee
	active[who] = id
}

// Kick drops a seat during Open and refunds that seat's fee (creator only).
func Kick(cur realm, id int64, seat int8) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)

	if j.Creator != who {
		panic(ErrNotCreator)
	}
	if j.Phase != PhaseOpen {
		panic(ErrBadPhase)
	}
	if seat < 0 || int(seat) >= int(j.NSeats) {
		panic(ErrNotSeated)
	}

	idx := int(seat)
	kicked := j.Seats[idx]
	for i := idx; i < int(j.NSeats)-1; i++ {
		j.Seats[i] = j.Seats[i+1]
	}
	j.Seats[j.NSeats-1] = Seat{}
	j.NSeats--
	j.Pot -= j.Fee
	delete(active, kicked.Addr)

	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), kicked.Addr, chain.NewCoins(chain.NewCoin(Denom, j.Fee)))
}

// Start moves an open job into round 1 (creator only).
func Start(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	j := mustJob(id)

	if j.Creator != here(cur) {
		panic(ErrNotCreator)
	}
	if j.Phase != PhaseOpen {
		panic(ErrBadPhase)
	}
	if j.NSeats < 2 {
		panic(ErrNotReady)
	}

	j.Phase = PhaseCommit
	j.Round = 1
	j.Deadline = mustHeight() + CommitBlocks
}

// Commit stores the caller's sealed choice hash for the current round.
func Commit(cur realm, id int64, hash string) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)
	idx := seatOf(j, who)

	if idx < 0 {
		panic(ErrNotSeated)
	}
	if j.Phase != PhaseCommit {
		panic(ErrBadPhase)
	}
	if mustHeight() > j.Deadline {
		panic(ErrDeadlinePassed)
	}
	if j.Seats[idx].Committed {
		panic(ErrAlreadyComitted)
	}
	if !isHex64(hash) {
		panic(ErrBadHash)
	}

	j.Seats[idx].Committed = true
	j.Seats[idx].CommitHash = hash

	if countCommitted(j) == int(j.NSeats) {
		closeCommitRound(j)
	}
}

// Reveal opens the caller's sealed choice and applies nothing yet.
func Reveal(cur realm, id int64, action uint8, salt string) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)
	idx := seatOf(j, who)

	if idx < 0 {
		panic(ErrNotSeated)
	}
	if j.Phase != PhaseReveal {
		panic(ErrBadPhase)
	}
	if mustHeight() > j.Deadline {
		panic(ErrDeadlinePassed)
	}
	if j.Seats[idx].Action != ActNone {
		panic(ErrAlreadyComitted)
	}
	if !j.Seats[idx].Committed {
		// §8: an uncommitted reveal is a hash mismatch, not a readiness error
		panic(ErrHashMismatch)
	}
	if action < uint8(ActScout) || action > uint8(ActWatch) {
		panic(ErrBadAction)
	}
	if !validSalt(salt) {
		panic(ErrBadSalt)
	}
	if commitHash(j.ID, action, salt, who.String(), j.Round) != j.Seats[idx].CommitHash {
		panic(ErrHashMismatch)
	}

	j.Seats[idx].Action = Action(action)
	j.Seats[idx].Auto = false

	if countRevealed(j) == int(j.NSeats) {
		closeRevealRound(j, false)
	}
}

package cutpurse

import (
	"chain"
	"strings"
	"testing"
)

// Guard coverage note (§10 R3).
//
// A crossing call must be written `f(cur)` or `f(cross(rlm))`, and cross()
// validates the realm pointer before the body runs — so an outside caller can
// never hand a mutator a bad realm. The `if !cur.IsCurrent()` guard therefore
// protects against *stale captures* inside the realm (the case the banker
// stdlib docs warn about). What is assertable here is the predicate plus the
// fact that the live-cur path clears every mutator.

func TestStaleRealmIsNotCurrent(cur realm, t *testing.T) {
	if !cur.IsCurrent() {
		t.Fatal("the injected cur must be current")
	}
	if cur.Previous().IsCurrent() {
		t.Fatal("a previous realm must not report IsCurrent")
	}
}

func TestMutatorsRunOnLiveCur(cur realm, t *testing.T) {
	testing.SetHeight(700)
	actor := address("g1guard")
	testing.SetOriginCaller(actor)
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(Denom, MinFee)))

	id := CreateJob(cur, "guard", MinFee)
	if _, ok := jobView(id); !ok {
		t.Fatal("CreateJob must work on the live cur")
	}

	testing.SetOriginCaller(address("g1guard2"))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(Denom, MinFee)))
	JoinJob(cur, id)

	testing.SetOriginCaller(actor)
	testing.SetOriginSend(chain.NewCoins())
	Start(cur, id)
	Tick(cur, id) // inside the commit deadline: no-op, must not panic

	jv, _ := jobView(id)
	if jv.Phase != uint8(PhaseCommit) || jv.NSeats != 2 {
		t.Fatalf("expected an open commit round with 2 seats, got phase %d nseats %d", jv.Phase, jv.NSeats)
	}
}

// seed() fills the globals directly (no caller realm needed) so render probes
// can address a realistic board. Idempotent.
func seed() {
	if len(jobs) > 0 {
		return
	}
	hostile := "a|b *c* _d_ `e` <gno-x> [f](g) " + strings.Repeat("z", 30)
	who0 := address("g1qrmldr7hh985wngaklzfkzlt588z4gewtlgwg0")
	other := address("g1seedother")

	for i := int64(0); i < 9; i++ {
		j := &Job{
			ID:       i,
			Name:     hostile,
			Creator:  who0,
			Fee:      MinFee,
			Pot:      MinFee * 4,
			Phase:    PhaseCommit,
			Round:    2,
			Deadline: 900,
			Alarm:    i % 4,
			Loot:     12,
			Secured:  4,
			Traitor:  1,
			OpenedAt: 100,
		}
		j.NSeats = 4
		for s := 0; s < 4; s++ {
			j.Seats[s] = Seat{Addr: who0, Committed: true, CommitHash: hostile}
			if s%2 == 1 {
				j.Seats[s].Addr = other
				j.Seats[s].Action = Action(1 + s%4)
				j.Seats[s].Contribution = 3
			}
		}
		jobs[i] = j
		active[j.Seats[0].Addr] = i
	}
	nextID = 9
	liveCount = 9
}

