package cutpurse

// render_job.gno — the job. Pot, alarm, seats, and exactly one control panel
// for the phase the job is in. Every panel says what the button does to
// your money before you press it.

import (
	"strconv"
	"strings"
)

// renderJobPath routes job/<id>, job/<id>/<you>, and the commit and reveal
// steps under them. j/<id> is the same page.
func renderJobPath(parts []string) string {
	if len(parts) < 2 {
		return renderMissing("job")
	}
	id := atoiOr(parts[1], -1)
	if id < 0 {
		return renderMissing(text(parts[1]))
	}
	at := 2
	you := ""
	if len(parts) > 2 && address(parts[2]).IsValid() {
		you = parts[2]
		at = 3
	}
	if len(parts) <= at {
		parts = append(parts, "")
	}
	rest := parts[at:]
	jv, ok := jobView(id)
	if !ok {
		return pageHead("No such job", "Nothing has been opened under "+
			"`"+strconv.FormatInt(id, 10)+"`.", "Home", hub) +
			notice("WARNING", "Job not found", "") +
			"Try " + md("the board", self("jobs")) + ".\n"
	}
	switch {
	case rest[0] == "":
		return renderJob(jv, you)
	case rest[0] == "commit" && len(rest) == 1:
		return renderCommitChoose(jv, you)
	case rest[0] == "commit":
		return renderCommitHash(jv, you, uint8(atoiOr(rest[1], 1)))
	case rest[0] == "reveal":
		return renderReveal(jv, you)
	}
	return renderJob(jv, you)
}

// ----- the job page -----

func renderJob(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(pageHeadBare(jobTitle(jv),
		"Job "+strconv.FormatInt(jv.ID, 10)+" · "+phaseBadge(jv.Phase)+roundLabel(jv)))

	if jv.Phase >= uint8(PhaseSettled) {
		b.WriteString(endBody(jv, you))
		return b.String()
	}

	// The numbers a player judges, in one line while the round is running —
	// three picture cards are wasted gas there. Cards stay on the open page,
	// where the join decision is the whole screen.
	if jv.Phase == 0 {
		b.WriteString(cards(
			"**Pot**\n\n"+coins(jv.Pot)+"\n\nSeat fee "+money(jv.Fee)+" GNOT",
			"**Seats**\n\n"+seatStrip(int64(jv.NSeats))+"\n\n"+
				strconv.FormatInt(int64(jv.NSeats), 10)+" of 4 filled",
			"**Clock**\n\n"+clockCell(jv)+"\n\nOn alarm "+alarmMeter(jv.Alarm),
		))
		b.WriteString("\n")
	} else {
		b.WriteString(jobFacts(jv))
		b.WriteString(phaseBanner(jv))
	}

	b.WriteString(traitorPanel(jv))
	b.WriteString(seatTable(jv, you))
	arch, settled := Archived(jv.ID)
	b.WriteString(controlPanel(jv, you, settled, arch))
	b.WriteString(nav("The board", self("jobs"), "Home", self("")))
	return b.String()
}

// jobFacts is the one-line state of a running job: pot, fee, seats, clock,
// alarm. Cheaper than three cards and hard to read past, which is what a
// player in a timed round wants.
func jobFacts(jv JobView) string {
	return "Round " + strconv.FormatInt(int64(jv.Round), 10) + "/3 · pot " + coins(jv.Pot) +
		" · " + seatStrip(int64(jv.NSeats)) + " " +
		strconv.FormatInt(int64(jv.NSeats), 10) + "/4 · " + clockCell(jv) + " · " +
		alarmBars(jv.Alarm) + " · " + money(jv.Secured) + " GNOT secured\n\n"
}

// ----- the two end states -----

// endBody is the job after the last round: verdict, then the money, then who
// took what. The three grey cards go away here — the verdict is the number.
func endBody(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(endVerdict(jv))
	b.WriteString(takeCards(jv))
	b.WriteString(scoreboard(jv, you))
	arch, _ := Archived(jv.ID)
	b.WriteString(controlPanel(jv, you, jv.Settled, arch))
	b.WriteString(nav("The board", self("jobs"), "Every settled job", self("ledger")))
	return b.String()
}

// endVerdict is the loudest block on the site: who did it, and what it cost.
// Money is written plainly here — coins() already bolds, and bolding a bold
// reads as a mistake.
func endVerdict(jv JobView) string {
	snitch, _, snitchPaid := snitchFacts(jv)
	if jv.Alarm >= alarmTotal {
		// Heading, then exactly one sentence of explanation, then the cost.
		// A stranger has to get the mechanic from that sentence alone.
		body := "### 🐀 Busted\n\n"
		if snitch >= 0 {
			body += "**Seat " + strconv.FormatInt(int64(snitch)+1, 10) + " was the snitch.** " +
				payoffLine(jv, snitch, snitchPaid) + " They walk.\n\n"
		} else {
			body += "The door slammed at round " + strconv.FormatInt(int64(jv.Round), 10) + ".\n\n"
		}
		if jv.Secured == 0 {
			body += "**Nothing reached the door.** " + money(bustedLost(jv)) +
				" GNOT stayed on the shelf of a " + money(jv.Pot) + " GNOT pot.\n"
		} else {
			body += "What reached the door survives: **" + money(jv.Secured) + " GNOT**. " +
				money(bustedLost(jv)) + " GNOT stayed on the shelf.\n"
		}
		return frame(body) + "\n"
	}

	body := "### Escaped\n\n"
	if snitch >= 0 {
		body += "**Seat " + strconv.FormatInt(int64(snitch)+1, 10) + " was the snitch** — and got " +
			"away with it: on an escape they take nothing extra, the same share as everyone.\n\n"
	}
	if jv.Secured == 0 {
		body += "Three rounds cleared and the alarm never reached 3, but nothing was carried " +
			"out — the pot still splits.\n\n"
	} else {
		body += "Three rounds cleared, alarm never reached 3. **" + money(jv.Secured) +
			" GNOT** walked out the door.\n\n"
	}
	body += "The remainder split by contribution below. It could have been worse.\n"
	return frame(body) + "\n"
}

// payoffLine is the snitch's payoff in one sentence, pitched at someone who has
// never played. The contrast does the teaching: the 60% is only outrageous when
// it is set against what that seat actually did.
func payoffLine(jv JobView, seat int, paid int64) string {
	shares := payoutShares(jv)
	rank, didLeast := 1, true
	for i := range jv.Seats {
		if i == seat {
			continue
		}
		if shares[i] >= shares[seat] {
			rank++
		}
		if jv.Seats[i].Contribution < jv.Seats[seat].Contribution {
			didLeast = false
		}
	}
	amount := money(paid) + " GNOT"
	switch {
	case rank == 1 && didLeast:
		return "A bust pays the snitch 60% of the pot: " + amount +
			", taken before the crew is paid, from the seat that did the least."
	case rank == 1:
		return "A bust pays the snitch 60% of the pot: " + amount +
			", before the crew is paid — more than any seat that worked for it."
	case didLeast:
		return "A bust pays the snitch 60% of the pot: " + amount +
			", before the crew is paid, more than the seat that did most."
	}
	return "A bust pays the snitch 60% of the pot: " + amount + ", before the crew is paid at all."
}

// bustedLost is loot that never reached the door.
func bustedLost(jv JobView) int64 {
	if jv.Loot <= jv.Secured {
		return 0
	}
	return jv.Loot - jv.Secured
}

// takeCards is the money, split into the three places it went. On a bust the
// 60% is the story; on an escape the treasury cut is, because the snitch took
// nothing extra there.
func takeCards(jv JobView) string {
	shares := payoutShares(jv)
	if jv.Alarm >= alarmTotal {
		var snitchGet, crewGet int64
		for i, v := range shares {
			if i == int(jv.Traitor) {
				snitchGet += v
				continue
			}
			crewGet += v
		}
		return cards(
			"**The pot**\n\n"+coins(jv.Pot)+"\n\nthe whole stake",
			"**To the snitch**\n\n"+coins(snitchGet)+"\n\n60%, plus their split",
			"**To the crew**\n\n"+coins(crewGet)+"\n\nwhat is left",
		) + "\n"
	}

	var split int64
	for _, v := range shares {
		split += v
	}
	return cards(
		"**The pot**\n\n"+coins(jv.Pot)+"\n\nthe whole stake",
		"**To the treasury**\n\n"+coins(treasuryCut(jv))+"\n\n5%, scaled by what was secured",
		"**Split by contribution**\n\n"+coins(split)+"\n\nbetween all seats",
	) + "\n"
}

// scoreboard ranks the crew by what they took. The snitch is first, because
// the pot always pays them most — that is the point of the game.
func scoreboard(jv JobView, you string) string {
	shares := payoutShares(jv)
	order := make([]int, len(jv.Seats))
	for i := range order {
		order[i] = i
	}
	for i := 1; i < len(order); i++ {
		for k := i; k > 0 && shares[order[k]] > shares[order[k-1]]; k-- {
			order[k], order[k-1] = order[k-1], order[k]
		}
	}

	var b strings.Builder
	b.WriteString("## What everyone took\n\n")
	b.WriteString("| Seat | Player | Pick | Contribution | Took |\n|---:|---|---|---:|---:|\n")
	for _, i := range order {
		seat := jv.Seats[i]
		mark := ""
		if i == int(jv.Traitor) {
			mark = " 🐀"
		}
		pick := actionCell(seat.Action)
		if seat.Auto {
			pick += " `auto`"
		}
		b.WriteString("| " + strconv.Itoa(i+1) + mark + " | " + who(seat.Addr.String()) +
			youMark(seat.Addr.String(), you) + " | " + pick + " | " +
			strconv.FormatInt(seat.Contribution, 10) + " | **" + money(shares[i]) + "** |\n")
	}
	b.WriteString("\nPaid by contribution, remainder to the top contributor. ")
	if jv.Traitor >= 0 {
		b.WriteString("The 🐀 seat is the snitch.")
	}
	b.WriteString("\n\n")
	return b.String()
}

// snitchFacts is the snitch seat, how to describe them, and what they take.
func snitchFacts(jv JobView) (seat int, where string, paid int64) {
	seat = int(jv.Traitor)
	if seat < 0 || seat >= len(jv.Seats) {
		return -1, "", 0
	}
	where = "sealed at the close of round one"
	if jv.Round > 1 {
		where = "the crew never suspected"
	}
	if jv.Alarm >= alarmTotal {
		paid = jv.Pot * TraitorBustShare / 100
	}
	return seat, where, paid
}

// phaseBanner is only for the deadline running out. The round facts live in the
// one-line jobFacts above it; a second block repeating them is gas for nothing.
func phaseBanner(jv JobView) string {
	if jv.Deadline > jv.Height {
		return ""
	}
	return notice("CAUTION", "Deadline passed — nudge the clock",
		"The next phase is one Tick away. Anyone can send it and it pays nothing.")
}

// traitorPanel holds the snitch shut until the end states name them.
func traitorPanel(jv JobView) string {
	if jv.Round < 1 {
		return ""
	}
	return "🐀 **The snitch is among you** " + segLocked + " " + segLocked + " " + segLocked + " " +
		segLocked + "\n\n" +
		"One seat is on the take. A bust pays it 60% of the pot; a clean escape pays it nothing " +
		"extra — so the snitch wants the alarm, and you cannot see who does. Sealed from round " +
		"one out of every commit hash, and nobody sets it.\n\n"
}

// seatTable is the crew, in seat order.
func seatTable(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString("## The crew\n\n")
	if len(jv.Seats) == 0 {
		b.WriteString(notice("NOTE", "Empty cellar. No one has taken a seat.", "") + "\n")
		return b.String()
	}
	b.WriteString("| Seat | Player | This round | Contribution |\n|---:|---|---|---:|\n")
	for i, seat := range jv.Seats {
		b.WriteString("| " + strconv.Itoa(i+1) + " | " + who(seat.Addr.String()) + youMark(seat.Addr.String(), you) +
			" | " + seatState(jv, seat) + " | " + strconv.FormatInt(seat.Contribution, 10) + " |\n")
	}
	b.WriteString("\nContribution is what the payout splits by. " + md("How that works", self("rules")) + ".\n\n")
	return b.String()
}

// seatState never leaks a pick before the reveal.
func seatState(jv JobView, seat SeatView) string {
	if jv.Revealed && seat.Revealed {
		s := actionCell(seat.Action)
		if seat.Auto {
			s += " `auto`"
		}
		return s
	}
	if seat.Committed {
		return icon("lock", "committed")
	}
	if jv.Phase == 1 || jv.Phase == 2 {
		return "▪"
	}
	return "—"
}

// roundLabel is the round in a page header; an open job has none yet.
func roundLabel(jv JobView) string {
	if jv.Phase == 0 || jv.Round == 0 {
		return " · seats filling"
	}
	return " · round " + strconv.FormatInt(int64(jv.Round), 10) + "/" +
		strconv.FormatInt(Rounds, 10)
}

// ----- controls -----

func controlPanel(jv JobView, you string, settled bool, arch Result) string {
	var b strings.Builder
	b.WriteString("## " + panelTitle(jv) + "\n\n")
	switch {
	case jv.Phase == 0:
		b.WriteString(joinPanel(jv))
		b.WriteString(kickPanel(jv))
		b.WriteString(startPanel(jv))
	case jv.Phase == 1:
		b.WriteString("Your pick stays hidden: the page hashes it and signs only the hash. " +
			"Keep the salt it hands back — without it the pick cannot be revealed.\n\n")
		b.WriteString(stepButtons(jv, you, "Commit your pick", "commit/"))
	case jv.Phase == 2:
		b.WriteString(notice("CAUTION", "Reveal or lose the pick",
			"An unrevealed pick counts as "+actionCell(4)+", earns nothing and costs a reputation point."))
		b.WriteString(stepButtons(jv, you, "Reveal", "reveal"))
	case jv.Phase >= 3:
		b.WriteString(settlePanel(jv, settled, arch))
	}
	b.WriteString(tickPanel(jv))
	return b.String()
}

func panelTitle(jv JobView) string {
	switch jv.Phase {
	case 1:
		return "Your pick"
	case 2:
		return "Reveal"
	case 3, 4:
		if jv.Settled {
			return "Settled"
		}
		return "The pot"
	}
	return "Take a seat"
}

// seatLink is the viewer's own view of the job, so a form can name its seat.
func seatLink(jv JobView, you, suffix string) string {
	p := "job/" + strconv.FormatInt(jv.ID, 10) + "/"
	if you != "" {
		p += you + "/"
	}
	return self(p + suffix)
}

// stepButtons sends the viewer to the commit chooser or the reveal form.
func stepButtons(jv JobView, you string, label, sub string) string {
	if jv.Deadline <= jv.Height {
		return "Deadline passed — " + md("Tick it first", seatLink(jv, you, "")) + ".\n\n"
	}
	b := button(label, seatLink(jv, you, sub), "")
	if you == "" {
		b += "\n\n" + md("Open your own seat view", seatLink(jv, you, "")) +
			" first if the next page cannot find your seat — it reads your address from the URL."
	}
	return b + "\n\n"
}

// joinPanel is the join form, or why you cannot join.
func joinPanel(jv JobView) string {
	var b strings.Builder
	if int(jv.NSeats) >= seatTotal {
		b.WriteString(notice("NOTE", "Full. Four seats, all taken.", "Watch this page: a kick frees one."))
		return b.String()
	}
	b.WriteString("Joining puts up " + coins(jv.Fee) + " of your own, into escrow. " +
		"A seat you take is seat " + strconv.FormatInt(int64(jv.NSeats)+1, 10) + ".\n\n")
	b.WriteString("<gno-form exec=\"JoinJob\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	return b.String()
}

// kickPanel lets only the creator prune seats while the job is open.
func kickPanel(jv JobView) string {
	if jv.Phase != 0 || len(jv.Seats) < 2 {
		return ""
	}
	var b strings.Builder
	b.WriteString("<gno-form exec=\"Kick\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	for i, seat := range jv.Seats {
		b.WriteString(selectOpt("seat", strconv.Itoa(i), short(seat.Addr.String()), i == len(jv.Seats)-1))
	}
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Creator only. A kicked seat is refunded in full, immediately._\n\n")
	return b.String()
}

// startPanel is the creator's go signal, once two seats are filled.
func startPanel(jv JobView) string {
	if int(jv.NSeats) < 2 {
		return notice("NOTE", "One player is not a job",
			"Seats fill for now. Send this page's link to a second wallet; Start appears at two.")
	}
	var b strings.Builder
	b.WriteString("<gno-form exec=\"Start\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Creator only. This closes the seats and opens round one. Empty seats stay empty._\n\n")
	return b.String()
}

// settlePanel is the permissionless settle, plus the split it will pay. Once
// the job is archived the form and the summary both go: the receipt replaces
// them, and a second send would only panic.
func settlePanel(jv JobView, settled bool, arch Result) string {
	var b strings.Builder
	if settled {
		b.WriteString(notice("SUCCESS", "Settled in block "+strconv.FormatInt(arch.At, 10),
			"Settled once, permanently — the pot cannot move again. "+
				md("Entry "+strconv.FormatInt(jv.ID, 10), self("ledger/1"))+" is the record."))
		if arch.Payouts != "" {
			b.WriteString("The realm logged the send: `" + arch.Payouts + "`\n\n")
		}
		return b.String()
	}

	if jv.Alarm >= alarmTotal {
		b.WriteString("Pot " + coins(jv.Pot) + " · 60% to the snitch · the rest by contribution.\n\n")
	} else {
		b.WriteString("Pot " + coins(jv.Pot) + " · " + money(treasuryCut(jv)) +
			" GNOT to the treasury (5%) · the rest by contribution.\n\n")
	}
	b.WriteString("<gno-form exec=\"Settle\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_The pot is still here. Anyone may settle, once._\n\n")
	return b.String()
}

// tickPanel is the clock nudge, shown whenever a deadline has passed.
func tickPanel(jv JobView) string {
	if jv.Phase == 0 || jv.Phase >= 3 || jv.Deadline > jv.Height {
		return ""
	}
	var b strings.Builder
	b.WriteString("### The clock stopped\n\n")
	b.WriteString("<gno-form exec=\"Tick\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Permissionless. Carries the job to its next phase and pays nothing._\n\n")
	return b.String()
}

// payoutShares mirrors Settle exactly — same pool, same order of operations,
// same remainder rule — because a preview that disagrees with the chain is a
// lie on a page whose whole purpose is trust. The pool is the POT on both
// outcomes; a bust reserves 60% for the snitch, an escape a scaled 5% for the
// treasury. Returns all-zero when the realm would pay nothing.
func payoutShares(jv JobView) []int64 {
	shares := make([]int64, len(jv.Seats))
	if len(shares) == 0 || jv.Pot <= 0 {
		return shares
	}
	if jv.Alarm >= alarmTotal {
		share := jv.Pot * TraitorBustShare / 100
		if int(jv.Traitor) >= 0 && int(jv.Traitor) < len(shares) {
			shares[int(jv.Traitor)] = share
			splitShares(jv, jv.Pot-share, shares)
		} else {
			splitShares(jv, jv.Pot, shares)
		}
		return shares
	}
	splitShares(jv, jv.Pot-treasuryCut(jv), shares)
	return shares
}

// treasuryCut is the escape cut exactly as Settle computes it: Secured scaled
// against the best possible secure, so 5% of the pot is 5% of the pot.
func treasuryCut(jv JobView) int64 {
	if jv.Pot <= 0 {
		return 0
	}
	cut := jv.Pot * jv.Secured * TreasuryBps / (10000 * MaxSecured)
	if cut > jv.Pot {
		return jv.Pot
	}
	return cut
}

// splitShares is splitByContribution over a view: contribution-weighted, the
// remainder to the top contributor, an even split when nobody contributed.
func splitShares(jv JobView, amount int64, shares []int64) {
	n := len(shares)
	if amount <= 0 || n == 0 {
		return
	}
	var total int64
	top := 0
	for i := 0; i < n; i++ {
		c := jv.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		total += c
		if c > jv.Seats[top].Contribution {
			top = i
		}
	}
	if total == 0 {
		each := amount / int64(n)
		for i := 0; i < n; i++ {
			shares[i] += each
		}
		shares[0] += amount - each*int64(n)
		return
	}
	var given int64
	for i := 0; i < n; i++ {
		c := jv.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		part := amount * c / total
		shares[i] += part
		given += part
	}
	if rest := amount - given; rest > 0 {
		shares[top] += rest
	}
}

// ----- commit -----

func renderCommitChoose(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(pageHead("Commit your pick", jobTitle(jv)+" · round "+
		strconv.FormatInt(int64(jv.Round), 10), "The job", jobLink(jv.ID)))
	if jv.Phase != 1 {
		b.WriteString(notice("WARNING", "Not committing any more", "This job is "+phaseName(jv.Phase)+"."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	b.WriteString("Pick one. The next page hashes it and hands you the exact value to sign — " +
		"the hash is public, the pick is not. You can change nothing after signing.\n\n")
	for _, a := range []uint8{1, 2, 3, 4} {
		b.WriteString("### " + actionGlyph(a) + " " + actionName(a) + "\n" + actionBlurb(a) + "\n\n")
		b.WriteString(button("Take "+actionName(a), seatLink(jv, you, "commit/"+strconv.Itoa(int(a))), "outline") + "\n\n")
	}
	b.WriteString(notice("NOTE", "Alarm is at "+strconv.FormatInt(jv.Alarm, 10)+"/3",
		"Carry secures loot against a bust; Watch holds the door. If you are the snitch you want alarm, not a clean cellar."))
	b.WriteString(nav("The job", jobLink(jv.ID), "Rules", self("rules")))
	return b.String()
}

func renderCommitHash(jv JobView, you string, action uint8) string {
	if action < 1 || action > 4 {
		action = 1
	}
	var b strings.Builder
	b.WriteString(pageHead("Sign this hash", jobTitle(jv)+" · "+actionCell(action), "The job", jobLink(jv.ID)))
	if jv.Phase != 1 {
		b.WriteString(notice("WARNING", "Too late for a commit", "This job is "+phaseName(jv.Phase)+"."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	if you == "" {
		b.WriteString(notice("WARNING", "No address in the URL",
			"The hash is bound to your wallet. Open your own seat view first: "+
				md("job "+strconv.FormatInt(jv.ID, 10), jobLink(jv.ID))+" and use the address link there."))
	}
	salt := CommitSalt(jv.ID, jv.Round, you)
	hash := CommitHash(jv.ID, action, salt, you)

	b.WriteString("You chose " + actionCell(action) + ". " + actionBlurb(action) + "\n\n")
	b.WriteString("**Hash to sign**\n\n" + code(hash) + "\n\n")
	b.WriteString("**Salt, keep it**\n\n" + code(salt) + "\n\n")
	b.WriteString(notice("CAUTION", "Without the salt your pick dies",
		"The realm checks `sha256(action|salt|you|job|round)` on reveal. Paste this salt back at the "+
			"reveal step or the pick counts as "+actionCell(4)+" and earns nothing."))

	b.WriteString("<gno-form exec=\"Commit\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString(readonlyField("hash", "Hash (built from your pick)", hash))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Signing posts only the hash. Your pick stays unreadable until the reveal._\n\n")

	b.WriteString("### After signing\n\n")
	b.WriteString(md("Back to the job", jobLink(jv.ID)) + " · " +
		md("go straight to the reveal form", seatLink(jv, you, "reveal")) +
		" (it works once this round's commits close — " + blocksLeft(jv) + ")\n")
	return b.String()
}

// ----- reveal -----

func renderReveal(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(pageHead("Reveal your pick", jobTitle(jv)+" · round "+
		strconv.FormatInt(int64(jv.Round), 10), "The job", jobLink(jv.ID)))
	if jv.Phase != 2 {
		b.WriteString(notice("WARNING", "Reveal is closed", "This job is "+phaseName(jv.Phase)+"."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	if jv.Deadline <= jv.Height {
		b.WriteString(notice("CAUTION", "Deadline passed",
			"Reveal is rejected now (`e410`). "+md("Tick the job", jobLink(jv.ID))+
				" — unrevealed picks become "+actionCell(4)+" with no contribution."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	b.WriteString(blocksLeft(jv) + ". The realm recomputes the hash from what you send and rejects a " +
		"mismatch, so send exactly what you committed.\n\n")

	b.WriteString("<gno-form exec=\"Reveal\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	for _, a := range []uint8{1, 2, 3, 4} {
		b.WriteString(selectOpt("action", strconv.Itoa(int(a)), actionGlyph(a)+" "+actionName(a), false))
	}
	b.WriteString(selectSalt(jv, you))
	b.WriteString("</gno-form>\n\n")

	b.WriteString(notice("NOTE", "Salt prefilled but editable",
		"It is derived from your seat and this round. If you committed from another device, "+
			"paste the salt the commit page gave you instead."))
	b.WriteString(nav("The job", jobLink(jv.ID), "Rules", self("rules")))
	return b.String()
}

// ----- small form fields -----

func readonlyField(name, description, value string) string {
	return `<gno-input name="` + name + `" description="` + attr(description) +
		`" value="` + attr(value) + `" readonly="true" />` + "\n"
}

func selectOpt(name, value, label string, selected bool) string {
	s := `<gno-select name="` + name + `" value="` + attr(value) + `"`
	if label != "" {
		s += ` description="` + attr(label) + `"`
	}
	if selected {
		s += ` selected="true"`
	}
	return s + " />\n"
}

// selectSalt prefills the salt; a player who committed elsewhere overwrites it.
func selectSalt(jv JobView, you string) string {
	return `<gno-input name="salt" description="Salt from your commit page" value="` +
		attr(CommitSalt(jv.ID, jv.Round, you)) + `" required="true" />` + "\n"
}

package cutpurse

// render_jobs.gno — the board. Every open and live job, one row each, and the
// filters as paths so a shared link keeps its filter.

import (
	"strconv"
	"strings"
)

// boardJobs collects rows for a filter: 0 open, 1 committing, 2 revealing,
// 3 escaped, 4 busted, anything else every live phase.
func boardJobs(kind int64) []JobView {
	switch kind {
	case 0:
		return jobList(0, 40)
	case 1:
		return jobList(1, 40)
	case 2:
		return jobList(2, 40)
	case 3:
		return jobList(3, 32)
	case 4:
		return jobList(4, 32)
	}
	rows := jobList(0, 20)
	rows = append(rows, jobList(1, 20)...)
	return append(rows, jobList(2, 20)...)
}

func filterName(kind int64) string {
	switch kind {
	case 0:
		return "open"
	case 1:
		return "committing"
	case 2:
		return "revealing"
	case 3:
		return "escaped"
	case 4:
		return "busted"
	}
	return "live"
}

// jobTable is one row per job: enough to judge a fee in one glance, nothing
// that belongs on the job's own page.
func jobTable(rows []JobView) string {
	var b strings.Builder
	b.WriteString("| Job | State | Seats | Pot | Fee | Clock | |\n")
	b.WriteString("|---|---|---:|---:|---:|---|---|\n")
	for _, jv := range rows {
		b.WriteString("| " + jobLinkCell(jv) + " | " + phaseBadge(jv.Phase) +
			" | " + seatStrip(int64(jv.NSeats)) +
			" | " + money(jv.Pot) + " | " + money(jv.Fee) +
			" | " + clockCell(jv) +
			" | " + md(icon("arrow-right", "Open job"), jobLink(jv.ID)) + " |\n")
	}
	return b.String()
}

// jobLinkCell is a job's name as a link; jobTitle already escapes its pipes.
func jobLinkCell(jv JobView) string {
	return md(icon("door", "")+" "+jobTitle(jv), jobLink(jv.ID))
}

// clockCell is a job's remaining time in a table cell.
func clockCell(jv JobView) string {
	switch jv.Phase {
	case 3, 4:
		return "settled"
	}
	if jv.Deadline <= jv.Height {
		return "**passed**"
	}
	return strconv.FormatInt(jv.Deadline-jv.Height, 10) + " blk"
}

func renderJobs(kind int64) string {
	var b strings.Builder
	b.WriteString(pageHead("The board", "", "Home", hub))

	if kind > 4 {
		var links []string
		for _, k := range []int64{0, 1, 2, 3, 4} {
			links = append(links, md(filterName(k), self("jobs/"+strconv.FormatInt(k, 10))))
		}
		b.WriteString("Filter: **live** (showing every live phase) · " + strings.Join(links, " · ") + "\n\n")
	} else {
		var links []string
		for _, k := range []int64{0, 1, 2, 3, 4} {
			label := filterName(k)
			if k == kind {
				links = append(links, "**"+label+"**")
				continue
			}
			links = append(links, md(label, self("jobs/"+strconv.FormatInt(k, 10))))
		}
		b.WriteString("Filter: " + strings.Join(links, " · ") + " · " + md("live", self("jobs")) + "\n\n")
	}

	rows := boardJobs(kind)
	if len(rows) == 0 {
		b.WriteString(emptyBoard(kind))
	} else {
		b.WriteString(jobTable(rows) + "\n")
		b.WriteString(notice("TIP", "Fees are set by each creator",
			"A low fee is a cheap seat, not a weak crew. Check the pot before you judge a job."))
	}

	b.WriteString(button("Start a job", self(""), "outline") + "\n\n")
	b.WriteString(nav("Home", self(""), "How it works", self("rules")))
	return b.String()
}

func emptyBoard(kind int64) string {
	switch kind {
	case 3:
		return notice("NOTE", "Nobody has escaped yet", "Settled jobs land here forever. "+
			"When one does, its payouts are public.") + "\n"
	case 4:
		return notice("NOTE", "Nobody has been busted yet", "The first job to hit an alarm of 3 lands here.")
	}
	if kind == 0 {
		return notice("NOTE", "No job is open. Be the first through the door.",
			"Start one, then send the link to a second wallet. Two seats are enough to run a round.")
	}
	return notice("NOTE", "No job is "+filterName(kind)+" right now", "Try "+md("every live job", self("jobs"))+".")
}

package cutpurse

// render_ledger.gno — the permanent record, and the network totals.
// The ledger is the game's memory: it is why a snitch is worth naming.

import (
	"strconv"
	"strings"
)

const ledgerPageSize = 8

func renderLedger(page int64) string {
	if page < 1 {
		page = 1
	}
	var b strings.Builder
	b.WriteString(pageHead("The ledger",
		"Every settled job, kept. Fees, splits and snitches, readable by anyone.", "Home", hub))

	rows := ledgerPage(int(page-1), ledgerPageSize)
	if len(rows) == 0 {
		if page > 1 {
			b.WriteString(notice("NOTE", "Past the last page", "Nothing archived here. ") +
				md("Back to page 1", self("ledger/1")) + ".\n\n")
		} else {
			b.WriteString(notice("NOTE", "Nothing archived. The first job to settle lands here.",
				md("Open a job", self(""))+" and give it three rounds."))
		}
		b.WriteString(nav("Home", self(""), "The board", self("jobs")))
		return b.String()
	}

	b.WriteString(resultTable(rows) + "\n")
	if page > 1 {
		b.WriteString(md(icon("arrow-left", "")+" newer", self("ledger/"+strconv.FormatInt(page-1, 10))) + " · ")
	}
	if ledgerPageSize*page < LedgerLen() {
		b.WriteString(md("older "+icon("arrow-right", ""), self("ledger/"+strconv.FormatInt(page+1, 10))))
	}
	b.WriteString("\n\nPage " + strconv.FormatInt(page, 10) + ". The ledger keeps the last " +
		strconv.Itoa(LedgerMax) + " results; older ones fall off the end.\n\n")

	b.WriteString(notice("NOTE", "Secured loot, not loot",
		"The loot column is what the crew raised. Only the secured part was ever paid out — "+
			"a bust keeps what reached the door."))
	b.WriteString(nav("Home", self(""), "Totals", self("stats")))
	return b.String()
}

// resultTable is the archive, one row per job.
func resultTable(rows []Result) string {
	var b strings.Builder
	// No payout column: it is the widest string on the page and it grows with
	// every row. The receipt lives on the job itself.
	b.WriteString("| Job | Name | Outcome | Raised | Snitch | Block |\n")
	b.WriteString("|---|---|---|---:|---|---:|\n")
	for _, r := range rows {
		b.WriteString("| " + md(strconv.FormatInt(r.JobID, 10), jobLink(r.JobID)) + " | " +
			pipe(resultName(r)) + " | " + outcomeCell(r) + " | " +
			money(r.Loot) + " | " + snitchCell(r) + " | " +
			strconv.FormatInt(r.At, 10) + " |\n")
	}
	return b.String() + "\n"
}

func resultName(r Result) string {
	if strings.TrimSpace(r.Name) == "" {
		return "Job " + strconv.FormatInt(r.JobID, 10)
	}
	return r.Name
}

func outcomeCell(r Result) string {
	if r.Busted {
		return icon("alarm", "busted") + " busted"
	}
	return icon("check-circle", "escaped") + " escaped"
}

// snitchCell names the snitch seat's wallet. who() already answers "—" for an
// unusable address, so the zero address is the only case worth a guard here.
func snitchCell(r Result) string {
	s := r.Traitor.String()
	if len(s) < 20 {
		return "—"
	}
	return who(s)
}

// secured is what a bust did not destroy. The archive keeps raised loot, so
// a busted row shows nothing secure.
func secured(r Result) int64 {
	if r.Busted {
		return 0
	}
	return r.Loot
}

// ----- stats -----

func renderStats() string {
	var b strings.Builder
	b.WriteString(pageHead("Totals", "What the realm has run, in aggregate.", "Home", hub))
	b.WriteString(notice("NOTE", "Nobody's numbers are graded here",
		"This page is the cellar's own tally. Per-wallet records are on their profiles."))

	open := int64(len(jobList(0, 40)))
	var escaped, busted, loot int64
	for p := 0; p <= currentLedgerPages(); p++ {
		for _, r := range ledgerPage(p, ledgerPageSize) {
			loot += r.Loot
			if r.Busted {
				busted++
			} else {
				escaped++
			}
		}
	}
	settled := escaped + busted

	b.WriteString(cards(
		"**Jobs opened**\n\n"+strconv.FormatInt(JobCount(), 10),
		"**Open now**\n\n"+strconv.FormatInt(open, 10),
		"**Settled**\n\n"+strconv.FormatInt(settled, 10),
		"**Loot raised**\n\n"+money(loot)+" GNOT",
	))
	b.WriteString("\n")

	if settled > 0 {
		bar := busted * 10 / settled
		b.WriteString("**Treasury** " + coins(Treasury()) + "\n\n")
		b.WriteString("**Busted** " + meter(bar, 10) + " " +
			strconv.FormatInt(busted*100/settled, 10) + "% of " + plural(settled, "settled job") + "\n\n")
		b.WriteString("### The snitch has been named\n\n")
		b.WriteString(plural(busted, "bust") + " out of " + plural(settled, "settled job") +
			". A bust pays the snitch 60% of the pot, so a snitch who is never caught is the " +
			"best-paid seat in the game.\n\n")
	} else {
		b.WriteString(notice("NOTE", "No job has settled yet",
			"These totals fill in as jobs finish. "+md("Open the first", self(""))+"."))
	}

	b.WriteString(button("The ledger", self("ledger"), "outline") + " " +
		button("The board", self("jobs"), "outline") + "\n\n")
	b.WriteString(nav("Home", self(""), "Rules", self("rules")))
	return b.String()
}

// currentLedgerPages is the last page index (0-based).
func currentLedgerPages() int {
	if LedgerLen() == 0 {
		return 0
	}
	return int((LedgerLen() - 1) / ledgerPageSize)
}

package cutpurse

// render_profile.gno — one wallet's record. A record is the only reputation
// here, so it is stated plainly and never graded with a badge.

import (
	"strconv"
	"strings"
)

func renderProfile(addr string) string {
	var b strings.Builder
	b.WriteString(pageHead("A wallet", "", "The ledger", self("ledger")))
	if !address(addr).IsValid() {
		b.WriteString(notice("WARNING", "Not an address", "`"+text(addr)+"` is not a gno address."))
		return b.String() + nav("The ledger", self("ledger"), "Home", self(""))
	}

	jobs, escapes, busts, loot := StatsOf(addr)
	b.WriteString("## " + code(addr) + "\n\n")
	b.WriteString(cards(
		"**Jobs**\n\n"+strconv.FormatInt(jobs, 10),
		"**Escaped**\n\n"+strconv.FormatInt(escapes, 10),
		"**Busted**\n\n"+strconv.FormatInt(busts, 10),
		"**Secured**\n\n"+money(loot)+" GNOT",
	))
	b.WriteString("\n")

	if jobs == 0 {
		b.WriteString(notice("NOTE", "Nothing on this wallet yet",
			"A job takes five minutes and the ledger keeps it forever. "+
				md("Take a seat", self("jobs"))+" and this page fills itself in."))
		b.WriteString(nav("The board", self("jobs"), "Rules", self("rules")))
		return b.String()
	}

	b.WriteString(notice("NOTE", "Read the seats, not the percentage",
		"Escapes at a high fee beat many cheap jobs. Contribution is what each split was weighted by."))

	b.WriteString("## Jobs settled\n\n")
	rows := entriesOf(addr)
	if len(rows) == 0 {
		b.WriteString("_This wallet is in a live job and has not settled one yet._\n\n")
	} else {
		b.WriteString(resultTable(rows))
	}

	b.WriteString(button("Find a job", self("jobs"), "") + "\n\n")
	b.WriteString(nav("The ledger", self("ledger"), "Home", self("")))
	return b.String()
}

// entriesOf scans the archived ledger for one wallet. The ring buffer holds
// 500 entries, so one page is enough to find a recent record.
func entriesOf(addr string) []Result {
	var out []Result
	for p := 0; p <= currentLedgerPages(); p++ {
		for _, r := range ledgerPage(p, LedgerMax) {
			if strings.Contains(r.Payouts, addr) || r.Traitor.String() == addr {
				out = append(out, r)
			}
		}
	}
	return out
}

package cutpurse

import "strconv"

// FROZEN CONTRACT (SPEC §9). The designer consumes these shapes and may not
// touch globals or maps. Widening a struct is builder-only and needs a SPEC
// amendment.

type JobView struct {
	ID        int64
	Name      string
	Creator   address
	Fee       int64
	Pot       int64
	Loot      int64
	Secured   int64
	Alarm     int64
	Phase     uint8
	Round     uint8
	Deadline  int64
	Height    int64
	NSeats    uint8
	Revealed  bool
	Traitor   int8
	OpenedAt  int64
	SettledAt int64
	Settled   bool
	Seats     []SeatView
}

type SeatView struct {
	Addr         address
	Committed    bool
	Revealed     bool
	Auto         bool
	Action       uint8
	Contribution int64
}

// jobView renders one job; Traitor is -1 until the snitch is public.
func jobView(id int64) (JobView, bool) {
	j, ok := jobs[id]
	if !ok {
		return JobView{}, false
	}

	v := JobView{
		ID:        j.ID,
		Name:      j.Name,
		Creator:   j.Creator,
		Fee:       j.Fee,
		Pot:       j.Pot,
		Loot:      j.Loot,
		Secured:   j.Secured,
		Alarm:     j.Alarm,
		Phase:     uint8(j.Phase),
		Round:     j.Round,
		Deadline:  j.Deadline,
		Height:    mustHeight(),
		NSeats:    j.NSeats,
		Revealed:  j.Revealed,
		Traitor:   -1,
		OpenedAt:  j.OpenedAt,
		SettledAt: j.SettledAt,
		Settled:   j.SettledAt != 0,
		Seats:     make([]SeatView, 0, int(j.NSeats)),
	}
	if j.Revealed {
		v.Traitor = j.Traitor
	}
	for i := 0; i < int(j.NSeats); i++ {
		s := j.Seats[i]
		v.Seats = append(v.Seats, SeatView{
			Addr:         s.Addr,
			Committed:    s.Committed,
			Revealed:     s.Action != ActNone,
			Auto:         s.Auto,
			Action:       uint8(s.Action),
			Contribution: s.Contribution,
		})
	}
	return v, true
}

// jobList returns up to limit views, newest first. phase > PhaseBusted means
// "any phase".
func jobList(phase uint8, limit int) []JobView {
	if limit < 1 {
		limit = 1
	}
	if limit > MaxListLimit {
		limit = MaxListLimit
	}

	out := make([]JobView, 0, limit)
	id := nextID - 1
	for scanned := 0; id >= 0 && len(out) < limit && scanned < LedgerMax; scanned++ {
		if v, ok := jobView(id); ok {
			if phase > uint8(PhaseBusted) || v.Phase == phase {
				out = append(out, v)
			}
		}
		id--
	}
	return out
}

// ledgerPage returns one ledger page, newest entry first.
func ledgerPage(n, size int) []Result {
	if size < 1 {
		size = 10
	}
	if size > MaxListLimit {
		size = MaxListLimit
	}
	if n < 0 {
		n = 0
	}

	out := make([]Result, 0, size)
	start := n * size
	for k := start; k < start+size && k < ledgerLen; k++ {
		idx := (ledgerHead - 1 - k + LedgerMax*2) % LedgerMax
		if r := ledger[idx]; r != nil {
			out = append(out, *r)
		}
	}
	return out
}

func statsOf(a address) (jobs, escapes, busts, loot int64) {
	s, ok := stats[a.String()]
	if !ok {
		return 0, 0, 0, 0
	}
	return s.Jobs, s.Escapes, s.Busts, s.Loot
}

// JobCount is the number of jobs ever created.
func JobCount() int64 { return nextID }

// JobViewOf / JobListOf / LedgerPageOf / StatsOfAddress are exported doors on
// the unexported contract helpers so out-of-package tests can assert on state
// without touching globals.
func JobViewOf(id int64) (JobView, bool) { return jobView(id) }

func JobListOf(phase uint8, limit int) []JobView { return jobList(phase, limit) }

func LedgerPageOf(n, size int) []Result { return ledgerPage(n, size) }

func StatsOfAddress(a address) (jobs, escapes, busts, loot int64) { return statsOf(a) }

// StatsOf is statsOf keyed by bech32 string (path input, no parser needed).
func StatsOf(a string) (jobs, escapes, busts, loot int64) {
	s, ok := stats[a]
	if !ok {
		return 0, 0, 0, 0
	}
	return s.Jobs, s.Escapes, s.Busts, s.Loot
}

// Name returns the stored (already sanitized) job name, or "".
func Name(id int64) string {
	if j, ok := jobs[id]; ok {
		return j.Name
	}
	return ""
}

// Treasury is the accrued 5% house cut, in ugnot.
func Treasury() int64 { return treasury }

// treasuryTotal is the designer's spelling for the same number.
func TreasuryTotal() int64 { return treasury }

// commitSalt is a round-stable, per-seat nonce the commit page shows. It is
// derived from OpenedAt (immutable for the life of the job) and Round, so the
// same value comes back at reveal time even though Deadline moves.
func saltFor(id int64, round uint8, who string) string {
	openedAt := int64(0)
	if j, ok := jobs[id]; ok {
		openedAt = j.OpenedAt
	}
	return sha256Hex("cutpurse|" +
		strconv.FormatInt(id, 10) + "|" +
		strconv.FormatUint(uint64(round), 10) + "|" +
		strconv.FormatInt(openedAt, 10) + "|" +
		who)
}

// CommitSalt is the exported door for out-of-package callers.
func CommitSalt(id int64, round uint8, who string) string { return saltFor(id, round, who) }

// LedgerLen is the number of archived results.
func LedgerLen() int64 { return int64(ledgerLen) }

// Archived returns the permanent ledger entry for a settled job.
func Archived(id int64) (Result, bool) {
	for k := 0; k < ledgerLen; k++ {
		idx := (ledgerHead - 1 - k + LedgerMax*2) % LedgerMax
		if r := ledger[idx]; r != nil && r.JobID == id {
			return *r, true
		}
	}
	return Result{}, false
}

package cutpurse

import (
	"chain"
	"chain/banker"
	"sort"
	"strconv"
	"strings"
)

// Tick is the only transition driver. Permissionless, any phase, no-op while
// the phase deadline is still open (§5, §6).
func Tick(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	j := mustJob(id)

	if j.Phase >= PhaseSettled {
		return
	}

	height := mustHeight()
	if height <= j.Deadline {
		return
	}

	switch j.Phase {
	case PhaseOpen:
		if j.NSeats >= 2 {
			j.Phase = PhaseCommit
			j.Round = 1
			j.Deadline = height + CommitBlocks
			return
		}
		// never filled: disband, everyone is refunded by Settle
		j.Phase = PhaseSettled
		j.Deadline = height
	case PhaseCommit:
		closeCommitRound(j)
	case PhaseReveal:
		closeRevealRound(j, true)
	}
}

// sealSeed is the deterministic seed from §6: it is a pure function of public
// data, so anyone can recompute it after the round closes.
func sealSeed(j *Job) string {
	hashes := make([]string, 0, Seats)
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Committed && j.Seats[i].CommitHash != "" {
			hashes = append(hashes, j.Seats[i].CommitHash)
		}
	}
	sort.Strings(hashes)

	return sha256Hex(j.Seed + "|" +
		strconv.FormatInt(j.ID, 10) + "|" +
		strconv.FormatInt(mustHeight(), 10) + "|" +
		strings.Join(hashes, ""))
}

// closeCommitRound ends the commit phase: silent seats fall back to Watch, the
// seed is sealed on round 1 and the snitch seat is drawn from it.
func closeCommitRound(j *Job) {
	for i := 0; i < int(j.NSeats); i++ {
		if !j.Seats[i].Committed {
			j.Seats[i].Action = ActWatch
			j.Seats[i].Auto = true
		}
	}

	if j.Round == 1 && j.Seed == "" {
		j.Seed = sealSeed(j)
		if j.NSeats > 0 {
			j.Traitor = int8(int64(j.Seed[0]) % int64(j.NSeats))
		}
	}

	j.Phase = PhaseReveal
	j.Deadline = mustHeight() + RevealBlocks
}

// closeRevealRound ends the reveal phase: silent seats fall back to Watch and,
// when the deadline forced the close, lose one reputation point.
func closeRevealRound(j *Job, penalize bool) {
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Action == ActNone {
			j.Seats[i].Action = ActWatch
			j.Seats[i].Auto = true
			if penalize {
				repDown(j.Seats[i].Addr)
			}
		}
	}
	resolveRound(j)
}

// resolveRound applies §6 exactly: alarm, secured, loot, contributions, then
// either terminal phase or the next round.
func resolveRound(j *Job) {
	n := int(j.NSeats)
	var np, nc, ns, nw int64

	for i := 0; i < n; i++ {
		switch j.Seats[i].Action {
		case ActPick:
			np++
		case ActCarry:
			nc++
		case ActScout:
			ns++
		case ActWatch:
			nw++
		}
	}

	j.Alarm += maxInt64(0, np-nw)
	j.Secured += 2 * nc
	loot := 3*np + 2*nc + 2*ns + nw
	if np == 0 && nw > 0 {
		loot += nw
	}
	j.Loot += loot

	for i := 0; i < n; i++ {
		switch j.Seats[i].Action {
		case ActPick, ActCarry:
			j.Seats[i].Contribution += 3
		case ActScout:
			j.Seats[i].Contribution += 2
		case ActWatch:
			j.Seats[i].Contribution += 1 + np
		}
	}

	if j.Alarm >= BustAlarm {
		j.Phase = PhaseBusted
		return
	}
	if j.Round >= Rounds {
		j.Phase = PhaseSettled
		return
	}

	j.Round++
	j.Phase = PhaseCommit
	j.Deadline = mustHeight() + CommitBlocks
	for i := 0; i < n; i++ {
		j.Seats[i].Committed = false
		j.Seats[i].CommitHash = ""
		j.Seats[i].Action = ActNone
		j.Seats[i].Auto = false
	}
}

// splitByContribution divides amount by accumulated contribution; the rounding
// dust goes to the top contributor, and an all-zero table splits equally.
func splitByContribution(j *Job, amount int64, pay *[Seats]int64) {
	n := int(j.NSeats)
	if amount <= 0 || n == 0 {
		return
	}

	var total int64
	top := 0
	for i := 0; i < n; i++ {
		c := j.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		total += c
		if c > j.Seats[top].Contribution {
			top = i
		}
	}

	if total == 0 {
		each := amount / int64(n)
		for i := 0; i < n; i++ {
			pay[i] += each
		}
		pay[0] += amount - each*int64(n)
		return
	}

	var given int64
	for i := 0; i < n; i++ {
		c := j.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		part := amount * c / total
		pay[i] += part
		given += part
	}
	if rest := amount - given; rest > 0 {
		pay[top] += rest
	}
}

func archiveResult(j *Job, pay *[Seats]int64) {
	r := &Result{
		JobID:  j.ID,
		Name:   j.Name,
		Busted: j.Phase == PhaseBusted,
		Loot:   j.Loot,
		At:     mustHeight(),
	}
	if j.Traitor >= 0 && int(j.Traitor) < int(j.NSeats) {
		r.Traitor = j.Seats[j.Traitor].Addr
	}

	parts := make([]string, 0, Seats)
	for i := 0; i < int(j.NSeats); i++ {
		if pay[i] > 0 {
			parts = append(parts, j.Seats[i].Addr.String()+":"+strconv.FormatInt(pay[i], 10))
		}
	}
	r.Payouts = strings.Join(parts, ",")

	ledger[ledgerHead] = r
	ledgerHead = (ledgerHead + 1) % LedgerMax
	if ledgerLen < LedgerMax {
		ledgerLen++
	}
}

// Settle pushes the single payout, archives the result and frees the seats.
// All state is written before any coin leaves the realm (§10 R4).
func Settle(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	j := mustJob(id)

	if j.SettledAt != 0 {
		panic(ErrAlreadySettled)
	}
	if j.Phase < PhaseSettled {
		panic(ErrNotReady)
	}

	n := int(j.NSeats)
	busted := j.Phase == PhaseBusted
	pay := [Seats]int64{}

	if n > 0 && j.Pot > 0 {
		if busted {
			share := j.Pot * TraitorBustShare / 100
			if j.Traitor >= 0 && int(j.Traitor) < n {
				pay[j.Traitor] = share
				splitByContribution(j, j.Pot-share, &pay)
			} else {
				splitByContribution(j, j.Pot, &pay)
			}
			j.Revealed = true
		} else {
			// §6 says cut = Secured*Bps/10000, but Secured counts 2 per carry
			// while the pot is in ugnot — the raw product rounds to zero at
			// MinFee. Scale Secured against the best possible secure
			// (2*Seats*Rounds) so the 5% is 5% of the pot, capped there.
			cut := j.Pot * j.Secured * TreasuryBps / (10000 * MaxSecured)
			if cut > j.Pot {
				cut = j.Pot
			}
			treasury += cut
			splitByContribution(j, j.Pot-cut, &pay)
		}
	}

	// --- state before coins ---
	height := mustHeight()
	j.SettledAt = height
	for i := 0; i < n; i++ {
		s := statFor(j.Seats[i].Addr)
		s.Jobs++
		if busted {
			s.Busts++
		} else {
			s.Escapes++
		}
		s.Loot += pay[i]
		if active[j.Seats[i].Addr] == j.ID {
			delete(active, j.Seats[i].Addr)
		}
	}
	archiveResult(j, &pay)
	if liveCount > 0 {
		liveCount--
	}
	purgeOld()

	// --- then coins ---
	realmAddr := cur.Address()
	bank := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	for i := 0; i < n; i++ {
		if pay[i] > 0 {
			bank.SendCoins(realmAddr, j.Seats[i].Addr, chain.NewCoins(chain.NewCoin(Denom, pay[i])))
		}
	}
}

package cutpurse

// ui.gno — the design system and the router. Everything a page may say about
// shape, money, danger or another player goes through this file. Pages call
// these and never build markup themselves.
//
// Palette, voice and copy deck: docs/brand.md. The rules that matter here:
// text from the chain is hostile, so it enters through text/cell/code; every
// self-link is absolute and built from hub; alarm is ▰▰▱ and seats are ▰▰▱▱.

import (
	"html"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// hub is this realm's absolute base. Set it to the deploy address before
// deploy (see _agents/STATE.md). Every link and button is hub + ":" + path.
const hub = "/r/g1e4jarvm80rz800tmw8nvx43j2fq2z9atkya5na/cutpurse"

const (
	seatTotal  = 4 // seats per job, drawn as a strip of 4 segments
	alarmTotal = 3 // alarm segments before a job busts
)

const (
	segFull   = "▰"
	segBlank  = "▱"
	segLocked = "▪"
)

// ----- routing -----

// Render is the realm's only entry point besides the actions. It is the
// designer's: builder must not define another one (see STATE.md).
// Paths: "" home · rules · jobs[/<phase>] · job/<id>[/<you>[/commit[/<action>]|/reveal]]
// · j/<id> (alias) · p/<addr> · ledger[/<n>] · stats.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	p := strings.Trim(path, "/")
	parts := strings.Split(p, "/")
	switch parts[0] {
	case "rules":
		return renderRules()
	case "jobs":
		return renderJobs(atoiOr(part(parts, 1), 0))
	case "job", "j":
		return renderJobPath(parts)
	case "p":
		return renderProfile(part(parts, 1))
	case "ledger":
		return renderLedger(atoiOr(part(parts, 1), 1))
	case "stats":
		return renderStats()
	}
	return renderMissing(text(parts[0]))
}

func part(parts []string, i int) string {
	if i < len(parts) {
		return parts[i]
	}
	return ""
}

func atoiOr(s string, fallback int64) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return fallback
	}
	return n
}

// ----- escaping -----

// text is user prose: safe inside a paragraph, heading or link label.
func text(s string) string { return sanitize.InlineText(s) }

// cell is a table cell: text that also survives its own pipes.
func cell(s string) string { return sanitize.TableCell(s) }

// code is a code span holding user text.
func code(s string) string { return sanitize.InlineCode(s) }

// attr escapes a value for a tag attribute.
func attr(s string) string { return html.EscapeString(s) }

// ----- links and controls -----

// self is an absolute self-link. The empty path is the realm root, which
// takes no colon.
func self(path string) string {
	if path == "" {
		return hub
	}
	return hub + ":" + path
}

func md(label, href string) string { return "[" + label + "](" + href + ")" }

func icon(name, label string) string {
	if label == "" {
		return `<gno-icon name="` + name + `" />`
	}
	return `<gno-icon name="` + name + `" label="` + attr(label) + `" />`
}

// button is a styled link. variant: "" (solid), "outline", "caution",
// "warning", "success", or two of them.
func button(label, href, variant string) string {
	s := `<gno-button href="` + attr(href) + `" label="` + attr(label) + `"`
	if variant != "" {
		s += ` variant="` + attr(variant) + `"`
	}
	return s + ` />`
}

// nav is a foot row of label/href pairs. The first pair is the way back and
// carries the arrow; the rest are cross-links.
func nav(pairs ...string) string {
	var b strings.Builder
	for i := 0; i+1 < len(pairs); i += 2 {
		if i > 0 {
			b.WriteString(" · ")
		}
		label := pairs[i]
		if i == 0 {
			label = icon("arrow-left", "Back") + " " + label
		}
		b.WriteString(md(label, pairs[i+1]))
	}
	return b.String() + "\n\n"
}

// ----- structure -----

// frame is a bordered block. Alone in a column it draws as a card. The
// closing tag always gets its own empty line so the last line parses.
func frame(body string) string {
	if !strings.HasSuffix(body, "\n") {
		body += "\n"
	}
	return "<gno-frame>\n" + body + "\n</gno-frame>\n"
}

// cards lays frames out side by side, one column each.
func cards(bodies ...string) string {
	if len(bodies) == 0 {
		return ""
	}
	if len(bodies) == 1 {
		return frame(bodies[0]) + "\n"
	}
	s := "<gno-columns>\n" + frame(bodies[0])
	for _, body := range bodies[1:] {
		s += "\n<gno-columns-sep />\n" + frame(body)
	}
	return s + "</gno-columns>\n\n"
}

func notice(kind, title, body string) string {
	s := "> [!" + kind + "]"
	if title != "" {
		s += " " + title
	}
	if body != "" {
		s += "\n> " + body
	}
	return s + "\n\n"
}

// fold is a collapsed block: closed by default, so it hides what a returning
// player already knows.
func fold(summary, body string) string {
	return "<gno-details summary=\"" + attr(summary) + "\">\n" + body + "\n</gno-details>\n\n"
}

func title(s string) string { return "# " + s + "\n\n" }

// pageHeadBare is a title and one line of state with no cross-links. Pages that
// already carry their own footer nav use this: two nav rows on one page is a
// third more link gas for nothing.
func pageHeadBare(name, line string) string {
	if line == "" {
		return title(name)
	}
	return title(name) + line + "\n\n"
}

// pageHead is the standard opening: title, one line of state, and the way out.
func pageHead(name, line, backLabel, backHref string) string {
	s := title(name)
	if line != "" {
		s += line + "\n\n"
	}
	s += nav(backLabel, backHref, "Rules", self("rules"), "Ledger", self("ledger"))
	return s
}

// ----- money and numbers -----

// money renders ugnot as GNOT with three decimals: 100000 -> "0.100".
// Concatenation beats strings.Builder here by measurement, and this is the
// most-called helper on a page.
func money(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	milli := ugnot / 1000
	s := strconv.FormatInt(milli/1000, 10) + "." + pad(milli%1000, 3)
	if neg {
		return "-" + s
	}
	return s
}

func pad(v int64, width int) string {
	s := strconv.FormatInt(v, 10)
	for len(s) < width {
		s = "0" + s
	}
	return s
}

// coins is money with its glyph, the only form used in prose.
func coins(ugnot int64) string { return "🪙 **" + money(ugnot) + " GNOT**" }

func plural(n int64, one string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.FormatInt(n, 10) + " " + one + "s"
}

// ----- meters -----

// meter draws v filled segments out of total.
func meter(v, total int64) string {
	if v < 0 {
		v = 0
	}
	if v > total {
		v = total
	}
	s := ""
	for i := int64(0); i < total; i++ {
		if i < v {
			s += segFull
		} else {
			s += segBlank
		}
	}
	return s
}

// alarmBars is the alarm bar and its count, always three segments. The bar is
// decoration; the number is the fact, so both are always written.
func alarmBars(alarm int64) string {
	s := meter(alarm, alarmTotal) + " " + strconv.FormatInt(alarm, 10) + "/3"
	if alarm >= alarmTotal {
		return s + " **— the door is closing**"
	}
	return s
}

// alarmMeter is alarmBars with its glyph, for prose.
func alarmMeter(alarm int64) string { return icon("alarm", "") + " " + alarmBars(alarm) }

// seatStrip draws filled seats out of four, empty ones as blanks.
func seatStrip(filled int64) string { return meter(filled, seatTotal) }

// ----- players -----

func short(addr string) string {
	if len(addr) <= 12 {
		return addr
	}
	return addr[:6] + "…" + addr[len(addr)-4:]
}

// who is a player as a link to their profile. An address is bech32 — lowercase
// letters and digits only — so it needs no sanitize pass, only a code span; that
// keeps a seat table inside the render gas budget.
func who(addr string) string {
	if !address(addr).IsValid() {
		return "—"
	}
	return md("`"+short(addr)+"`", self("p/"+addr))
}

// youMark flags the caller's own seat, when the path carried their address.
func youMark(addr, viewer string) string {
	if viewer != "" && addr == viewer {
		return " " + icon("user-male", "you") + " **you**"
	}
	return ""
}

// ----- game vocabulary -----

func phaseName(phase uint8) string {
	switch phase {
	case 1:
		return "committing"
	case 2:
		return "revealing"
	case 3:
		return "escaped"
	case 4:
		return "busted"
	}
	return "open"
}

// phaseBadge is the one-glance state of a job in a list or a heading.
func phaseBadge(phase uint8) string {
	switch phase {
	case 1:
		return icon("lock", "committing") + " committing"
	case 2:
		return icon("eye", "revealing") + " revealing"
	case 3:
		return icon("check-circle", "escaped") + " escaped"
	case 4:
		return icon("alarm", "busted") + " busted"
	}
	return icon("door", "open") + " open"
}

func actionName(a uint8) string {
	switch a {
	case 1:
		return "Scout"
	case 2:
		return "Pick"
	case 3:
		return "Carry"
	case 4:
		return "Watch"
	}
	return "—"
}

func actionIcon(a uint8) string {
	switch a {
	case 1:
		return "search"
	case 2:
		return "unlock"
	case 3:
		return "bag"
	case 4:
		return "eye"
	}
	return "info"
}

func actionGlyph(a uint8) string {
	switch a {
	case 1:
		return "🔍"
	case 2:
		return "🔓"
	case 3:
		return "🎒"
	case 4:
		return "👁"
	}
	return "·"
}

// actionCell is an action with its glyph, for a table.
func actionCell(a uint8) string {
	if a == 0 {
		return "—"
	}
	return actionGlyph(a) + " " + actionName(a)
}

// actionBlurb is why a player would choose it. Contributions are the truth
// behind the flavour, so both are printed.
func actionBlurb(a uint8) string {
	switch a {
	case 1:
		return "Reads the room: **+2** loot, no alarm."
	case 2:
		return "Takes from the shelf: **+3** loot, **+1 alarm**."
	case 3:
		return "Hauls it to the door: **+3 loot that survives a bust**."
	case 4:
		return "Holds the door: **+1** loot, and **−1 alarm**."
	}
	return "Do nothing."
}

// blocksLeft says how long is left before the deadline, in blocks.
func blocksLeft(jv JobView) string {
	left := jv.Deadline - jv.Height
	if left <= 0 {
		return "**deadline passed**"
	}
	return strconv.FormatInt(left, 10) + " blocks left"
}

// jobTitle is a job's name with a fallback. Names are sanitised once at write
// time (cleanName), and sanitize helpers are not idempotent, so it is *not*
// re-run here — only the escape a table cell needs is applied.
func jobTitle(jv JobView) string {
	n := strings.TrimSpace(jv.Name)
	if n == "" {
		return "Job " + strconv.FormatInt(jv.ID, 10)
	}
	return pipe(n)
}

// pipe escapes the only markdown character a stored (already sanitised) name
// can still break a table with.
func pipe(s string) string { return strings.ReplaceAll(s, "|", `\|`) }

// jobLink is the canonical link to a job.
func jobLink(id int64) string { return self("job/" + strconv.FormatInt(id, 10)) }

// ----- surfaces owned by other files -----

// The six page functions live in render_home/rules/jobs/job/profile/ledger.gno.
// Declared here so the router reads as a table of contents.
func renderMissing(what string) string {
	return pageHead("Nothing here", "The path `"+what+"` is not a page.", "Home", hub) +
		notice("WARNING", "No such page", "") +
		"Try " + md("the board", self("jobs")) + ", " + md("the rules", self("rules")) +
		", or " + md("the ledger", self("ledger")) + ".\n"
}

package cutpurse

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// payIn enforces the send envelope of the call: the caller must cover want
// ugnot, anything above want is refunded immediately.
//
// A BankerTypeRealmSend banker can only spend the realm's own address, so fees
// must arrive with the message (tx send coins); banker.IssueCoin is not a
// substitute because realm-issued coins carry a "/<pkgpath>:" denom prefix and
// would not be the native ugnot the game escrows.
func payIn(cur realm, want int64) {
	// cur.Previous() is unreadable when a test drives the mutator with a bare
	// frame ("cannot seek beyond origin caller override"), so the caller-kind
	// guard is derived from the envelope instead: a realm caller attaches
	// nothing, so a zero envelope is a caller error, not a fee shortfall.
	sent := unsafe.OriginSend().AmountOf(Denom)
	if sent == 0 {
		panic(ErrNotUserCall)
	}
	who := here(cur)
	if sent < want {
		panic(ErrFeeTooLow)
	}
	if sent > want {
		banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
			cur.Address(), who, chain.NewCoins(chain.NewCoin(Denom, sent-want)))
	}
}

// mustJob returns the job or panics e404.
func mustJob(id int64) *Job {
	j, ok := jobs[id]
	if !ok {
		panic(ErrNoJob)
	}
	return j
}

func mustHeight() int64 { return runtime.ChainHeight() }

// here is the acting player. It is the message's origin caller, not
// cur.Previous(): a crossed call from another *package* would otherwise act as
// that package's address instead of the signing wallet.
func here(cur realm) address { return unsafe.OriginCaller() }

// clampFee bounds a caller-supplied fee into [MinFee, MaxFee].
func clampFee(fee int64) int64 {
	if fee < MinFee {
		return MinFee
	}
	if fee > MaxFee {
		return MaxFee
	}
	return fee
}

// cleanName sanitizes user text for write and bounds it to MaxNameRunes runes
// so Render is safe for arbitrarily long input (§10 R9).
func cleanName(raw string) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		panic(ErrBadName)
	}
	rs := []rune(sanitize.InlineText(trimmed))
	if len(rs) > MaxNameRunes {
		rs = rs[:MaxNameRunes]
	}
	// a truncated trailing escape would eat the following character
	for len(rs) > 0 && rs[len(rs)-1] == '\\' {
		rs = rs[:len(rs)-1]
	}
	if len(rs) == 0 {
		panic(ErrBadName)
	}
	return string(rs)
}

func validSalt(salt string) bool {
	if len(salt) == 0 || len(salt) > MaxSaltLen {
		return false
	}
	for i := 0; i < len(salt); i++ {
		b := salt[i]
		if b <= 0x20 || b >= 0x7f {
			return false
		}
	}
	return true
}

func isHex64(h string) bool {
	if len(h) != 64 {
		return false
	}
	for i := 0; i < len(h); i++ {
		b := h[i]
		ok := (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
		if !ok {
			return false
		}
	}
	return true
}

func sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// commitHash is the sealed preimage: sha256(action|salt|caller|id|round).
func commitHash(id int64, action uint8, salt, who string, round uint8) string {
	return sha256Hex(
		strconv.FormatUint(uint64(action), 10) + "|" +
			salt + "|" +
			who + "|" +
			strconv.FormatInt(id, 10) + "|" +
			strconv.FormatUint(uint64(round), 10))
}

// CommitHash is the render-facing helper (§7): designer passes the *typed*
// action and salt and shows the resulting string to paste in Commit.
func CommitHash(id int64, action uint8, salt, who string) string {
	rnd := uint8(0)
	if j, ok := jobs[id]; ok {
		rnd = j.Round
	}
	return commitHash(id, action, salt, who, rnd)
}

func maxInt64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func isLive(j *Job) bool { return j.Phase < PhaseSettled }

func seatOf(j *Job, who address) int {
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Addr == who {
			return i
		}
	}
	return -1
}

func countCommitted(j *Job) int {
	n := 0
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Committed {
			n++
		}
	}
	return n
}

func countRevealed(j *Job) int {
	n := 0
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Action != ActNone {
			n++
		}
	}
	return n
}

func statFor(who address) *Stats {
	k := who.String()
	s, ok := stats[k]
	if !ok {
		s = &Stats{}
		stats[k] = s
	}
	return s
}

func repDown(who address) {
	s := statFor(who)
	if s.Escapes > 0 {
		s.Escapes--
	}
}

// purgeOld keeps the jobs map bounded: once more than LedgerMax jobs exist,
// settled jobs are dropped oldest-first (the ledger ring stays permanent).
func purgeOld() {
	for i := 0; i < LedgerMax; i++ {
		if len(jobs) <= LedgerMax {
			return
		}
		oldest := int64(0)
		found := false
		for id := range jobs {
			if !isLive(jobs[id]) && jobs[id].SettledAt != 0 && (!found || id < oldest) {
				oldest = id
				found = true
			}
		}
		if !found {
			return
		}
		delete(jobs, oldest)
	}
}

package hearthboard

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1xj5r20d9yy4hfap0x5w3p9nu4x27mekc8pscgs/ember"
)

const (
	open              = "Open"
	claimed           = "Claimed"
	review            = "In review"
	complete          = "Completed"
	cancelled         = "Cancelled"
	claimBlocks int64 = 20000
	maxEmber    int64 = 1000000
	pageSize          = 8
)

type Quest struct {
	ID       int64
	Title    string
	Brief    string
	Poster   address
	Solver   address
	Proof    string
	Bounty   int64
	Tips     int64
	State    string
	Deadline int64
}

type Score struct {
	Solver address
	Solved int64
}

var (
	quests    avl.Tree
	scores    avl.Tree
	leaders   []Score
	latest    int64
	fulfilled int64
	escrowed  int64
)

func Post(cur realm, title, brief string, bounty int64) int64 {
	poster := wallet(0, cur)
	title = text(title, 80)
	brief = text(brief, 800)
	if bounty < 0 || bounty > maxEmber || bounty > 9223372036854775807-escrowed {
		panic("invalid bounty")
	}
	if bounty > 0 {
		ember.TransferFrom(cross(cur), poster, cur.Address(), bounty)
	}
	latest++
	q := &Quest{ID: latest, Title: title, Brief: brief, Poster: poster, Bounty: bounty, State: open}
	quests.Set(key(q.ID), q)
	escrowed += bounty
	emit("QuestPosted", q, poster)
	return q.ID
}

func Claim(cur realm, id int64) {
	solver := wallet(0, cur)
	q := mustQuest(id)
	if solver == q.Poster || !available(q) {
		panic("quest is not claimable by this wallet")
	}
	q.Solver, q.Proof, q.State = solver, "", claimed
	q.Deadline = runtime.ChainHeight() + claimBlocks
	emit("QuestClaimed", q, solver)
}

func Release(cur realm, id int64) {
	solver := wallet(0, cur)
	q := mustQuest(id)
	if solver != q.Solver || !active(q) {
		panic("only the active solver can release")
	}
	q.Solver, q.Proof, q.State, q.Deadline = "", "", open, 0
	emit("QuestReleased", q, solver)
}

func Submit(cur realm, id int64, proof string) {
	solver := wallet(0, cur)
	q := mustQuest(id)
	if q.State != claimed || solver != q.Solver || expired(q) {
		panic("only the active solver can submit once")
	}
	q.Proof, q.State = text(proof, 800), review
	emit("ProofSubmitted", q, solver)
}

func Complete(cur realm, id int64, solver address, proof string) {
	poster := wallet(0, cur)
	q := mustQuest(id)
	if poster != q.Poster || q.State != review || q.Solver != solver || q.Proof != proof {
		panic("only the poster can approve the current submission")
	}
	if q.Bounty > 0 {
		ember.Transfer(cross(cur), solver, q.Bounty)
	}
	escrowed -= q.Bounty
	q.State = complete
	fulfilled++
	recordSolve(solver)
	emit("QuestCompleted", q, solver)
}

func Cancel(cur realm, id int64) {
	poster := wallet(0, cur)
	q := mustQuest(id)
	if poster != q.Poster || !available(q) {
		panic("only the poster can cancel an open or expired quest")
	}
	if q.Bounty > 0 {
		ember.Transfer(cross(cur), poster, q.Bounty)
	}
	escrowed -= q.Bounty
	q.Solver, q.Proof, q.State, q.Deadline = "", "", cancelled, 0
	emit("QuestCancelled", q, poster)
}

func Tip(cur realm, id int64, recipient address, amount int64) {
	tipper := wallet(0, cur)
	q := mustQuest(id)
	if q.State == cancelled || recipient == tipper || (recipient != q.Poster && (q.State != complete || recipient != q.Solver)) {
		panic("tip a different wallet: the poster or the completed solver")
	}
	if amount < 1 || amount > maxEmber || amount > 9223372036854775807-q.Tips {
		panic("invalid tip")
	}
	ember.TransferFrom(cross(cur), tipper, recipient, amount)
	q.Tips += amount
	chain.Emit("QuestTipped", "id", key(id), "from", tipper.String(), "to", recipient.String(), "amount", key(amount))
}

func EscrowAddress() address { return chain.PackageAddress(boardPath) }
func Escrowed() int64        { return escrowed }

func wallet(_ int, rlm realm) address {
	caller := rlm.Previous()
	if !caller.IsUserCall() {
		panic("use a direct wallet call")
	}
	return caller.Address()
}

func key(n int64) string { return strconv.FormatInt(n, 10) }

func getQuest(id int64) *Quest {
	val := quests.Get(key(id))
	if val == nil {
		return nil
	}
	return val.(*Quest)
}

func mustQuest(id int64) *Quest {
	q := getQuest(id)
	if q == nil {
		panic("quest not found")
	}
	return q
}

func active(q *Quest) bool    { return q.State == claimed || q.State == review }
func expired(q *Quest) bool   { return active(q) && runtime.ChainHeight() >= q.Deadline }
func available(q *Quest) bool { return q.State == open || expired(q) }

func text(value string, limit int) string {
	value = strings.TrimSpace(value)
	if len(value) == 0 || len(value) > limit || !utf8.ValidString(value) {
		panic("text is empty, too long or invalid UTF-8")
	}
	for _, c := range value {
		if c < ' ' && c != '\n' && c != '\t' {
			panic("text contains control characters")
		}
	}
	return value
}

func emit(event string, q *Quest, actor address) {
	chain.Emit(event, "id", key(q.ID), "actor", actor.String())
}

func recordSolve(solver address) {
	score := Score{Solver: solver, Solved: 1}
	old := scores.Get(solver.String())
	if old != nil {
		score.Solved += old.(int64)
	}
	scores.Set(solver.String(), score.Solved)
	for i, entry := range leaders {
		if entry.Solver == solver {
			leaders = append(leaders[:i], leaders[i+1:]...)
			break
		}
	}
	leaders = append(leaders, score)
	for i := len(leaders) - 1; i > 0; i-- {
		prev := leaders[i-1]
		if prev.Solved > score.Solved || (prev.Solved == score.Solved && prev.Solver.String() < solver.String()) {
			break
		}
		leaders[i], leaders[i-1] = prev, score
	}
	if len(leaders) > pageSize {
		leaders = leaders[:pageSize]
	}
}

package hearthboard

import (
	"chain/runtime"
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xj5r20d9yy4hfap0x5w3p9nu4x27mekc8pscgs/ember"
)

const (
	boardPath = "gno.land/r/g1xj5r20d9yy4hfap0x5w3p9nu4x27mekc8pscgs/hearthboard"
	emberPath = "gno.land/r/g1xj5r20d9yy4hfap0x5w3p9nu4x27mekc8pscgs/ember"
)

func Render(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "account" && validAccount(parts[1]) {
		owner := address(parts[1])
		return ufmt.Sprintf(`{"balance":"%d","starterClaimed":%t}`, ember.BalanceOf(owner), ember.ClaimedStarter(owner))
	}
	if len(parts) == 2 && (parts[0] == "page" || parts[0] == "quest" || parts[0] == "api") {
		n, err := strconv.ParseInt(parts[1], 10, 64)
		if err != nil || n < 0 {
			return "No such board page."
		}
		switch parts[0] {
		case "page":
			return renderBoard(n)
		case "quest":
			if q := getQuest(n); q != nil {
				return renderQuest(q)
			}
		case "api":
			return renderAPI(n)
		}
	}
	if path == "" {
		return renderBoard(0)
	}
	if path == "leaderboard" {
		return renderLeaderboard()
	}
	return "No such board page."
}

func renderBoard(before int64) string {
	var out strings.Builder
	out.WriteString("# Hearthboard\n\n*The tavern quest board · On-chain quests, bounties and tips.*\n\n")
	out.WriteString(ufmt.Sprintf("**%d** posted · **%d** completed · **%d EMBER** in escrow\n\n", latest, fulfilled, escrowed))
	out.WriteString(ufmt.Sprintf("[Leaderboard](%s:leaderboard) · [EMBER token](%s) · [Web UI source](https://github.com/ZQ051031/gnome-tavern-hackathon/tree/main/web)\n\n",
		readPath(boardPath), readPath(emberPath)))
	out.WriteString("## Quest ledger\n\n")
	next := eachPage(before, func(q *Quest) {
		out.WriteString(ufmt.Sprintf("- [#%d · %s](%s:quest/%d) — **%s** · %d EMBER bounty · %d tipped\n",
			q.ID, sanitize.InlineText(q.Title), readPath(boardPath), q.ID, displayState(q), q.Bounty, q.Tips))
	})
	if latest == 0 {
		out.WriteString("The board is empty. Post the first quest from the web UI or CLI.\n")
	}
	if next != 0 {
		out.WriteString(ufmt.Sprintf("\n[Older quests](%s:page/%d)\n", readPath(boardPath), next))
	}
	if before != 0 {
		out.WriteString(ufmt.Sprintf("\n[Latest quests](%s)\n", readPath(boardPath)))
	}
	return out.String()
}

func renderQuest(q *Quest) string {
	s := ufmt.Sprintf("[← Quest ledger](%s)\n\n# #%d · %s\n\n**%s** · **%d EMBER** bounty · **%d EMBER** tipped\n\n%s\n\n**Poster:** `%s`\n",
		readPath(boardPath), q.ID, sanitize.InlineText(q.Title), displayState(q), q.Bounty, q.Tips, sanitize.InlineText(q.Brief), q.Poster.String())
	if q.Solver != "" {
		s += ufmt.Sprintf("\n**Solver:** `%s`\n", q.Solver.String())
	}
	if active(q) {
		s += ufmt.Sprintf("\n**Claim expires at block:** %d\n", q.Deadline)
	}
	if q.Proof != "" {
		s += "\n## Submitted proof\n\n" + sanitize.InlineText(q.Proof) + "\n"
	}
	return s
}

func renderLeaderboard() string {
	out := ufmt.Sprintf("[← Quest ledger](%s)\n\n# Hall of Embers\n\nRanked by poster-approved quests; tips do not affect rank.\n\n", readPath(boardPath))
	if len(leaders) == 0 {
		return out + "No completed quests yet.\n"
	}
	for _, row := range leaders {
		out += ufmt.Sprintf("1. `%s` — **%d** completed\n", row.Solver.String(), row.Solved)
	}
	return out
}

func renderAPI(before int64) string {
	var out strings.Builder
	out.WriteString(ufmt.Sprintf(`{"height":"%d","latest":"%d","completed":"%d","escrowed":"%d","escrow":"%s","quests":[`,
		runtime.ChainHeight(), latest, fulfilled, escrowed, EscrowAddress().String()))
	first := true
	next := eachPage(before, func(q *Quest) {
		if !first {
			out.WriteString(",")
		}
		first = false
		out.WriteString(ufmt.Sprintf(`{"id":"%d","title":"%s","brief":"%s","poster":"%s","solver":"%s","proof":"%s","bounty":"%d","tips":"%d","state":"%s","expired":%t,"deadline":"%d"}`,
			q.ID, encoded(q.Title), encoded(q.Brief), q.Poster.String(), q.Solver.String(), encoded(q.Proof), q.Bounty, q.Tips, q.State, expired(q), q.Deadline))
	})
	out.WriteString(ufmt.Sprintf(`],"next":"%d","leaders":[`, next))
	for i, row := range leaders {
		if i > 0 {
			out.WriteString(",")
		}
		out.WriteString(ufmt.Sprintf(`{"solver":"%s","solved":"%d"}`, row.Solver.String(), row.Solved))
	}
	out.WriteString("]}")
	return out.String()
}

func eachPage(before int64, visit func(*Quest)) int64 {
	id := latest
	if before > 0 && before <= latest {
		id = before - 1
	}
	for n := 0; id > 0 && n < pageSize; n++ {
		visit(mustQuest(id))
		id--
	}
	if id > 0 {
		return id + 1
	}
	return 0
}

func displayState(q *Quest) string {
	if expired(q) {
		return q.State + " · lease expired"
	}
	return q.State
}

func readPath(path string) string { return strings.TrimPrefix(path, "gno.land") }
func encoded(s string) string     { return base64.StdEncoding.EncodeToString([]byte(s)) }

func validAccount(s string) bool {
	if len(s) != 40 || !strings.HasPrefix(s, "g1") {
		return false
	}
	for _, c := range s[2:] {
		if !strings.ContainsRune("qpzry9x8gf2tvdw0s3jn54khce6mua7l", c) {
			return false
		}
	}
	return true
}

// Package erratabank records corrections, finder credit and book reward escrow.
package erratabank

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"unicode/utf8"

	"gno.land/p/g132vz03ycpaagtef4jmxjakstkppgyc5wn3r807/errata/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	Pending   = "Pending"
	Accepted  = "Accepted"
	Rejected  = "Rejected"
	Duplicate = "Duplicate"

	maxAmount  = 1<<63 - 1
	idKeyWidth = 19
)

type Book struct {
	ID               int
	Owner            address
	Title            string
	Edition          string
	Link             string
	RewardPerErratum int64
	Escrow           int64
	Open             bool
	CreatedAt        int64
}

type Erratum struct {
	ID          int
	BookID      int
	Finder      address
	Location    string
	Text        string
	Status      string
	DuplicateOf int
	SubmittedAt int64
	ReviewedAt  int64
	Paid        int64
	Note        string
}

// Each book indexes all reports and each status by submission ID.
type bookRecord struct {
	book      Book
	all       avl.Tree
	pending   avl.Tree
	accepted  avl.Tree
	rejected  avl.Tree
	duplicate avl.Tree
}

func (record *bookRecord) reports(status string) *avl.Tree {
	switch status {
	case "":
		return &record.all
	case Pending:
		return &record.pending
	case Accepted:
		return &record.accepted
	case Rejected:
		return &record.rejected
	case Duplicate:
		return &record.duplicate
	}
	return nil
}

type finderRecord struct {
	paid int64
	ids  avl.Tree
}

var (
	books         = avl.NewTree()
	errataByID    = avl.NewTree()
	finders       = avl.NewTree()
	nextErratumID int
	realmURL      string
)

func init(cur realm) {
	realmURL = strings.TrimPrefix(cur.PkgPath(), "gno.land") + ":"
}

func idKey(id int) string {
	digits := strconv.Itoa(id)
	return strings.Repeat("0", idKeyWidth-len(digits)) + digits
}

func bookByID(id int) *bookRecord {
	if id <= 0 {
		return nil
	}
	book, _ := books.Get(idKey(id)).(*bookRecord)
	return book
}

func reportByID(id int) *Erratum {
	if id <= 0 {
		return nil
	}
	report, _ := errataByID.Get(idKey(id)).(*Erratum)
	return report
}

func requireBook(id int) *bookRecord {
	record := bookByID(id)
	if record == nil {
		panic(errBookMissing)
	}
	return record
}

func requireOwner(record *bookRecord, caller address) {
	if record.book.Owner != caller {
		panic(errOwnerOnly)
	}
}

func requireReview(id int, caller address) (*bookRecord, *Erratum) {
	report := reportByID(id)
	if report == nil {
		panic(errErratumMiss)
	}
	record := requireBook(report.BookID)
	requireOwner(record, caller)
	if report.Status != Pending {
		panic(errPendingOnly)
	}
	return record, report
}

func callerAddress(cur realm) address {
	if !cur.IsCurrent() {
		panic(errCurrentRealm)
	}
	return cur.Previous().Address()
}

// A direct MsgCall credits this realm with the transaction's send before execution.
func inboundUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic(errDirectCall)
	}
	coins := unsafe.OriginSend()
	if len(coins) == 0 {
		return 0
	}
	if len(coins) != 1 || coins[0].Denom != "ugnot" {
		panic(errPaymentDenom)
	}
	if coins[0].Amount <= 0 {
		panic(errPayment)
	}
	return coins[0].Amount
}

func rejectCoins(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) != 0 {
		panic(errRejectCoins)
	}
}

func addAmount(total, amount int64) int64 {
	if amount > maxAmount-total {
		panic(errOverflow)
	}
	return total + amount
}

func sendUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

func requiredText(field, text string, max int) string {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" || !utf8.ValidString(text) || utf8.RuneCountInString(text) > max {
		panic(field + " must contain 1 to " + strconv.Itoa(max) + " characters")
	}
	return trimmed
}

func reviewNote(note string) string {
	if strings.TrimSpace(note) == "" {
		return ""
	}
	return requiredText("review note", note, 300)
}

// CreateBook registers an open book and optionally credits inbound reward escrow.
func CreateBook(cur realm, title, edition, link string, rewardPerErratum int64) int {
	owner := callerAddress(cur)
	escrow := inboundUgnot(cur)
	title = requiredText("title", title, 120)
	edition = requiredText("edition", edition, 120)
	link = requiredText("link", link, 300)
	if sanitize.URL(link) == "" {
		panic("unsupported book link")
	}
	if rewardPerErratum < 0 {
		panic("reward cannot be negative")
	}
	id := books.Size() + 1
	books.Set(idKey(id), &bookRecord{book: Book{
		ID: id, Owner: owner, Title: title, Edition: edition, Link: link,
		RewardPerErratum: rewardPerErratum, Escrow: escrow, Open: true, CreatedAt: runtime.ChainHeight(),
	}})
	chain.Emit("BookCreated", "book", strconv.Itoa(id), "owner", owner.String(),
		"reward", strconv.FormatInt(rewardPerErratum, 10), "escrow", strconv.FormatInt(escrow, 10))
	return id
}

// FundBook credits a book with ugnot supplied by any direct caller.
func FundBook(cur realm, bookID int) {
	caller := callerAddress(cur)
	amount := inboundUgnot(cur)
	if amount == 0 {
		panic(errPayment)
	}
	record := requireBook(bookID)
	record.book.Escrow = addAmount(record.book.Escrow, amount)
	chain.Emit("BookFunded", "book", strconv.Itoa(bookID), "funder", caller.String(),
		"amount", strconv.FormatInt(amount, 10))
}

// Submit records a report. Increasing IDs break ties within a block.
func Submit(cur realm, bookID int, location, text string) int {
	finder := callerAddress(cur)
	rejectCoins(cur)
	record := requireBook(bookID)
	if !record.book.Open {
		panic(errClosed)
	}
	if finder == record.book.Owner {
		panic(errSelfSubmit)
	}
	location = requiredText("location", location, 120)
	text = requiredText("text", text, 1000)
	nextErratumID++
	id := nextErratumID
	key := idKey(id)
	errataByID.Set(key, &Erratum{
		ID: id, BookID: bookID, Finder: finder, Location: location, Text: text,
		Status: Pending, SubmittedAt: runtime.ChainHeight(),
	})
	record.all.Set(key, id)
	record.pending.Set(key, id)
	chain.Emit("ErratumSubmitted", "book", strconv.Itoa(bookID), "erratum", strconv.Itoa(id),
		"finder", finder.String())
	return id
}

func review(record *bookRecord, report *Erratum, status, note string) {
	key := idKey(report.ID)
	record.pending.Remove(key)
	record.reports(status).Set(key, report.ID)
	report.Status = status
	report.ReviewedAt = runtime.ChainHeight()
	report.Note = note
}

// Accept credits the finder and pays the full reward when escrow covers it.
func Accept(cur realm, erratumID int, note string) {
	owner := callerAddress(cur)
	rejectCoins(cur)
	record, report := requireReview(erratumID, owner)
	review(record, report, Accepted, reviewNote(note))

	addr := report.Finder.String()
	finder, ok := finders.Get(addr).(*finderRecord)
	if !ok {
		finder = &finderRecord{}
		finders.Set(addr, finder)
	}
	finder.ids.Set(idKey(erratumID), erratumID)
	reward := record.book.RewardPerErratum
	if reward > 0 && record.book.Escrow >= reward {
		record.book.Escrow -= reward
		report.Paid = reward
		finder.paid = addAmount(finder.paid, reward)
		sendUgnot(cur, report.Finder, reward)
	}
	chain.Emit("ErratumAccepted", "book", strconv.Itoa(report.BookID), "erratum", strconv.Itoa(erratumID),
		"finder", addr, "paid", strconv.FormatInt(report.Paid, 10))
}

// Reject closes a pending submission without finder credit.
func Reject(cur realm, erratumID int, note string) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record, report := requireReview(erratumID, caller)
	review(record, report, Rejected, reviewNote(note))
	chain.Emit("ErratumRejected", "book", strconv.Itoa(report.BookID), "erratum", strconv.Itoa(erratumID))
}

// MarkDuplicate links a pending report to an earlier accepted report in the same book.
func MarkDuplicate(cur realm, erratumID, originalID int) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record, report := requireReview(erratumID, caller)
	original := reportByID(originalID)
	if original == nil || original.BookID != report.BookID || original.ID >= report.ID ||
		original.Status != Accepted {
		panic(errDuplicate)
	}
	report.DuplicateOf = originalID
	review(record, report, Duplicate, "")
	chain.Emit("ErratumMarkedDuplicate", "book", strconv.Itoa(report.BookID), "erratum", strconv.Itoa(erratumID),
		"original", strconv.Itoa(originalID))
}

// SetBookOpen controls new submissions. Existing submissions remain reviewable.
func SetBookOpen(cur realm, bookID int, open bool) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record := requireBook(bookID)
	requireOwner(record, caller)
	record.book.Open = open
	chain.Emit("BookOpenChanged", "book", strconv.Itoa(bookID), "open", strconv.FormatBool(open))
}

// Withdraw returns unused escrow to the book owner.
func Withdraw(cur realm, bookID int, amount int64) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record := requireBook(bookID)
	requireOwner(record, caller)
	if amount <= 0 || amount > record.book.Escrow {
		panic(errWithdraw)
	}
	record.book.Escrow -= amount
	sendUgnot(cur, caller, amount)
	chain.Emit("BookWithdrawn", "book", strconv.Itoa(bookID), "owner", caller.String(),
		"amount", strconv.FormatInt(amount, 10))
}

func GetBook(id int) (Book, bool) {
	if record := bookByID(id); record != nil {
		return record.book, true
	}
	return Book{}, false
}

func ListBooks(offset, limit int) []Book {
	var result []Book
	if offset < 0 || limit <= 0 || offset >= books.Size() {
		return result
	}
	if remaining := books.Size() - offset; limit > remaining {
		limit = remaining
	}
	books.IterateByOffset(offset, limit, func(_ string, value any) bool {
		result = append(result, value.(*bookRecord).book)
		return false
	})
	return result
}

func GetErratum(id int) (Erratum, bool) {
	if report := reportByID(id); report != nil {
		return *report, true
	}
	return Erratum{}, false
}

func listReports(tree *avl.Tree, offset, limit int) []Erratum {
	var result []Erratum
	if tree == nil || offset < 0 || limit <= 0 || offset >= tree.Size() {
		return result
	}
	if remaining := tree.Size() - offset; limit > remaining {
		limit = remaining
	}
	tree.IterateByOffset(offset, limit, func(_ string, value any) bool {
		report, _ := GetErratum(value.(int))
		result = append(result, report)
		return false
	})
	return result
}

// ListErrata returns reports in submission order. An empty status selects all reports.
func ListErrata(bookID int, status string, offset, limit int) []Erratum {
	if record := bookByID(bookID); record != nil {
		return listReports(record.reports(status), offset, limit)
	}
	return nil
}

func acceptedEntries(reports []Erratum) []errata.Entry {
	var entries []errata.Entry
	for _, report := range reports {
		entries = append(entries, errata.Entry{
			Location: report.Location, Text: report.Text, Finder: report.Finder.String(),
			FoundAt: report.SubmittedAt, Paid: report.Paid, Link: finderURL(report.Finder),
		})
	}
	return entries
}

func AcceptedEntries(bookID int) []errata.Entry {
	return AcceptedEntriesPage(bookID, 0, int(maxAmount))
}

// AcceptedEntriesPage supports integrations that render a bounded page.
func AcceptedEntriesPage(bookID, offset, limit int) []errata.Entry {
	return acceptedEntries(ListErrata(bookID, Accepted, offset, limit))
}

func FinderStats(addr address) (accepted int, paid int64) {
	if finder, ok := finders.Get(addr.String()).(*finderRecord); ok {
		return finder.ids.Size(), finder.paid
	}
	return 0, 0
}

package erratabank

import (
	"strconv"

	"gno.land/p/g132vz03ycpaagtef4jmxjakstkppgyc5wn3r807/errata/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
)

const pageSize = 20

var router = mux.NewRouter()

func init() {
	router.HandleFunc("", renderHome)
	router.HandleFunc("book/{id}", renderBook)
	router.HandleFunc("book/{id}/pending", renderPending)
	router.HandleFunc("book/{id}/all", renderAll)
	router.HandleFunc("erratum/{id}", renderErratum)
	router.HandleFunc("finder/{addr}", renderFinder)
	router.SetNotFoundHandler(func(w *mux.ResponseWriter, _ *mux.Request) {
		notFound(w, "Page")
	})
}

// Render is the public Markdown entry point for gnoweb.
func Render(path string) string {
	return router.Render(path)
}

func finderURL(addr address) string {
	return realmURL + "finder/" + addr.String()
}

func bookRoute(id int) string {
	return "book/" + strconv.Itoa(id)
}

func erratumURL(id int) string {
	return realmURL + "erratum/" + strconv.Itoa(id)
}

func bookURL(id int) string {
	return realmURL + bookRoute(id)
}

func pageOffset(req *mux.Request, total int) (int, bool) {
	value := req.Query.Get("page")
	if value == "" {
		return 0, true
	}
	page, err := strconv.Atoi(value)
	if err != nil || page < 1 || (page > 1 && page-1 > (total-1)/pageSize) {
		return 0, false
	}
	return (page - 1) * pageSize, true
}

func pagination(w *mux.ResponseWriter, route string, offset, total int) {
	if total <= pageSize {
		return
	}
	page := offset/pageSize + 1
	last := (total-1)/pageSize + 1
	w.Write(ufmt.Sprintf("\nPage %d of %d", page, last))
	if page > 1 {
		w.Write(ufmt.Sprintf(" · [Previous](%s%s?page=%d)", realmURL, route, page-1))
	}
	if page < last {
		w.Write(ufmt.Sprintf(" · [Next](%s%s?page=%d)", realmURL, route, page+1))
	}
	w.Write("\n")
}

func notFound(w *mux.ResponseWriter, item string) {
	w.Write("# " + item + " not found\n\n[Erratabank home](" + realmURL + ")\n")
}

func renderHome(w *mux.ResponseWriter, req *mux.Request) {
	offset, ok := pageOffset(req, books.Size())
	if !ok {
		notFound(w, "Page")
		return
	}
	w.Write("# Erratabank\n\n")
	w.Write("Erratabank is a public errata page for books, courses, and technical docs.\n\n")
	w.Write("Each accepted correction credits its finder. Authors can escrow a reward for accepted reports.\n\n")
	w.Write("Use the Actions tab to register a book, submit a correction, or review reports for a book you own.\n\n")
	w.Write("## Books\n\n")
	if books.Size() == 0 {
		w.Write("No books registered yet.\n")
	} else {
		w.Write("| Book | Owner | Reward per erratum | Escrow | Accepted |\n")
		w.Write("| --- | --- | ---: | ---: | ---: |\n")
		for _, book := range ListBooks(offset, pageSize) {
			w.Write(ufmt.Sprintf("| [%s](%s) | %s | %s | %s | %d |\n",
				sanitize.TableCell(book.Title), bookURL(book.ID), errata.ShortAddr(book.Owner.String()),
				errata.FormatUgnot(book.RewardPerErratum), errata.FormatUgnot(book.Escrow),
				requireBook(book.ID).accepted.Size()))
		}
		pagination(w, "", offset, books.Size())
	}
	w.Write("\nStarted 23 Nov 2026 for Gnome Tavern.\n")
}

func routeBook(w *mux.ResponseWriter, req *mux.Request) *bookRecord {
	if id, err := strconv.Atoi(req.GetVar("id")); err == nil {
		if record := bookByID(id); record != nil {
			return record
		}
	}
	notFound(w, "Book")
	return nil
}

func renderBook(w *mux.ResponseWriter, req *mux.Request) {
	record := routeBook(w, req)
	if record == nil {
		return
	}
	offset, ok := pageOffset(req, record.accepted.Size())
	if !ok {
		notFound(w, "Page")
		return
	}
	book := record.book
	state := "Closed"
	if book.Open {
		state = "Open"
	}
	w.Write(ufmt.Sprintf("# %s\n\n- Edition: %s\n- Owner: %s\n- Submissions: %s\n- Reward per erratum: %s\n- Escrow left: %s\n",
		sanitize.InlineText(book.Title), sanitize.InlineText(book.Edition), sanitize.InlineCode(book.Owner.String()),
		state, errata.FormatUgnot(book.RewardPerErratum), errata.FormatUgnot(book.Escrow)))
	if url := sanitize.URL(book.Link); url != "" {
		w.Write("- [Read the book](" + url + ")\n")
	}
	w.Write("\n")
	w.Write(errata.RenderSection("Accepted errata", AcceptedEntriesPage(book.ID, offset, pageSize)))
	pagination(w, bookRoute(book.ID), offset, record.accepted.Size())
	w.Write(ufmt.Sprintf("\n[Pending (%d)](%s/pending) · [All reports (%d)](%s/all) · Rejected: %d · Duplicates: %d · [All books](%s)\n",
		record.pending.Size(), bookURL(book.ID), record.all.Size(), bookURL(book.ID),
		record.rejected.Size(), record.duplicate.Size(), realmURL))
}

func renderPending(w *mux.ResponseWriter, req *mux.Request) {
	renderReportList(w, req, Pending, "Pending reports", "/pending")
}

func renderAll(w *mux.ResponseWriter, req *mux.Request) {
	renderReportList(w, req, "", "All reports", "/all")
}

func renderReportList(w *mux.ResponseWriter, req *mux.Request, status, heading, suffix string) {
	record := routeBook(w, req)
	if record == nil {
		return
	}
	tree := record.reports(status)
	offset, ok := pageOffset(req, tree.Size())
	if !ok {
		notFound(w, "Page")
		return
	}
	book := record.book
	w.Write(ufmt.Sprintf("# %s\n\n[Back to %s](%s)\n\n",
		heading, sanitize.InlineText(book.Title), bookURL(book.ID)))
	if tree.Size() == 0 {
		w.Write("No reports here yet.\n")
		return
	}
	w.Write("| Report | Location | Status | Finder | Height found |\n| --- | --- | --- | --- | ---: |\n")
	for _, report := range listReports(tree, offset, pageSize) {
		w.Write(ufmt.Sprintf("| [#%d](%s) | %s | %s | [%s](%s) | %d |\n",
			report.ID, erratumURL(report.ID), sanitize.TableCell(report.Location), report.Status,
			errata.ShortAddr(report.Finder.String()), finderURL(report.Finder), report.SubmittedAt))
	}
	pagination(w, bookRoute(book.ID)+suffix, offset, tree.Size())
}

func renderErratum(w *mux.ResponseWriter, req *mux.Request) {
	id, err := strconv.Atoi(req.GetVar("id"))
	report, ok := GetErratum(id)
	if err != nil || !ok {
		notFound(w, "Erratum")
		return
	}
	book, _ := GetBook(report.BookID)
	w.Write(ufmt.Sprintf("# Erratum #%d\n\n[Back to %s](%s)\n\n",
		id, sanitize.InlineText(book.Title), bookURL(book.ID)))
	w.Write(ufmt.Sprintf("- Location: %s\n- Finder: [%s](%s)\n- Status: %s\n- Paid: %s\n\n## Correction\n\n%s\n\n",
		sanitize.InlineText(report.Location), report.Finder.String(), finderURL(report.Finder),
