package cutpurse

// render_job.gno — the job. Pot, alarm, seats, and exactly one control panel
// for the phase the job is in. Every panel says what the button does to
// your money before you press it.

import (
	"strconv"
	"strings"
)

// renderJobPath routes job/<id>, job/<id>/<you>, and the commit and reveal
// steps under them. j/<id> is the same page.
func renderJobPath(parts []string) string {
	if len(parts) < 2 {
		return renderMissing("job")
	}
	id := atoiOr(parts[1], -1)
	if id < 0 {
		return renderMissing(text(parts[1]))
	}
	at := 2
	you := ""
	if len(parts) > 2 && address(parts[2]).IsValid() {
		you = parts[2]
		at = 3
	}
	if len(parts) <= at {
		parts = append(parts, "")
	}
	rest := parts[at:]
	jv, ok := jobView(id)
	if !ok {
		return pageHead("No such job", "Nothing has been opened under "+
			"`"+strconv.FormatInt(id, 10)+"`.", "Home", hub) +
			notice("WARNING", "Job not found", "") +
			"Try " + md("the board", self("jobs")) + ".\n"
	}
	switch {
	case rest[0] == "":
		return renderJob(jv, you)
	case rest[0] == "commit" && len(rest) == 1:
		return renderCommitChoose(jv, you)
	case rest[0] == "commit":
		return renderCommitHash(jv, you, uint8(atoiOr(rest[1], 1)))
	case rest[0] == "reveal":
		return renderReveal(jv, you)
	}
	return renderJob(jv, you)
}

// ----- the job page -----

func renderJob(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(pageHeadBare(jobTitle(jv),
		"Job "+strconv.FormatInt(jv.ID, 10)+" · "+phaseBadge(jv.Phase)+roundLabel(jv)))

	if jv.Phase >= uint8(PhaseSettled) {
		b.WriteString(endBody(jv, you))
		return b.String()
	}

	// The numbers a player judges, in one line while the round is running —
	// three picture cards are wasted gas there. Cards stay on the open page,
	// where the join decision is the whole screen.
	if jv.Phase == 0 {
		b.WriteString(cards(
			"**Pot**\n\n"+coins(jv.Pot)+"\n\nSeat fee "+money(jv.Fee)+" GNOT",
			"**Seats**\n\n"+seatStrip(int64(jv.NSeats))+"\n\n"+
				strconv.FormatInt(int64(jv.NSeats), 10)+" of 4 filled",
			"**Clock**\n\n"+clockCell(jv)+"\n\nOn alarm "+alarmMeter(jv.Alarm),
		))
		b.WriteString("\n")
	} else {
		b.WriteString(jobFacts(jv))
		b.WriteString(phaseBanner(jv))
	}

	b.WriteString(traitorPanel(jv))
	b.WriteString(seatTable(jv, you))
	arch, settled := Archived(jv.ID)
	b.WriteString(controlPanel(jv, you, settled, arch))
	b.WriteString(nav("The board", self("jobs"), "Home", self("")))
	return b.String()
}

// jobFacts is the one-line state of a running job: pot, fee, seats, clock,
// alarm. Cheaper than three cards and hard to read past, which is what a
// player in a timed round wants.
func jobFacts(jv JobView) string {
	return "Round " + strconv.FormatInt(int64(jv.Round), 10) + "/3 · pot " + coins(jv.Pot) +
		" · " + seatStrip(int64(jv.NSeats)) + " " +
		strconv.FormatInt(int64(jv.NSeats), 10) + "/4 · " + clockCell(jv) + " · " +
		alarmBars(jv.Alarm) + " · " + strconv.FormatInt(jv.Secured, 10) + " secured\n\n"
}

// ----- the two end states -----

// endBody is the job after the last round: verdict, then the money, then who
// took what. The three grey cards go away here — the verdict is the number.
func endBody(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(endVerdict(jv))
	b.WriteString(takeCards(jv))
	b.WriteString(scoreboard(jv, you))
	arch, _ := Archived(jv.ID)
	b.WriteString(controlPanel(jv, you, jv.Settled, arch))
	b.WriteString(nav("The board", self("jobs"), "Every settled job", self("ledger")))
	return b.String()
}

// endVerdict is the loudest block on the site: who did it, and what it cost.
// Money is written plainly here — coins() already bolds, and bolding a bold
// reads as a mistake.
func endVerdict(jv JobView) string {
	snitch, _, snitchPaid := snitchFacts(jv)
	if jv.Alarm >= alarmTotal {
		// Heading, then exactly one sentence of explanation, then the cost.
		// A stranger has to get the mechanic from that sentence alone.
		body := "### 🐀 Busted\n\n"
		if snitch >= 0 {
			body += "**Seat " + strconv.FormatInt(int64(snitch)+1, 10) + " was the snitch.** " +
				payoffLine(jv, snitch, snitchPaid) + " They walk.\n\n"
		} else {
			body += "The door slammed at round " + strconv.FormatInt(int64(jv.Round), 10) + ".\n\n"
		}
		if jv.Secured == 0 {
			body += "**Nothing reached the door.** " + strconv.FormatInt(bustedLost(jv), 10) +
				" was still on the shelf.\n"
		} else {
			body += "What reached the door survives: **" + strconv.FormatInt(jv.Secured, 10) +
				" secured** of " + strconv.Itoa(MaxSecured) + ". " +
				strconv.FormatInt(bustedLost(jv), 10) + " was still on the shelf.\n"
		}
		return frame(body) + "\n"
	}

	body := "### Escaped\n\n"
	if snitch >= 0 {
		body += "**Seat " + strconv.FormatInt(int64(snitch)+1, 10) + " was the snitch** — and got " +
			"away with it: on an escape they take nothing extra, the same share as everyone.\n\n"
	}
	if jv.Secured == 0 {
		body += "Three rounds cleared and the alarm never reached 3, but nothing was carried " +
			"out — the pot still splits.\n\n"
	} else {
		body += "Three rounds cleared, alarm never reached 3. **" +
			strconv.FormatInt(jv.Secured, 10) + " secured** of " + strconv.Itoa(MaxSecured) +
			" — that is what sets the treasury cut.\n\n"
	}
	body += "The remainder split by contribution below. It could have been worse.\n"
	return frame(body) + "\n"
}

// payoffLine is the snitch's payoff in one sentence, pitched at someone who has
// never played. The contrast does the teaching: the 60% is only outrageous when
// it is set against what that seat actually did.
func payoffLine(jv JobView, seat int, paid int64) string {
	shares := payoutShares(jv)
	rank, didLeast := 1, true
	for i := range jv.Seats {
		if i == seat {
			continue
		}
		if shares[i] >= shares[seat] {
			rank++
		}
		if jv.Seats[i].Contribution < jv.Seats[seat].Contribution {
			didLeast = false
		}
	}
	amount := money(paid) + " GNOT"
	switch {
	case rank == 1 && didLeast:
		return "A bust pays the snitch 60% of the pot: " + amount +
			", taken before the crew is paid, from the seat that did the least."
	case rank == 1:
		return "A bust pays the snitch 60% of the pot: " + amount +
			", before the crew is paid — more than any seat that worked for it."
	case didLeast:
		return "A bust pays the snitch 60% of the pot: " + amount +
			", before the crew is paid, more than the seat that did most."
	}
	return "A bust pays the snitch 60% of the pot: " + amount + ", before the crew is paid at all."
}

// bustedLost is loot that never reached the door.
func bustedLost(jv JobView) int64 {
	if jv.Loot <= jv.Secured {
		return 0
	}
	return jv.Loot - jv.Secured
}

// takeCards is the money, split into the three places it went. On a bust the
// 60% is the story; on an escape the treasury cut is, because the snitch took
// nothing extra there.
func takeCards(jv JobView) string {
	shares := payoutShares(jv)
	if jv.Alarm >= alarmTotal {
		var snitchGet, crewGet int64
		for i, v := range shares {
			if i == int(jv.Traitor) {
				snitchGet += v
				continue
			}
			crewGet += v
		}
		return cards(
			"**The pot**\n\n"+coins(jv.Pot)+"\n\nthe whole stake",
			"**To the snitch**\n\n"+coins(snitchGet)+"\n\n60%, plus their split",
			"**To the crew**\n\n"+coins(crewGet)+"\n\nwhat is left",
		) + "\n"
	}

	var split int64
	for _, v := range shares {
		split += v
	}
	return cards(
		"**The pot**\n\n"+coins(jv.Pot)+"\n\nthe whole stake",
		"**To the treasury**\n\n"+coins(treasuryCut(jv))+"\n\n5%, scaled by what was secured",
		"**Split by contribution**\n\n"+coins(split)+"\n\nbetween all seats",
	) + "\n"
}

// scoreboard ranks the crew by what they took. The snitch is first, because
// the pot always pays them most — that is the point of the game.
func scoreboard(jv JobView, you string) string {
	shares := payoutShares(jv)
	order := make([]int, len(jv.Seats))
	for i := range order {
		order[i] = i
	}
	for i := 1; i < len(order); i++ {
		for k := i; k > 0 && shares[order[k]] > shares[order[k-1]]; k-- {
			order[k], order[k-1] = order[k-1], order[k]
		}
	}

	var b strings.Builder
	b.WriteString("## What everyone took\n\n")
	b.WriteString("| Seat | Player | Pick | Contribution | Took |\n|---:|---|---|---:|---:|\n")
	for _, i := range order {
		seat := jv.Seats[i]
		mark := ""
		if i == int(jv.Traitor) {
			mark = " 🐀"
		}
		pick := actionCell(seat.Action)
		if seat.Auto {
			pick += " `auto`"
		}
		b.WriteString("| " + strconv.Itoa(i+1) + mark + " | " + who(seat.Addr.String()) +
			youMark(seat.Addr.String(), you) + " | " + pick + " | " +
			strconv.FormatInt(seat.Contribution, 10) + " | **" + money(shares[i]) + "** |\n")
	}
	b.WriteString("\nPaid by contribution, remainder to the top contributor. ")
	if jv.Traitor >= 0 {
		b.WriteString("The 🐀 seat is the snitch.")
	}
	b.WriteString("\n\n")
	return b.String()
}

// snitchFacts is the snitch seat, how to describe them, and what they take.
func snitchFacts(jv JobView) (seat int, where string, paid int64) {
	seat = int(jv.Traitor)
	if seat < 0 || seat >= len(jv.Seats) {
		return -1, "", 0
	}
	where = "sealed at the close of round one"
	if jv.Round > 1 {
		where = "the crew never suspected"
	}
	if jv.Alarm >= alarmTotal {
		paid = jv.Pot * TraitorBustShare / 100
	}
	return seat, where, paid
}

// phaseBanner is only for the deadline running out. The round facts live in the
// one-line jobFacts above it; a second block repeating them is gas for nothing.
func phaseBanner(jv JobView) string {
	if jv.Deadline > jv.Height {
		return ""
	}
	return notice("CAUTION", "Deadline passed — nudge the clock",
		"The next phase is one Tick away. Anyone can send it and it pays nothing.")
}

// traitorPanel holds the snitch shut until the end states name them.
func traitorPanel(jv JobView) string {
	if jv.Round < 1 {
		return ""
	}
	return "🐀 **The snitch is among you** " + segLocked + " " + segLocked + " " + segLocked + " " +
		segLocked + "\n\n" +
		"One seat is on the take: a bust pays it 60% of the pot, a clean escape nothing extra. " +
		"Sealed from round one out of every commit hash, and nobody sets it.\n\n"
}

// seatTable is the crew, in seat order.
func seatTable(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString("## The crew\n\n")
	if len(jv.Seats) == 0 {
		b.WriteString(notice("NOTE", "Empty cellar. No one has taken a seat.", "") + "\n")
		return b.String()
	}
	// Contribution is zero for everyone until a reveal lands, so the column only
	// exists once it can carry a number.
	withContribution := jv.Round > 1 || jv.Phase >= 2
	if withContribution {
		b.WriteString("| Seat | Player | This round | Contribution |\n|---:|---|---|---:|\n")
	} else {
		b.WriteString("| Seat | Player | This round |\n|---:|---|---|\n")
	}
	for i, seat := range jv.Seats {
		addr := seat.Addr.String() // one bech32 encode per row, not two
		b.WriteString("| " + strconv.Itoa(i+1) + " | " + who(addr) + youMark(addr, you) +
			" | " + seatState(jv, seat) + " |")
		if withContribution {
			b.WriteString(" " + strconv.FormatInt(seat.Contribution, 10) + " |")
		}
		b.WriteString("\n")
	}
	if withContribution {
		b.WriteString("\nContribution is what the payout splits by. " +
			md("How that works", self("rules")) + ".\n\n")
	} else {
		b.WriteString("\n")
	}
	return b.String()
}

// seatState never leaks a pick before the reveal.
func seatState(jv JobView, seat SeatView) string {
	if jv.Revealed && seat.Revealed {
		s := actionCell(seat.Action)
		if seat.Auto {
			s += " `auto`"
		}
		return s
	}
	if seat.Committed {
		return "🔒 committed"
	}
	if jv.Phase == 1 || jv.Phase == 2 {
		return "▪"
	}
	return "—"
}

// roundLabel is the round in a page header; an open job has none yet.
func roundLabel(jv JobView) string {
	if jv.Phase == 0 || jv.Round == 0 {
		return " · seats filling"
	}
	return " · round " + strconv.FormatInt(int64(jv.Round), 10) + "/" +
		strconv.FormatInt(Rounds, 10)
}

// ----- controls -----

func controlPanel(jv JobView, you string, settled bool, arch Result) string {
	var b strings.Builder
	b.WriteString("## " + panelTitle(jv) + "\n\n")
	switch {
	case jv.Phase == 0:
		b.WriteString(joinPanel(jv))
		b.WriteString(kickPanel(jv))
		b.WriteString(startPanel(jv))
	case jv.Phase == 1:
		b.WriteString("Your pick stays hidden: the page hashes it and signs only the hash. " +
			"Keep the salt it hands back — without it the pick cannot be revealed.\n\n")
		b.WriteString(stepButtons(jv, you, "Commit your pick", "commit/"))
	case jv.Phase == 2:
		b.WriteString(notice("CAUTION", "Reveal or lose the pick",
			"An unrevealed pick counts as "+actionCell(4)+", earns nothing and costs a reputation point."))
		b.WriteString(stepButtons(jv, you, "Reveal", "reveal"))
	case jv.Phase >= 3:
		b.WriteString(settlePanel(jv, settled, arch))
	}
	b.WriteString(tickPanel(jv))
	return b.String()
}

func panelTitle(jv JobView) string {
	switch jv.Phase {
	case 1:
		return "Your pick"
	case 2:
		return "Reveal"
	case 3, 4:
		if jv.Settled {
			return "Settled"
		}
		return "The pot"
	}
	return "Take a seat"
}

// seatLink is the viewer's own view of the job, so a form can name its seat.
func seatLink(jv JobView, you, suffix string) string {
	p := "job/" + strconv.FormatInt(jv.ID, 10) + "/"
	if you != "" {
		p += you + "/"
	}
	return self(p + suffix)
}

// stepButtons sends the viewer to the commit chooser or the reveal form.
func stepButtons(jv JobView, you string, label, sub string) string {
	if jv.Deadline <= jv.Height {
		return "Deadline passed — " + md("Tick it first", seatLink(jv, you, "")) + ".\n\n"
	}
	b := button(label, seatLink(jv, you, sub), "")
	if you == "" {
		b += "\n\n" + md("Open your own seat view", seatLink(jv, you, "")) +
			" first if the next page cannot find your seat — it reads your address from the URL."
	}
	return b + "\n\n"
}

// joinPanel is the join form, or why you cannot join.
func joinPanel(jv JobView) string {
	var b strings.Builder
	if int(jv.NSeats) >= seatTotal {
		b.WriteString(notice("NOTE", "Full. Four seats, all taken.", "Watch this page: a kick frees one."))
		return b.String()
	}
	b.WriteString("Joining puts up " + coins(jv.Fee) + " of your own, into escrow. " +
		"A seat you take is seat " + strconv.FormatInt(int64(jv.NSeats)+1, 10) + ".\n\n")
	b.WriteString("<gno-form exec=\"JoinJob\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString(sendFor(jv.Fee, "That is the seat's fee, into the pot."))
	return b.String()
}

// kickPanel lets only the creator prune seats while the job is open.
func kickPanel(jv JobView) string {
	if jv.Phase != 0 || len(jv.Seats) < 2 {
		return ""
	}
	var b strings.Builder
	b.WriteString("<gno-form exec=\"Kick\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	for i, seat := range jv.Seats {
		b.WriteString(selectOpt("seat", strconv.Itoa(i), short(seat.Addr.String()), i == len(jv.Seats)-1))
	}
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Creator only. A kicked seat is refunded in full, immediately._\n\n")
	b.WriteString(noSend())
	return b.String()
}

// startPanel is the creator's go signal, once two seats are filled.
func startPanel(jv JobView) string {
	if int(jv.NSeats) < 2 {
		return notice("NOTE", "One player is not a job",
			"Seats fill for now. Send this page's link to a second wallet; Start appears at two.")
	}
	var b strings.Builder
	b.WriteString("<gno-form exec=\"Start\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Creator only. This closes the seats and opens round one. Empty seats stay empty._\n\n")
	b.WriteString(noSend())
	return b.String()
}

// settlePanel is the permissionless settle, plus the split it will pay. Once
// the job is archived the form and the summary both go: the receipt replaces
// them, and a second send would only panic.
func settlePanel(jv JobView, settled bool, arch Result) string {
	var b strings.Builder
	if settled {
		b.WriteString(notice("SUCCESS", "Settled in block "+strconv.FormatInt(arch.At, 10),
			"Settled once, permanently — the pot cannot move again. "+
				md("Entry "+strconv.FormatInt(jv.ID, 10), self("ledger/1"))+" is the record."))
		if arch.Payouts != "" {
			b.WriteString("The realm logged the send: `" + arch.Payouts + "`\n\n")
		}
		return b.String()
	}

	if jv.Alarm >= alarmTotal {
		b.WriteString("Pot " + coins(jv.Pot) + " · 60% to the snitch · the rest by contribution.\n\n")
	} else {
		b.WriteString("Pot " + coins(jv.Pot) + " · " + money(treasuryCut(jv)) +
			" GNOT to the treasury (5%) · the rest by contribution.\n\n")
	}
	b.WriteString("<gno-form exec=\"Settle\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_The pot is still here. Anyone may settle, once._\n\n")
	b.WriteString(noSend())
	return b.String()
}

// tickPanel is the clock nudge, shown whenever a deadline has passed.
func tickPanel(jv JobView) string {
	if jv.Phase == 0 || jv.Phase >= 3 || jv.Deadline > jv.Height {
		return ""
	}
	var b strings.Builder
	b.WriteString("### The clock stopped\n\n")
	b.WriteString("<gno-form exec=\"Tick\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString("</gno-form>\n\n")
	b.WriteString("_Permissionless. Carries the job to its next phase and pays nothing._\n\n")
	b.WriteString(noSend())
	return b.String()
}

// payoutShares mirrors Settle exactly — same pool, same order of operations,
// same remainder rule — because a preview that disagrees with the chain is a
// lie on a page whose whole purpose is trust. The pool is the POT on both
// outcomes; a bust reserves 60% for the snitch, an escape a scaled 5% for the
// treasury. Returns all-zero when the realm would pay nothing.
func payoutShares(jv JobView) []int64 {
	shares := make([]int64, len(jv.Seats))
	if len(shares) == 0 || jv.Pot <= 0 {
		return shares
	}
	if jv.Alarm >= alarmTotal {
		share := jv.Pot * TraitorBustShare / 100
		if int(jv.Traitor) >= 0 && int(jv.Traitor) < len(shares) {
			shares[int(jv.Traitor)] = share
			splitShares(jv, jv.Pot-share, shares)
		} else {
			splitShares(jv, jv.Pot, shares)
		}
		return shares
	}
	splitShares(jv, jv.Pot-treasuryCut(jv), shares)
	return shares
}

// treasuryCut is the escape cut exactly as Settle computes it: Secured scaled
// against the best possible secure, so 5% of the pot is 5% of the pot.
func treasuryCut(jv JobView) int64 {
	if jv.Pot <= 0 {
		return 0
	}
	cut := jv.Pot * jv.Secured * TreasuryBps / (10000 * MaxSecured)
	if cut > jv.Pot {
		return jv.Pot
	}
	return cut
}

// splitShares is splitByContribution over a view: contribution-weighted, the
// remainder to the top contributor, an even split when nobody contributed.
func splitShares(jv JobView, amount int64, shares []int64) {
	n := len(shares)
	if amount <= 0 || n == 0 {
		return
	}
	var total int64
	top := 0
	for i := 0; i < n; i++ {
		c := jv.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		total += c
		if c > jv.Seats[top].Contribution {
			top = i
		}
	}
	if total == 0 {
		each := amount / int64(n)
		for i := 0; i < n; i++ {
			shares[i] += each
		}
		shares[0] += amount - each*int64(n)
		return
	}
	var given int64
	for i := 0; i < n; i++ {
		c := jv.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		part := amount * c / total
		shares[i] += part
		given += part
	}
	if rest := amount - given; rest > 0 {
		shares[top] += rest
	}
}

// ----- commit -----

func renderCommitChoose(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(pageHead("Commit your pick", jobTitle(jv)+" · round "+
		strconv.FormatInt(int64(jv.Round), 10), "The job", jobLink(jv.ID)))
	if jv.Phase != 1 {
		b.WriteString(notice("WARNING", "Not committing any more", "This job is "+phaseName(jv.Phase)+"."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	b.WriteString("Pick one. The next page hashes it and hands you the exact value to sign — " +
		"the hash is public, the pick is not. You can change nothing after signing.\n\n")
	for _, a := range []uint8{1, 2, 3, 4} {
		b.WriteString("### " + actionGlyph(a) + " " + actionName(a) + "\n" + actionBlurb(a) + "\n\n")
		b.WriteString(button("Take "+actionName(a), seatLink(jv, you, "commit/"+strconv.Itoa(int(a))), "outline") + "\n\n")
	}
	b.WriteString(notice("NOTE", "Alarm is at "+strconv.FormatInt(jv.Alarm, 10)+"/3",
		"Carry secures loot against a bust; Watch holds the door. If you are the snitch you want alarm, not a clean cellar."))
	b.WriteString(nav("The job", jobLink(jv.ID), "Rules", self("rules")))
	return b.String()
}

func renderCommitHash(jv JobView, you string, action uint8) string {
	if action < 1 || action > 4 {
		action = 1
	}
	var b strings.Builder
	b.WriteString(pageHead("Sign this hash", jobTitle(jv)+" · "+actionCell(action), "The job", jobLink(jv.ID)))
	if jv.Phase != 1 {
		b.WriteString(notice("WARNING", "Too late for a commit", "This job is "+phaseName(jv.Phase)+"."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	if you == "" {
		b.WriteString(notice("WARNING", "No address in the URL",
			"The hash is bound to your wallet. Open your own seat view first: "+
				md("job "+strconv.FormatInt(jv.ID, 10), jobLink(jv.ID))+" and use the address link there."))
	}
	salt := CommitSalt(jv.ID, jv.Round, you)
	hash := CommitHash(jv.ID, action, salt, you)

	b.WriteString("You chose " + actionCell(action) + ". " + actionBlurb(action) + "\n\n")
	b.WriteString("**Hash to sign**\n\n" + code(hash) + "\n\n")
	b.WriteString("**Salt, keep it**\n\n" + code(salt) + "\n\n")
	b.WriteString(notice("CAUTION", "Without the salt your pick dies",
		"The realm checks `sha256(action|salt|you|job|round)` on reveal. Paste this salt back at the "+
			"reveal step or the pick counts as "+actionCell(4)+" and earns nothing."))

	b.WriteString("<gno-form exec=\"Commit\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	b.WriteString(readonlyField("hash", "Hash (built from your pick)", hash))
	b.WriteString("</gno-form>\n\n")
	b.WriteString(noSend())
	b.WriteString("_Signing posts only the hash. Your pick stays unreadable until the reveal._\n\n")

	b.WriteString("### After signing\n\n")
	b.WriteString(md("Back to the job", jobLink(jv.ID)) + " · " +
		md("go straight to the reveal form", seatLink(jv, you, "reveal")) +
		" (it works once this round's commits close — " + blocksLeft(jv) + ")\n")
	return b.String()
}

// ----- reveal -----

func renderReveal(jv JobView, you string) string {
	var b strings.Builder
	b.WriteString(pageHead("Reveal your pick", jobTitle(jv)+" · round "+
		strconv.FormatInt(int64(jv.Round), 10), "The job", jobLink(jv.ID)))
	if jv.Phase != 2 {
		b.WriteString(notice("WARNING", "Reveal is closed", "This job is "+phaseName(jv.Phase)+"."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	if jv.Deadline <= jv.Height {
		b.WriteString(notice("CAUTION", "Deadline passed",
			"Reveal is rejected now (`e410`). "+md("Tick the job", jobLink(jv.ID))+
				" — unrevealed picks become "+actionCell(4)+" with no contribution."))
		return b.String() + nav("The job", jobLink(jv.ID))
	}
	b.WriteString(blocksLeft(jv) + ". The realm recomputes the hash from what you send and rejects a " +
		"mismatch, so send exactly what you committed.\n\n")

	b.WriteString("<gno-form exec=\"Reveal\">\n")
	b.WriteString(readonlyField("id", "Job", strconv.FormatInt(jv.ID, 10)))
	for _, a := range []uint8{1, 2, 3, 4} {
		b.WriteString(selectOpt("action", strconv.Itoa(int(a)), actionGlyph(a)+" "+actionName(a), false))
	}
	b.WriteString(selectSalt(jv, you))
	b.WriteString("</gno-form>\n\n")

	b.WriteString(noSend())
	b.WriteString(notice("NOTE", "Salt prefilled but editable",
		"It is derived from your seat and this round. If you committed from another device, "+
			"paste the salt the commit page gave you instead."))
	b.WriteString(nav("The job", jobLink(jv.ID), "Rules", self("rules")))
	return b.String()
}

// ----- small form fields -----

func readonlyField(name, description, value string) string {
	return `<gno-input name="` + name + `" description="` + attr(description) +
		`" value="` + attr(value) + `" readonly="true" />` + "\n"
}

func selectOpt(name, value, label string, selected bool) string {
	s := `<gno-select name="` + name + `" value="` + attr(value) + `"`
	if label != "" {
		s += ` description="` + attr(label) + `"`
	}
	if selected {
		s += ` selected="true"`
	}
	return s + " />\n"
}

// selectSalt prefills the salt; a player who committed elsewhere overwrites it.
func selectSalt(jv JobView, you string) string {
	return `<gno-input name="salt" description="Salt from your commit page" value="` +
		attr(CommitSalt(jv.ID, jv.Round, you)) + `" required="true" />` + "\n"
}

package cutpurse

// render_jobs.gno — the board. Every open and live job, one row each, and the
// filters as paths so a shared link keeps its filter.

import (
	"strconv"
	"strings"
)

// boardJobs collects rows for a filter: 0 open, 1 committing, 2 revealing,
// 3 escaped, 4 busted, anything else every live phase.
func boardJobs(kind int64) []JobView {
	switch kind {
	case 0:
		return jobList(0, 40)
	case 1:
		return jobList(1, 40)
	case 2:
		return jobList(2, 40)
	case 3:
		return jobList(3, 32)
	case 4:
		return jobList(4, 32)
	}
	rows := jobList(0, 20)
	rows = append(rows, jobList(1, 20)...)
	return append(rows, jobList(2, 20)...)
}

func filterName(kind int64) string {
	switch kind {
	case 0:
		return "open"
	case 1:
		return "committing"
	case 2:
		return "revealing"
	case 3:
		return "escaped"
	case 4:
		return "busted"
	}
	return "live"
}

// jobTable is one row per job: enough to judge a fee in one glance, nothing
// that belongs on the job's own page.
func jobTable(rows []JobView) string {
	var b strings.Builder
	b.WriteString("| Job | State | Seats | Pot | Fee | Clock | |\n")
	b.WriteString("|---|---|---:|---:|---:|---|---|\n")
	for _, jv := range rows {
		b.WriteString("| " + jobLinkCell(jv) + " | " + phaseBadge(jv.Phase) +
			" | " + seatStrip(int64(jv.NSeats)) +
			" | " + money(jv.Pot) + " | " + money(jv.Fee) +
			" | " + clockCell(jv) +
			" | " + md(icon("arrow-right", "Open job"), jobLink(jv.ID)) + " |\n")
	}
	return b.String()
}

// jobLinkCell is a job's name as a link; jobTitle already escapes its pipes.
func jobLinkCell(jv JobView) string {
	return md(icon("door", "")+" "+jobTitle(jv), jobLink(jv.ID))
}

// clockCell is a job's remaining time in a table cell.
func clockCell(jv JobView) string {
	switch jv.Phase {
	case 3, 4:
		return "settled"
	}
	if jv.Deadline <= jv.Height {
		return "**passed**"
	}
	return strconv.FormatInt(jv.Deadline-jv.Height, 10) + " blk"
}

func renderJobs(kind int64) string {
	var b strings.Builder
	b.WriteString(pageHead("The board", "", "Home", hub))

	if kind > 4 {
		var links []string
		for _, k := range []int64{0, 1, 2, 3, 4} {
			links = append(links, md(filterName(k), self("jobs/"+strconv.FormatInt(k, 10))))
		}
		b.WriteString("Filter: **live** (showing every live phase) · " + strings.Join(links, " · ") + "\n\n")
	} else {
		var links []string
		for _, k := range []int64{0, 1, 2, 3, 4} {
			label := filterName(k)
			if k == kind {
				links = append(links, "**"+label+"**")
				continue
			}
			links = append(links, md(label, self("jobs/"+strconv.FormatInt(k, 10))))
		}
		b.WriteString("Filter: " + strings.Join(links, " · ") + " · " + md("live", self("jobs")) + "\n\n")
	}

	rows := boardJobs(kind)
	if len(rows) == 0 {
		b.WriteString(emptyBoard(kind))
	} else {
		b.WriteString(jobTable(rows) + "\n")
		b.WriteString(notice("TIP", "Fees are set by each creator",
			"A low fee is a cheap seat, not a weak crew. Check the pot before you judge a job."))
	}

	b.WriteString(button("Start a job", self(""), "outline") + "\n\n")
	b.WriteString(nav("Home", self(""), "How it works", self("rules")))
	return b.String()
}

func emptyBoard(kind int64) string {
	switch kind {
	case 3:
		return notice("NOTE", "Nobody has escaped yet", "Settled jobs land here forever. "+
			"When one does, its payouts are public.") + "\n"
	case 4:
		return notice("NOTE", "Nobody has been busted yet", "The first job to hit an alarm of 3 lands here.")
	}
	if kind == 0 {
		return notice("NOTE", "No job is open. Be the first through the door.",
			"Start one, then send the link to a second wallet. Two seats are enough to run a round.")
	}
	return notice("NOTE", "No job is "+filterName(kind)+" right now", "Try "+md("every live job", self("jobs"))+".")
}

package cutpurse

// render_ledger.gno — the permanent record, and the network totals.
// The ledger is the game's memory: it is why a snitch is worth naming.

import (
	"strconv"
	"strings"
)

const ledgerPageSize = 8

func renderLedger(page int64) string {
	if page < 1 {
		page = 1
	}
	var b strings.Builder
	b.WriteString(pageHead("The ledger",
		"Every settled job, kept. Fees, splits and snitches, readable by anyone.", "Home", hub))

	rows := ledgerPage(int(page-1), ledgerPageSize)
	if len(rows) == 0 {
		if page > 1 {
			b.WriteString(notice("NOTE", "Past the last page",
				"There is nothing archived out here. "+md("Back to page 1", self("ledger/1"))+"."))
		} else {
			b.WriteString(notice("NOTE", "Nothing archived. The first job to settle lands here.",
				md("Open a job", self(""))+" and give it three rounds."))
		}
		b.WriteString(nav("Home", self(""), "The board", self("jobs")))
		return b.String()
	}

	b.WriteString(resultTable(rows) + "\n")
	if page > 1 {
		b.WriteString(md(icon("arrow-left", "")+" newer", self("ledger/"+strconv.FormatInt(page-1, 10))) + " · ")
	}
	if ledgerPageSize*page < LedgerLen() {
		b.WriteString(md("older "+icon("arrow-right", ""), self("ledger/"+strconv.FormatInt(page+1, 10))))
	}
	b.WriteString("\n\nPage " + strconv.FormatInt(page, 10) + ". The ledger keeps the last " +
		strconv.Itoa(LedgerMax) + " results; older ones fall off the end.\n\n")

	b.WriteString(notice("NOTE", "Loot, not money",
		"A bust destroys the loot, but never the pot: the pot is always paid — 60% to the snitch on a bust. "+
			"Secured loot only scales the 5% house cut, it never gates a payout."))
	b.WriteString(nav("Home", self(""), "Totals", self("stats")))
	return b.String()
}

// resultTable is the archive, one row per job.
func resultTable(rows []Result) string {
	var b strings.Builder
	// No payout column: it is the widest string on the page and it grows with
	// every row. The receipt lives on the job itself.
	b.WriteString("| Job | Name | Outcome | Loot | Snitch | Block |\n")
	b.WriteString("|---|---|---|---:|---|---:|\n")
	for _, r := range rows {
		b.WriteString("| " + md(strconv.FormatInt(r.JobID, 10), jobLink(r.JobID)) + " | " +
			pipe(resultName(r)) + " | " + outcomeCell(r) + " | " +
			strconv.FormatInt(r.Loot, 10) + " | " + snitchCell(r) + " | " +
			strconv.FormatInt(r.At, 10) + " |\n")
	}
	return b.String() + "\n"
}

func resultName(r Result) string {
	if strings.TrimSpace(r.Name) == "" {
		return "Job " + strconv.FormatInt(r.JobID, 10)
	}
	return r.Name
}

func outcomeCell(r Result) string {
	if r.Busted {
		return icon("alarm", "busted") + " busted"
	}
	return icon("check-circle", "escaped") + " escaped"
}

// snitchCell names the snitch seat's wallet. who() already answers "—" for an
// unusable address, so the zero address is the only case worth a guard here.
func snitchCell(r Result) string {
	s := r.Traitor.String()
	if len(s) < 20 {
		return "—"
	}
	return who(s)
}

// secured is what a bust did not destroy. The archive keeps raised loot, so
// a busted row shows nothing secure.
func secured(r Result) int64 {
	if r.Busted {
		return 0
	}
	return r.Loot
}

// ----- stats -----

func renderStats() string {
	var b strings.Builder
	b.WriteString(pageHead("Totals", "What the realm has run, in aggregate.", "Home", hub))
	b.WriteString(notice("NOTE", "Nobody's numbers are graded here",
		"This page is the cellar's own tally. Per-wallet records are on their profiles."))

	open := int64(len(jobList(0, 40)))
	var escaped, busted, loot int64
	for p := 0; p <= currentLedgerPages(); p++ {
		for _, r := range ledgerPage(p, ledgerPageSize) {
			loot += r.Loot
			if r.Busted {
				busted++
			} else {
				escaped++
			}
		}
	}
	settled := escaped + busted

	b.WriteString(cards(
		"**Jobs opened**\n\n"+strconv.FormatInt(JobCount(), 10),
		"**Open now**\n\n"+strconv.FormatInt(open, 10),
		"**Settled**\n\n"+strconv.FormatInt(settled, 10),
		"**Loot raised**\n\n"+money(loot)+" GNOT",
	))
	b.WriteString("\n")

	if settled > 0 {
		bar := busted * 10 / settled
		b.WriteString("**Treasury** " + coins(Treasury()) + "\n\n")
		b.WriteString("**Busted** " + meter(bar, 10) + " " +
			strconv.FormatInt(busted*100/settled, 10) + "% of " + plural(settled, "settled job") + "\n\n")
		b.WriteString("### The snitch has been named\n\n")
		b.WriteString(plural(busted, "bust") + " out of " + plural(settled, "settled job") +
			". A bust pays the snitch 60% of the pot, so a snitch who is never caught is the " +
			"best-paid seat in the game.\n\n")
	} else {
		b.WriteString(notice("NOTE", "No job has settled yet",
			"These totals fill in as jobs finish. "+md("Open the first", self(""))+"."))
	}

	b.WriteString(button("The ledger", self("ledger"), "outline") + " " +
		button("The board", self("jobs"), "outline") + "\n\n")
	b.WriteString(nav("Home", self(""), "Rules", self("rules")))
	return b.String()
}

// currentLedgerPages is the last page index (0-based).
func currentLedgerPages() int {
	if LedgerLen() == 0 {
		return 0
	}
	return int((LedgerLen() - 1) / ledgerPageSize)
}

package cutpurse

// render_profile.gno — one wallet's record. A record is the only reputation
// here, so it is stated plainly and never graded with a badge.

import (
	"strconv"
	"strings"
)

func renderProfile(addr string) string {
	var b strings.Builder
	b.WriteString(pageHead("A wallet", "", "The ledger", self("ledger")))
	if !address(addr).IsValid() {
		b.WriteString(notice("WARNING", "Not an address", "`"+text(addr)+"` is not a gno address."))
		return b.String() + nav("The ledger", self("ledger"), "Home", self(""))
	}

	jobs, escapes, busts, loot := StatsOf(addr)
	b.WriteString("## " + code(addr) + "\n\n")
	b.WriteString(cards(
		"**Jobs**\n\n"+strconv.FormatInt(jobs, 10),
		"**Escaped**\n\n"+strconv.FormatInt(escapes, 10),
		"**Busted**\n\n"+strconv.FormatInt(busts, 10),
		"**Secured**\n\n"+money(loot)+" GNOT",
	))
	b.WriteString("\n")

	if jobs == 0 {
		b.WriteString(notice("NOTE", "Nothing on this wallet yet",
			"A job takes five minutes and the ledger keeps it forever. "+
				md("Take a seat", self("jobs"))+" and this page fills itself in."))
		b.WriteString(nav("The board", self("jobs"), "Rules", self("rules")))
		return b.String()
	}

	b.WriteString(notice("NOTE", "Read the seats, not the percentage",
		"Escapes at a high fee beat many cheap jobs. Contribution is what each split was weighted by."))

	b.WriteString("## Jobs settled\n\n")
	rows := entriesOf(addr)
	if len(rows) == 0 {
		b.WriteString("_This wallet is in a live job and has not settled one yet._\n\n")
	} else {
		b.WriteString(resultTable(rows))
		if len(rows) == profileLimit {
			b.WriteString("_Showing the most recent " + strconv.Itoa(profileLimit) +
				". Earlier jobs are in " + md("the ledger", self("ledger")) + "._\n\n")
		}
	}

	b.WriteString(button("Find a job", self("jobs"), "") + "\n\n")
	b.WriteString(nav("The ledger", self("ledger"), "Home", self("")))
	return b.String()
}

// profileLimit caps a profile's list: the archive can hold LedgerMax results and
// rendering every one of them costs more than the page is worth. The ledger
// itself is where the full record lives.
const profileLimit = 6

// maxProfileScanPages bounds the archive walk. Copying archived results out of
// the ring is the single most expensive thing on this page (~600k gas per
// entry), so the walk is capped and the ledger keeps the long tail.
const maxProfileScanPages = 4

// entriesOf scans the newest pages for one wallet and stops at profileLimit.
func entriesOf(addr string) []Result {
	out := make([]Result, 0, profileLimit)
	who := address(addr)
	pages := (int(LedgerLen()) + MaxListLimit - 1) / MaxListLimit
	if pages > maxProfileScanPages {
		pages = maxProfileScanPages
	}
	for p := 0; p < pages; p++ {
		for _, r := range ledgerPage(p, MaxListLimit) {
			if r.Traitor == who || strings.Contains(r.Payouts, addr) {
				out = append(out, r)
				if len(out) == profileLimit {
					return out
				}
			}
		}
	}
	return out
}

package cutpurse

import "strconv"

// FROZEN CONTRACT (SPEC §9). The designer consumes these shapes and may not
// touch globals or maps. Widening a struct is builder-only and needs a SPEC
// amendment.

type JobView struct {
	ID        int64
	Name      string
	Creator   address
	Fee       int64
	Pot       int64
	Loot      int64
	Secured   int64
	Alarm     int64
	Phase     uint8
	Round     uint8
	Deadline  int64
	Height    int64
	NSeats    uint8
	Revealed  bool
	Traitor   int8
	OpenedAt  int64
	SettledAt int64
	Settled   bool
	Seats     []SeatView
}

type SeatView struct {
	Addr         address
	Committed    bool
	Revealed     bool
	Auto         bool
	Action       uint8
	Contribution int64
}

// jobView renders one job; Traitor is -1 until the snitch is public.
func jobView(id int64) (JobView, bool) {
	j, ok := jobs[id]
	if !ok {
		return JobView{}, false
	}

	v := JobView{
		ID:        j.ID,
		Name:      j.Name,
		Creator:   j.Creator,
		Fee:       j.Fee,
		Pot:       j.Pot,
		Loot:      j.Loot,
		Secured:   j.Secured,
		Alarm:     j.Alarm,
		Phase:     uint8(j.Phase),
		Round:     j.Round,
		Deadline:  j.Deadline,
		Height:    mustHeight(),
		NSeats:    j.NSeats,
		Revealed:  j.Revealed,
		Traitor:   -1,
		OpenedAt:  j.OpenedAt,
		SettledAt: j.SettledAt,
		Settled:   j.SettledAt != 0,
		Seats:     make([]SeatView, 0, int(j.NSeats)),
	}
	if j.Revealed {
		v.Traitor = j.Traitor
	}
	for i := 0; i < int(j.NSeats); i++ {
		s := j.Seats[i]
		v.Seats = append(v.Seats, SeatView{
			Addr:         s.Addr,
			Committed:    s.Committed,
			Revealed:     s.Action != ActNone,
			Auto:         s.Auto,
			Action:       uint8(s.Action),
			Contribution: s.Contribution,
		})
	}
	return v, true
}

// jobList returns up to limit views, newest first. phase > PhaseBusted means
// "any phase".
func jobList(phase uint8, limit int) []JobView {
	if limit < 1 {
		limit = 1
	}
	if limit > MaxListLimit {
		limit = MaxListLimit
	}

	out := make([]JobView, 0, limit)
	id := nextID - 1
	for scanned := 0; id >= 0 && len(out) < limit && scanned < LedgerMax; scanned++ {
		if v, ok := jobView(id); ok {
			if phase > uint8(PhaseBusted) || v.Phase == phase {
				out = append(out, v)
			}
		}
		id--
	}
	return out
}

// ledgerPage returns one ledger page, newest entry first.
func ledgerPage(n, size int) []Result {
	if size < 1 {
		size = 10
	}
	if size > MaxListLimit {
		size = MaxListLimit
	}
	if n < 0 {
		n = 0
	}

	out := make([]Result, 0, size)
	start := n * size
	for k := start; k < start+size && k < ledgerLen; k++ {
		idx := (ledgerHead - 1 - k + LedgerMax*2) % LedgerMax
		if r := ledger[idx]; r != nil {
			out = append(out, *r)
		}
	}
	return out
}

func statsOf(a address) (jobs, escapes, busts, loot int64) {
	s, ok := stats[a.String()]
	if !ok {
		return 0, 0, 0, 0
	}
	return s.Jobs, s.Escapes, s.Busts, s.Loot
}

// JobCount is the number of jobs ever created.
func JobCount() int64 { return nextID }

// JobViewOf / JobListOf / LedgerPageOf / StatsOfAddress are exported doors on
// the unexported contract helpers so out-of-package tests can assert on state
// without touching globals.
func JobViewOf(id int64) (JobView, bool) { return jobView(id) }

func JobListOf(phase uint8, limit int) []JobView { return jobList(phase, limit) }

func LedgerPageOf(n, size int) []Result { return ledgerPage(n, size) }

func StatsOfAddress(a address) (jobs, escapes, busts, loot int64) { return statsOf(a) }

// StatsOf is statsOf keyed by bech32 string (path input, no parser needed).
func StatsOf(a string) (jobs, escapes, busts, loot int64) {
	s, ok := stats[a]
	if !ok {
		return 0, 0, 0, 0
	}
	return s.Jobs, s.Escapes, s.Busts, s.Loot
}

// Name returns the stored (already sanitized) job name, or "".
func Name(id int64) string {
	if j, ok := jobs[id]; ok {
		return j.Name
	}
	return ""
}

// Treasury is the accrued 5% house cut, in ugnot.
func Treasury() int64 { return treasury }

// treasuryTotal is the designer's spelling for the same number.
func TreasuryTotal() int64 { return treasury }

// commitSalt is a round-stable, per-seat nonce the commit page shows. It is
// derived from OpenedAt (immutable for the life of the job) and Round, so the
// same value comes back at reveal time even though Deadline moves.
func saltFor(id int64, round uint8, who string) string {
	openedAt := int64(0)
	if j, ok := jobs[id]; ok {
		openedAt = j.OpenedAt
	}
	return sha256Hex("cutpurse|" +
		strconv.FormatInt(id, 10) + "|" +
		strconv.FormatUint(uint64(round), 10) + "|" +
		strconv.FormatInt(openedAt, 10) + "|" +
		who)
}

// CommitSalt is the exported door for out-of-package callers.
func CommitSalt(id int64, round uint8, who string) string { return saltFor(id, round, who) }

// LedgerLen is the number of archived results.
func LedgerLen() int64 { return int64(ledgerLen) }

// Archived returns the permanent ledger entry for a settled job.
func Archived(id int64) (Result, bool) {
	for k := 0; k < ledgerLen; k++ {
		idx := (ledgerHead - 1 - k + LedgerMax*2) % LedgerMax
		if r := ledger[idx]; r != nil && r.JobID == id {
			return *r, true
		}
	}
	return Result{}, false
}

package cutpurse

import (
	"chain"
	"chain/banker"
	"sort"
	"strconv"
	"strings"
)

// Tick is the only transition driver. Permissionless, any phase, no-op while
// the phase deadline is still open (§5, §6).
func Tick(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	j := mustJob(id)

	if j.Phase >= PhaseSettled {
		return
	}

	height := mustHeight()
	if height <= j.Deadline {
		return
	}

	switch j.Phase {
	case PhaseOpen:
		if j.NSeats >= 2 {
			j.Phase = PhaseCommit
			j.Round = 1
			j.Deadline = height + CommitBlocks
			return
		}
		// never filled: disband, everyone is refunded by Settle
		j.Phase = PhaseSettled
		j.Deadline = height
	case PhaseCommit:
		closeCommitRound(j)
	case PhaseReveal:
		closeRevealRound(j, true)
	}
}

// sealSeed is the deterministic seed from §6: it is a pure function of public
// data, so anyone can recompute it after the round closes.
func sealSeed(j *Job) string {
	hashes := make([]string, 0, Seats)
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Committed && j.Seats[i].CommitHash != "" {
			hashes = append(hashes, j.Seats[i].CommitHash)
		}
	}
	sort.Strings(hashes)

	return sha256Hex(j.Seed + "|" +
		strconv.FormatInt(j.ID, 10) + "|" +
		strconv.FormatInt(mustHeight(), 10) + "|" +
		strings.Join(hashes, ""))
}

// closeCommitRound ends the commit phase: silent seats fall back to Watch, the
// seed is sealed on round 1 and the snitch seat is drawn from it.
func closeCommitRound(j *Job) {
	for i := 0; i < int(j.NSeats); i++ {
		if !j.Seats[i].Committed {
			j.Seats[i].Action = ActWatch
			j.Seats[i].Auto = true
		}
	}

	if j.Round == 1 && j.Seed == "" {
		j.Seed = sealSeed(j)
		if j.NSeats > 0 {
			j.Traitor = int8(int64(j.Seed[0]) % int64(j.NSeats))
		}
	}

	j.Phase = PhaseReveal
	j.Deadline = mustHeight() + RevealBlocks
}

// closeRevealRound ends the reveal phase: silent seats fall back to Watch and,
// when the deadline forced the close, lose one reputation point.
func closeRevealRound(j *Job, penalize bool) {
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Action == ActNone {
			j.Seats[i].Action = ActWatch
			j.Seats[i].Auto = true
			if penalize {
				repDown(j.Seats[i].Addr)
			}
		}
	}
	resolveRound(j)
}

// resolveRound applies §6 exactly: alarm, secured, loot, contributions, then
// either terminal phase or the next round.
func resolveRound(j *Job) {
	n := int(j.NSeats)
	var np, nc, ns, nw int64

	for i := 0; i < n; i++ {
		switch j.Seats[i].Action {
		case ActPick:
			np++
		case ActCarry:
			nc++
		case ActScout:
			ns++
		case ActWatch:
			nw++
		}
	}

	j.Alarm += maxInt64(0, np-nw)
	j.Secured += 2 * nc
	loot := 3*np + 2*nc + 2*ns + nw
	if np == 0 && nw > 0 {
		loot += nw
	}
	j.Loot += loot

	for i := 0; i < n; i++ {
		switch j.Seats[i].Action {
		case ActPick, ActCarry:
			j.Seats[i].Contribution += 3
		case ActScout:
			j.Seats[i].Contribution += 2
		case ActWatch:
			j.Seats[i].Contribution += 1 + np
		}
	}

	if j.Alarm >= BustAlarm {
		j.Phase = PhaseBusted
		return
	}
	if j.Round >= Rounds {
		j.Phase = PhaseSettled
		return
	}

	j.Round++
	j.Phase = PhaseCommit
	j.Deadline = mustHeight() + CommitBlocks
	for i := 0; i < n; i++ {
		j.Seats[i].Committed = false
		j.Seats[i].CommitHash = ""
		j.Seats[i].Action = ActNone
		j.Seats[i].Auto = false
	}
}

// splitByContribution divides amount by accumulated contribution; the rounding
// dust goes to the top contributor, and an all-zero table splits equally.
func splitByContribution(j *Job, amount int64, pay *[Seats]int64) {
	n := int(j.NSeats)
	if amount <= 0 || n == 0 {
		return
	}

	var total int64
	top := 0
	for i := 0; i < n; i++ {
		c := j.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		total += c
		if c > j.Seats[top].Contribution {
			top = i
		}
	}

	if total == 0 {
		each := amount / int64(n)
		for i := 0; i < n; i++ {
			pay[i] += each
		}
		pay[0] += amount - each*int64(n)
		return
	}

	var given int64
	for i := 0; i < n; i++ {
		c := j.Seats[i].Contribution
		if c < 0 {
			c = 0
		}
		part := amount * c / total
		pay[i] += part
		given += part
	}
	if rest := amount - given; rest > 0 {
		pay[top] += rest
	}
}

func archiveResult(j *Job, pay *[Seats]int64) {
	r := &Result{
		JobID:  j.ID,
		Name:   j.Name,
		Busted: j.Phase == PhaseBusted,
		Loot:   j.Loot,
		At:     mustHeight(),
	}
	if j.Traitor >= 0 && int(j.Traitor) < int(j.NSeats) {
		r.Traitor = j.Seats[j.Traitor].Addr
	}

	parts := make([]string, 0, Seats)
	for i := 0; i < int(j.NSeats); i++ {
		if pay[i] > 0 {
			parts = append(parts, j.Seats[i].Addr.String()+":"+strconv.FormatInt(pay[i], 10))
		}
	}
	r.Payouts = strings.Join(parts, ",")

	ledger[ledgerHead] = r
	ledgerHead = (ledgerHead + 1) % LedgerMax
	if ledgerLen < LedgerMax {
		ledgerLen++
	}
}

// Settle pushes the single payout, archives the result and frees the seats.
// All state is written before any coin leaves the realm (§10 R4).
func Settle(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	j := mustJob(id)

	if j.SettledAt != 0 {
		panic(ErrAlreadySettled)
	}
	if j.Phase < PhaseSettled {
		panic(ErrNotReady)
	}

	n := int(j.NSeats)
	busted := j.Phase == PhaseBusted
	pay := [Seats]int64{}

	if n > 0 && j.Pot > 0 {
		if busted {
			share := j.Pot * TraitorBustShare / 100
			if j.Traitor >= 0 && int(j.Traitor) < n {
				pay[j.Traitor] = share
				splitByContribution(j, j.Pot-share, &pay)
			} else {
				splitByContribution(j, j.Pot, &pay)
			}
			j.Revealed = true
		} else {
			// §6 says cut = Secured*Bps/10000, but Secured counts 2 per carry
			// while the pot is in ugnot — the raw product rounds to zero at
			// MinFee. Scale Secured against the best possible secure
			// (2*Seats*Rounds) so the 5% is 5% of the pot, capped there.
			cut := j.Pot * j.Secured * TreasuryBps / (10000 * MaxSecured)
			if cut > j.Pot {
				cut = j.Pot
			}
			treasury += cut
			splitByContribution(j, j.Pot-cut, &pay)
		}
	}

	// --- state before coins ---
	height := mustHeight()
	j.SettledAt = height
	for i := 0; i < n; i++ {
		s := statFor(j.Seats[i].Addr)
		s.Jobs++
		if busted {
			s.Busts++
		} else {
			s.Escapes++
		}
		s.Loot += pay[i]
		if active[j.Seats[i].Addr] == j.ID {
			delete(active, j.Seats[i].Addr)
		}
	}
	archiveResult(j, &pay)
	if liveCount > 0 {
		liveCount--
	}
	purgeOld()

	// --- then coins ---
	realmAddr := cur.Address()
	bank := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	for i := 0; i < n; i++ {
		if pay[i] > 0 {
			bank.SendCoins(realmAddr, j.Seats[i].Addr, chain.NewCoins(chain.NewCoin(Denom, pay[i])))
		}
	}
}

package cutpurse

// ui.gno — the design system and the router. Everything a page may say about
// shape, money, danger or another player goes through this file. Pages call
// these and never build markup themselves.
//
// Palette, voice and copy deck: docs/brand.md. The rules that matter here:
// text from the chain is hostile, so it enters through text/cell/code; every
// self-link is absolute and built from hub; alarm is ▰▰▱ and seats are ▰▰▱▱.

import (
	"html"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// hub is this realm's absolute base. Set it to the deploy address before
// deploy (see _agents/STATE.md). Every link and button is hub + ":" + path.
const hub = "/r/g1e4jarvm80rz800tmw8nvx43j2fq2z9atkya5na/cutpurse/v1"

const (
	seatTotal  = 4 // seats per job, drawn as a strip of 4 segments
	alarmTotal = 3 // alarm segments before a job busts
)

const (
	segFull   = "▰"
	segBlank  = "▱"
	segLocked = "▪"
)

// ----- routing -----

// Render is the realm's only entry point besides the actions. It is the
// designer's: builder must not define another one (see STATE.md).
// Paths: "" home · rules · jobs[/<phase>] · job/<id>[/<you>[/commit[/<action>]|/reveal]]
// · j/<id> (alias) · p/<addr> · ledger[/<n>] · stats.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	p := strings.Trim(path, "/")
	parts := strings.Split(p, "/")
	switch parts[0] {
	case "rules":
		return renderRules()
	case "jobs":
		return renderJobs(atoiOr(part(parts, 1), 0))
	case "job", "j":
		return renderJobPath(parts)
	case "p":
		return renderProfile(part(parts, 1))
	case "ledger":
		return renderLedger(atoiOr(part(parts, 1), 1))
	case "stats":
		return renderStats()
	}
	return renderMissing(text(parts[0]))
}

func part(parts []string, i int) string {
	if i < len(parts) {
		return parts[i]
	}
	return ""
}

func atoiOr(s string, fallback int64) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return fallback
	}
	return n
}

// ----- escaping -----

// text is user prose: safe inside a paragraph, heading or link label.
func text(s string) string { return sanitize.InlineText(s) }

// cell is a table cell: text that also survives its own pipes.
func cell(s string) string { return sanitize.TableCell(s) }

// code is a code span holding user text.
func code(s string) string { return sanitize.InlineCode(s) }

// attr escapes a value for a tag attribute.
func attr(s string) string { return html.EscapeString(s) }

// ----- links and controls -----

// self is an absolute self-link. The empty path is the realm root, which
// takes no colon.
func self(path string) string {
	if path == "" {
		return hub
	}
	return hub + ":" + path
}

func md(label, href string) string { return "[" + label + "](" + href + ")" }

func icon(name, label string) string {
	if label == "" {
		return `<gno-icon name="` + name + `" />`
	}
	return `<gno-icon name="` + name + `" label="` + attr(label) + `" />`
}

// button is a styled link. variant: "" (solid), "outline", "caution",
// "warning", "success", or two of them.
func button(label, href, variant string) string {
	s := `<gno-button href="` + attr(href) + `" label="` + attr(label) + `"`
	if variant != "" {
		s += ` variant="` + attr(variant) + `"`
	}
	return s + ` />`
}

// nav is a foot row of label/href pairs. The first pair is the way back and
// carries the arrow; the rest are cross-links.
func nav(pairs ...string) string {
	var b strings.Builder
	for i := 0; i+1 < len(pairs); i += 2 {
		if i > 0 {
			b.WriteString(" · ")
		}
		label := pairs[i]
		if i == 0 {
			label = icon("arrow-left", "Back") + " " + label
		}
		b.WriteString(md(label, pairs[i+1]))
	}
	return b.String() + "\n\n"
}

// ----- structure -----

// frame is a bordered block. Alone in a column it draws as a card. The
// closing tag always gets its own empty line so the last line parses.
func frame(body string) string {
	if !strings.HasSuffix(body, "\n") {
		body += "\n"
	}
	return "<gno-frame>\n" + body + "\n</gno-frame>\n"
}

// cards lays frames out side by side, one column each.
func cards(bodies ...string) string {
	if len(bodies) == 0 {
		return ""
	}
	if len(bodies) == 1 {
		return frame(bodies[0]) + "\n"
	}
	s := "<gno-columns>\n" + frame(bodies[0])
	for _, body := range bodies[1:] {
		s += "\n<gno-columns-sep />\n" + frame(body)
	}
	return s + "</gno-columns>\n\n"
}

// sendFor marks the two forms that must carry coins. A gnoweb form has only
// `path` and `exec`, so the fee comes from the tx send envelope, not a field:
// short envelope is e413, excess is refunded. `$help` prints the command.
func sendFor(ugnot int64, what string) string {
	return notice("CAUTION", "Attach "+money(ugnot)+" GNOT to this call",
		"A form cannot carry coins, so the wallet must: send `"+strconv.FormatInt(ugnot, 10)+
			"ugnot` with the transaction, or the realm rejects it (`e413 fee-too-low`). "+
			what+" Anything over is refunded. "+md("The $help page", self("$help"))+
			" prints the exact command with the send already in it.")
}

// noSend marks forms that must carry nothing. A send on a function that never
// reads the envelope is a hard UnobservedSendError.
func noSend() string { return "_No coins on this call — a send here fails the tx._\n\n" }

func notice(kind, title, body string) string {
	s := "> [!" + kind + "]"
	if title != "" {
		s += " " + title
	}
	if body != "" {
		s += "\n> " + body
	}
	return s + "\n\n"
}

// fold is a collapsed block: closed by default, so it hides what a returning
// player already knows.
func fold(summary, body string) string {
	return "<gno-details summary=\"" + attr(summary) + "\">\n" + body + "\n</gno-details>\n\n"
}

func title(s string) string { return "# " + s + "\n\n" }

// pageHeadBare is a title and one line of state with no cross-links. Pages that
// already carry their own footer nav use this: two nav rows on one page is a
// third more link gas for nothing.
func pageHeadBare(name, line string) string {
	if line == "" {
		return title(name)
	}
	return title(name) + line + "\n\n"
}

// pageHead is the standard opening: title, one line of state, and the way out.
func pageHead(name, line, backLabel, backHref string) string {
	s := title(name)
	if line != "" {
		s += line + "\n\n"
	}
	s += nav(backLabel, backHref, "Rules", self("rules"), "Ledger", self("ledger"))
	return s
}

// ----- money and numbers -----

// money renders ugnot as GNOT with three decimals: 100000 -> "0.100".
// Concatenation beats strings.Builder here by measurement, and this is the
// most-called helper on a page.
func money(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	milli := ugnot / 1000
	s := strconv.FormatInt(milli/1000, 10) + "." + pad(milli%1000, 3)
	if neg {
		return "-" + s
	}
	return s
}

func pad(v int64, width int) string {
	s := strconv.FormatInt(v, 10)
	for len(s) < width {
		s = "0" + s
	}
	return s
}

// coins is money with its glyph, the only form used in prose.
func coins(ugnot int64) string { return "🪙 **" + money(ugnot) + " GNOT**" }

func plural(n int64, one string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.FormatInt(n, 10) + " " + one + "s"
}

// ----- meters -----

// meter draws v filled segments out of total.
func meter(v, total int64) string {
	if v < 0 {
		v = 0
	}
	if v > total {
		v = total
	}
	s := ""
	for i := int64(0); i < total; i++ {
		if i < v {
			s += segFull
		} else {
			s += segBlank
		}
	}
	return s
}

// alarmBars is the alarm bar and its count, always three segments. The bar is
// decoration; the number is the fact, so both are always written.
func alarmBars(alarm int64) string {
	s := meter(alarm, alarmTotal) + " " + strconv.FormatInt(alarm, 10) + "/3"
	if alarm >= alarmTotal {
		return s + " **— the door is closing**"
	}
	return s
}

// alarmMeter is alarmBars with its glyph, for prose.
func alarmMeter(alarm int64) string { return icon("alarm", "") + " " + alarmBars(alarm) }

// seatStrip draws filled seats out of four, empty ones as blanks.
func seatStrip(filled int64) string { return meter(filled, seatTotal) }

// ----- players -----

func short(addr string) string {
	if len(addr) <= 12 {
		return addr
	}
	return addr[:6] + "…" + addr[len(addr)-4:]
}

// who is a player as a link to their profile. An address is bech32 — lowercase
// letters and digits only — so it needs no sanitize pass, only a code span; that
// keeps a seat table inside the render gas budget.
func who(addr string) string {
	if !address(addr).IsValid() {
		return "—"
	}
	return md("`"+short(addr)+"`", self("p/"+addr))
}

// youMark flags the caller's own seat, when the path carried their address.
func youMark(addr, viewer string) string {
	if viewer != "" && addr == viewer {
		return " " + icon("user-male", "you") + " **you**"
	}
	return ""
}

// ----- game vocabulary -----

func phaseName(phase uint8) string {
	switch phase {
	case 1:
		return "committing"
	case 2:
		return "revealing"
	case 3:
		return "escaped"
	case 4:
		return "busted"
	}
	return "open"
}

// phaseBadge is the one-glance state of a job in a list or a heading.
func phaseBadge(phase uint8) string {
	switch phase {
	case 1:
		return icon("lock", "committing") + " committing"
	case 2:
		return icon("eye", "revealing") + " revealing"
	case 3:
		return icon("check-circle", "escaped") + " escaped"
	case 4:
		return icon("alarm", "busted") + " busted"
	}
	return icon("door", "open") + " open"
}

func actionName(a uint8) string {
	switch a {
	case 1:
		return "Scout"
	case 2:
		return "Pick"
	case 3:
		return "Carry"
	case 4:
		return "Watch"
	}
	return "—"
}

func actionIcon(a uint8) string {
	switch a {
	case 1:
		return "search"
	case 2:
		return "unlock"
	case 3:
		return "bag"
	case 4:
		return "eye"
	}
	return "info"
}

func actionGlyph(a uint8) string {
	switch a {
	case 1:
		return "🔍"
	case 2:
		return "🔓"
	case 3:
		return "🎒"
	case 4:
		return "👁"
	}
	return "·"
}

// actionCell is an action with its glyph, for a table.
func actionCell(a uint8) string {
	if a == 0 {
		return "—"
	}
	return actionGlyph(a) + " " + actionName(a)
}

// actionBlurb is why a player would choose it. Contributions are the truth
// behind the flavour, so both are printed.
func actionBlurb(a uint8) string {
	switch a {
	case 1:
		return "Reads the room: **+2** loot, no alarm."
	case 2:
		return "Takes from the shelf: **+3** loot, **+1 alarm**."
	case 3:
		return "Hauls it to the door: **+3 loot that survives a bust**."
	case 4:
		return "Holds the door: **+1** loot, and **−1 alarm**."
	}
	return "Do nothing."
}

// blocksLeft says how long is left before the deadline, in blocks.
func blocksLeft(jv JobView) string {
	left := jv.Deadline - jv.Height
	if left <= 0 {
		return "**deadline passed**"
	}
	return strconv.FormatInt(left, 10) + " blocks left"
}

// jobTitle is a job's name with a fallback. Names are sanitised once at write
// time (cleanName), and sanitize helpers are not idempotent, so it is *not*
// re-run here — only the escape a table cell needs is applied.
func jobTitle(jv JobView) string {
	n := strings.TrimSpace(jv.Name)
	if n == "" {
		return "Job " + strconv.FormatInt(jv.ID, 10)
	}
	return pipe(n)
}

// pipe escapes the only markdown character a stored (already sanitised) name
// can still break a table with.
func pipe(s string) string { return strings.ReplaceAll(s, "|", `\|`) }

// jobLink is the canonical link to a job.
func jobLink(id int64) string { return self("job/" + strconv.FormatInt(id, 10)) }

// ----- surfaces owned by other files -----

// The six page functions live in render_home/rules/jobs/job/profile/ledger.gno.
// Declared here so the router reads as a table of contents.
func renderMissing(what string) string {
	return pageHead("Nothing here", "The path `"+what+"` is not a page.", "Home", hub) +
		notice("WARNING", "No such page", "") +
		"Try " + md("the board", self("jobs")) + ", " + md("the rules", self("rules")) +
		", or " + md("the ledger", self("ledger")) + ".\n"
}

package cutpurse

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// payIn enforces the send envelope of the call: the caller must cover want
// ugnot, anything above want is refunded immediately.
//
// A BankerTypeRealmSend banker can only spend the realm's own address, so fees
// must arrive with the message (tx send coins); banker.IssueCoin is not a
// substitute because realm-issued coins carry a "/<pkgpath>:" denom prefix and
// would not be the native ugnot the game escrows.
func payIn(cur realm, want int64) {
	// cur.Previous() is unreadable when a test drives the mutator with a bare
	// frame ("cannot seek beyond origin caller override"), so the caller-kind
	// guard is derived from the envelope instead: a realm caller attaches
	// nothing, so a zero envelope is a caller error, not a fee shortfall.
	sent := unsafe.OriginSend().AmountOf(Denom)
	if sent == 0 {
		panic(ErrNotUserCall)
	}
	who := here(cur)
	if sent < want {
		panic(ErrFeeTooLow)
	}
	if sent > want {
		banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
			cur.Address(), who, chain.NewCoins(chain.NewCoin(Denom, sent-want)))
	}
}

// mustJob returns the job or panics e404.
func mustJob(id int64) *Job {
	j, ok := jobs[id]
	if !ok {
		panic(ErrNoJob)
	}
	return j
}

func mustHeight() int64 { return runtime.ChainHeight() }

// here is the acting player. It is the message's origin caller, not
// cur.Previous(): a crossed call from another *package* would otherwise act as
// that package's address instead of the signing wallet.
func here(cur realm) address { return unsafe.OriginCaller() }

// clampFee bounds a caller-supplied fee into [MinFee, MaxFee].
func clampFee(fee int64) int64 {
	if fee < MinFee {
		return MinFee
	}
	if fee > MaxFee {
		return MaxFee
	}
	return fee
}

// cleanName sanitizes user text for write and bounds it to MaxNameRunes runes
// so Render is safe for arbitrarily long input (§10 R9).
func cleanName(raw string) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		panic(ErrBadName)
	}
	rs := []rune(sanitize.InlineText(trimmed))
	if len(rs) > MaxNameRunes {
		rs = rs[:MaxNameRunes]
	}
	// a truncated trailing escape would eat the following character
	for len(rs) > 0 && rs[len(rs)-1] == '\\' {
		rs = rs[:len(rs)-1]
	}
	if len(rs) == 0 {
		panic(ErrBadName)
	}
	return string(rs)
}

func validSalt(salt string) bool {
	if len(salt) == 0 || len(salt) > MaxSaltLen {
		return false
	}
	for i := 0; i < len(salt); i++ {
		b := salt[i]
		if b <= 0x20 || b >= 0x7f {
			return false
		}
	}
	return true
}

func isHex64(h string) bool {
	if len(h) != 64 {
		return false
	}
	for i := 0; i < len(h); i++ {
		b := h[i]
		ok := (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
		if !ok {
			return false
		}
	}
	return true
}

func sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// commitHash is the sealed preimage: sha256(action|salt|caller|id|round).
func commitHash(id int64, action uint8, salt, who string, round uint8) string {
	return sha256Hex(
		strconv.FormatUint(uint64(action), 10) + "|" +
			salt + "|" +
			who + "|" +
			strconv.FormatInt(id, 10) + "|" +
			strconv.FormatUint(uint64(round), 10))
}

// CommitHash is the render-facing helper (§7): designer passes the *typed*
// action and salt and shows the resulting string to paste in Commit.
func CommitHash(id int64, action uint8, salt, who string) string {
	rnd := uint8(0)
	if j, ok := jobs[id]; ok {
		rnd = j.Round
	}
	return commitHash(id, action, salt, who, rnd)
}

func maxInt64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func isLive(j *Job) bool { return j.Phase < PhaseSettled }

func seatOf(j *Job, who address) int {
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Addr == who {
			return i
		}
	}
	return -1
}

func countCommitted(j *Job) int {
	n := 0
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Committed {
			n++
		}
	}
	return n
}

func countRevealed(j *Job) int {
	n := 0
	for i := 0; i < int(j.NSeats); i++ {
		if j.Seats[i].Action != ActNone {
			n++
		}
	}
	return n
}

func statFor(who address) *Stats {
	k := who.String()
	s, ok := stats[k]
	if !ok {
		s = &Stats{}
		stats[k] = s
	}
	return s
}

func repDown(who address) {
	s := statFor(who)
	if s.Escapes > 0 {
		s.Escapes--
	}
}

// purgeOld keeps the jobs map bounded: once more than LedgerMax jobs exist,
// settled jobs are dropped oldest-first (the ledger ring stays permanent).
func purgeOld() {
	for i := 0; i < LedgerMax; i++ {
		if len(jobs) <= LedgerMax {
			return
		}
		oldest := int64(0)
		found := false
		for id := range jobs {
			if !isLive(jobs[id]) && jobs[id].SettledAt != 0 && (!found || id < oldest) {
				oldest = id
				found = true
			}
		}
		if !found {
			return
		}
		delete(jobs, oldest)
	}
}

package mimir

import "strings"

const hexDigits = "0123456789abcdef"

// Quote returns s as a JSON string literal.
func Quote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c == '\n':
			b.WriteString(`\n`)
		case c == '\r':
			b.WriteString(`\r`)
		case c == '\t':
			b.WriteString(`\t`)
		case c < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte(hexDigits[c>>4])
			b.WriteByte(hexDigits[c&0xf])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// Escape makes user text safe to place in gnoweb markdown: it cannot open
// links, images, HTML or headings.
func Escape(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\", "[", "\\[", "]", "\\]", "(", "\\(", ")", "\\)",
		"<", "&lt;", ">", "&gt;", "*", "\\*", "_", "\\_", "`", "\\`",
		"#", "\\#", "|", "\\|", "\n", " ", "\r", " ",
	)
	return r.Replace(s)
}

// FormatUSD renders 6-decimal units as a dollar amount with two decimals, rounded down.
func FormatUSD(units int64) string {
	sign := ""
	if units < 0 {
		sign = "-"
		units = -units
	}
	cents := units / 10_000
	frac := cents % 100
	s := sign + itoa(cents/100) + "."
	if frac < 10 {
		s += "0"
	}
	return s + itoa(frac)
}

func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

package mimir

import "math/bits"

// MulDiv returns floor(a*b/d) without overflowing the 128-bit product.
// It panics on negative inputs, a zero divisor or a result above int64.
func MulDiv(a, b, d int64) int64 {
	if a < 0 || b < 0 || d <= 0 {
		panic("mimir: MulDiv needs a, b >= 0 and d > 0")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	if hi >= uint64(d) {
		panic("mimir: MulDiv overflow")
	}
	q, _ := bits.Div64(hi, lo, uint64(d))
	if q > uint64(1<<63-1) {
		panic("mimir: MulDiv overflow")
	}
	return int64(q)
}

// Add returns a+b, panicking on overflow, so a sum of stakes can never wrap.
func Add(a, b int64) int64 {
	c := a + b
	if (b > 0 && c < a) || (b < 0 && c > a) {
		panic("mimir: add overflow")
	}
	return c
}

package mimir

import (
	"chain"
	"strconv"
)

// TimelockSeconds delays ownership, oracle and fee-recipient changes.
const TimelockSeconds = int64(2 * 24 * 60 * 60)

// Roles holds a market realm's roles, pause flag and guarded-launch caps, and
// enforces the same rules the EVM contracts do:
//   - two-step ownership with a timelock;
//   - a timelocked oracle change the owner can revoke at once;
//   - the oracle is never also the owner, the arbiter or the fee recipient;
//   - the audit agent may only dispute, and never holds another role;
//   - a timelocked fee-recipient change;
//   - queued changes are executed by anyone once due.
//
// Every method takes the caller and the block time from the realm, which
// owns the Roles value.
type Roles struct {
	Owner               address
	Arbiter             address
	AuditAgent          address
	Oracle              address
	FeeRecipient        address
	PendingOwner        address
	PendingOwnerEta     int64
	PendingOracle       address
	PendingOracleEta    int64
	PendingFeeRecipient address
	PendingFeeEta       int64
	Paused              bool
	MaxAccountStake     int64
	MaxMarketStake      int64
}

// NewRoles validates the initial roles as the EVM constructors did.
func NewRoles(owner, arbiter, oracle, feeRecipient address) *Roles {
	if !owner.IsValid() || !arbiter.IsValid() || !oracle.IsValid() || !feeRecipient.IsValid() {
		panic("ZeroAddress")
	}
	if oracle == owner || oracle == arbiter || oracle == feeRecipient {
		panic("RoleCollision")
	}
	chain.Emit("OwnershipTransferred", "previous", "", "next", owner.String())
	chain.Emit("ArbiterChanged", "previous", "", "next", arbiter.String())
	chain.Emit("OracleChanged", "previous", "", "next", oracle.String())
	chain.Emit("FeeRecipientChanged", "previous", "", "next", feeRecipient.String())
	return &Roles{Owner: owner, Arbiter: arbiter, Oracle: oracle, FeeRecipient: feeRecipient}
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

func (r *Roles) AssertOwner(caller address) {
	if caller != r.Owner {
		panic("NotOwner")
	}
}

func (r *Roles) AssertOracle(caller address) {
	if r.Oracle == "" || caller != r.Oracle {
		panic("NotOracle")
	}
}

func (r *Roles) AssertArbiter(caller address) {
	if caller != r.Arbiter {
		panic("NotArbiter")
	}
}

func (r *Roles) AssertNotPaused() {
	if r.Paused {
		panic("IsPaused")
	}
}

func (r *Roles) checkAuditCollision(next address) {
	if next != "" && next == r.AuditAgent {
		panic("RoleCollision")
	}
}

func (r *Roles) TransferOwnership(caller, next address, now int64) {
	r.AssertOwner(caller)
	if !next.IsValid() {
		panic("ZeroAddress")
	}
	r.PendingOwner = next
	r.PendingOwnerEta = now + TimelockSeconds
	chain.Emit("OwnershipTransferStarted", "previous", r.Owner.String(), "next", next.String(), "eta", i64(r.PendingOwnerEta))
}

func (r *Roles) CancelOwnershipTransfer(caller address) {
	r.AssertOwner(caller)
	if r.PendingOwnerEta == 0 {
		panic("NothingQueued")
	}
	chain.Emit("OwnershipTransferCancelled", "pending", r.PendingOwner.String())
	r.PendingOwner = ""
	r.PendingOwnerEta = 0
}

func (r *Roles) AcceptOwnership(caller address, now int64) {
	if r.PendingOwner == "" || caller != r.PendingOwner {
		panic("NotPendingOwner")
	}
	if now < r.PendingOwnerEta {
		panic("Timelocked")
	}
	r.checkAuditCollision(caller)
	chain.Emit("OwnershipTransferred", "previous", r.Owner.String(), "next", caller.String())
	r.Owner = caller
	r.PendingOwner = ""
	r.PendingOwnerEta = 0
}

func (r *Roles) QueueOracle(caller, next address, now int64) {
	r.AssertOwner(caller)
	if !next.IsValid() {
		panic("ZeroAddress")
	}
	if next == r.Owner || next == r.Arbiter || next == r.FeeRecipient {
		panic("RoleCollision")
	}
	r.PendingOracle = next
	r.PendingOracleEta = now + TimelockSeconds
	chain.Emit("OracleChangeQueued", "next", next.String(), "eta", i64(r.PendingOracleEta))
}

// RevokeOracle is the emergency stop: the oracle loses its power at once.
func (r *Roles) RevokeOracle(caller address) {
	r.AssertOwner(caller)
	chain.Emit("OracleChanged", "previous", r.Oracle.String(), "next", "")
	r.Oracle = ""
}

func (r *Roles) CancelOracle(caller address) {
	r.AssertOwner(caller)
	if r.PendingOracleEta == 0 {
		panic("NothingQueued")
	}
	chain.Emit("OracleChangeCancelled", "next", r.PendingOracle.String())
	r.PendingOracle = ""
	r.PendingOracleEta = 0
}

func (r *Roles) ExecuteOracle(now int64) {
	if r.PendingOracleEta == 0 {
		panic("NothingQueued")
	}
	if now < r.PendingOracleEta {
		panic("Timelocked")
	}
	r.checkAuditCollision(r.PendingOracle)
	chain.Emit("OracleChanged", "previous", r.Oracle.String(), "next", r.PendingOracle.String())
	r.Oracle = r.PendingOracle
	r.PendingOracle = ""
	r.PendingOracleEta = 0
}

// SetAuditAgent appoints the reviewer that may dispute with a bond; "" disables it.
func (r *Roles) SetAuditAgent(caller, next address) {
	r.AssertOwner(caller)
	if next != "" && (next == r.Owner || next == r.Arbiter || next == r.Oracle || next == r.FeeRecipient) {
		panic("RoleCollision")
	}
	chain.Emit("AuditAgentChanged", "previous", r.AuditAgent.String(), "next", next.String())
	r.AuditAgent = next
}

func (r *Roles) SetArbiter(caller, next address) {
	r.AssertOwner(caller)
	if !next.IsValid() {
		panic("ZeroAddress")
	}
	if next == r.Oracle {
		panic("RoleCollision")
	}
	r.checkAuditCollision(next)
	chain.Emit("ArbiterChanged", "previous", r.Arbiter.String(), "next", next.String())
	r.Arbiter = next
}

// SetCaps sets guarded launch caps in mUSD units (0 = none). They only gate new positions.
func (r *Roles) SetCaps(caller address, market, account int64) {
	r.AssertOwner(caller)
	if market < 0 || account < 0 {
		panic("BadCap")
	}
	r.MaxMarketStake = market
	r.MaxAccountStake = account
	chain.Emit("CapsChanged", "maxMarketStake", i64(market), "maxAccountStake", i64(account))
}

// CheckCaps panics when an account's stake or a market's total is over its cap.
func (r *Roles) CheckCaps(mine, total int64) {
	if (r.MaxAccountStake != 0 && mine > r.MaxAccountStake) || (r.MaxMarketStake != 0 && total > r.MaxMarketStake) {
		panic("CapExceeded")
	}
}

func (r *Roles) QueueFeeRecipient(caller, next address, now int64) {
	r.AssertOwner(caller)
	if !next.IsValid() {
		panic("ZeroAddress")
	}
	r.PendingFeeRecipient = next
	r.PendingFeeEta = now + TimelockSeconds
	chain.Emit("FeeRecipientQueued", "next", next.String(), "eta", i64(r.PendingFeeEta))
}

func (r *Roles) CancelFeeRecipient(caller address) {
	r.AssertOwner(caller)
	if r.PendingFeeEta == 0 {
		panic("NothingQueued")
	}
	chain.Emit("FeeRecipientCancelled", "next", r.PendingFeeRecipient.String())
	r.PendingFeeRecipient = ""
	r.PendingFeeEta = 0
}

func (r *Roles) ExecuteFeeRecipient(now int64) {
	if r.PendingFeeEta == 0 {
		panic("NothingQueued")
	}
	if now < r.PendingFeeEta {
		panic("Timelocked")
	}
	r.checkAuditCollision(r.PendingFeeRecipient)
	chain.Emit("FeeRecipientChanged", "previous", r.FeeRecipient.String(), "next", r.PendingFeeRecipient.String())
	r.FeeRecipient = r.PendingFeeRecipient
	r.PendingFeeRecipient = ""
	r.PendingFeeEta = 0
}

func (r *Roles) SetPaused(caller address, p bool) {
	r.AssertOwner(caller)
	r.Paused = p
	if p {
		chain.Emit("Paused", "paused", "true")
	} else {
		chain.Emit("Paused", "paused", "false")
	}
}

// ParseOptional reads an optional address argument: "" means none.
func ParseOptional(s string) address {
	if s == "" {
		return ""
	}
	a := address(s)
	if !a.IsValid() {
		panic("BadAddress")
	}
	return a
}

// Package mimir holds the pure helpers Mimir's market realms share: stake
// history checkpoints (settlement cutoffs) and overflow-safe arithmetic.
package mimir

// Amounts are cumulative net deposits on each side, and the copied part of each.
type Amounts struct {
	A, B, CopiedA, CopiedB int64
}

type Checkpoint struct {
	At      int64 // unix seconds
	Amounts Amounts
}

// History is an append-only list of checkpoints in time order. Deposits in the
// same second coalesce into one checkpoint. Settlement never scans all deposits.
type History struct {
	points []Checkpoint
}

// Record stores the running totals as of `now`.
func (h *History) Record(now int64, a Amounts) {
	n := len(h.points)
	if n != 0 && h.points[n-1].At == now {
		h.points[n-1].Amounts = a
		return
	}
	h.points = append(h.points, Checkpoint{At: now, Amounts: a})
}

// Before returns the totals recorded strictly before cutoff. A cutoff of 0
// means no cutoff: the latest totals.
func (h *History) Before(cutoff int64) Amounts {
	hi := len(h.points)
	if hi == 0 {
		return Amounts{}
	}
	if cutoff == 0 {
		return h.points[hi-1].Amounts
	}
	lo := 0
	for lo < hi {
		mid := lo + (hi-lo)/2
		if h.points[mid].At < cutoff {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo == 0 {
		return Amounts{}
	}
	return h.points[lo-1].Amounts
}

func (h *History) Len() int { return len(h.points) }

// Package musd is Mimir USD (mUSD), the GRC20 test dollar Mimir markets stake
// on gno.land. It has 6 decimals, like USDC: 1 mUSD = 1_000_000 units.
//
// Anyone can call Faucet once per FaucetCooldown to receive FaucetAmount.
// It is a testnet token: it has no value and no backing.
package musd

import (
	"chain"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Deployer owns Mint, used to seed agent and council wallets.
const Deployer = address("g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz")

const (
	Decimals       = 6
	Unit           = int64(1_000_000)
	FaucetAmount   = 1_000 * Unit
	FaucetCooldown = 24 * time.Hour
)

var (
	Token      *grc20.Token
	ledger     *grc20.PrivateLedger
	userTeller grc20.Teller
	Ownable    *ownable.Ownable
	// lastDrip: address -> unix seconds of the last faucet payout.
	lastDrip avl.Tree
)

func init(cur realm) {
	Token, ledger = grc20.NewToken("Mimir USD", "mUSD", Decimals, 0, cur)
	userTeller = ledger.CallerTeller()
	Ownable = ownable.NewWithAddress(Deployer)
}

func TotalSupply() int64                     { return userTeller.TotalSupply() }
func BalanceOf(owner address) int64          { return userTeller.BalanceOf(owner) }
func Allowance(owner, spender address) int64 { return userTeller.Allowance(owner, spender) }

func Transfer(cur realm, to address, amount int64) {
	check(userTeller.Transfer(0, cur, to, amount))
}

func Approve(cur realm, spender address, amount int64) {
	check(userTeller.Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, from, to address, amount int64) {
	check(userTeller.TransferFrom(0, cur, from, to, amount))
}

// Faucet pays FaucetAmount to the caller, at most once per FaucetCooldown.
func Faucet(cur realm) {
	caller := cur.Previous().Address()
	now := time.Now().Unix()
	if v := lastDrip.Get(caller.String()); v != nil {
		next := v.(int64) + int64(FaucetCooldown/time.Second)
		if now < next {
			panic(ufmt.Sprintf("faucet: next drip at unix %d", next))
		}
	}
	lastDrip.Set(caller.String(), now)
	check(ledger.Mint(caller, FaucetAmount))
	chain.Emit("Faucet", "to", caller.String(), "amount", ufmt.Sprintf("%d", FaucetAmount))
}

// NextDrip is the unix time from which addr may use the faucet again (0: now).
func NextDrip(addr address) int64 {
	v := lastDrip.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64) + int64(FaucetCooldown/time.Second)
}

// Mint is for the owner, to seed agent and council wallets.
func Mint(cur realm, to address, amount int64) {
	Ownable.AssertOwnedBy(cur.Previous().Address())
	check(ledger.Mint(to, amount))
}

func Render(path string) string {
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return Token.RenderHome() + "\n" + ufmt.Sprintf(
			"Faucet: %d mUSD per address every %s. Call `Faucet` from your wallet.\n",
			FaucetAmount/Unit, FaucetCooldown.String())
	case len(parts) == 2 && parts[0] == "balance":
		return ufmt.Sprintf("%d\n", userTeller.BalanceOf(address(parts[1])))
	default:
		return "404\n"
	}
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// Package fees is the entry-fee rate each account pays on Mimir's pool and VS
// markets (the gno.land port of contracts/MimirFees.sol).
//
// Everyone pays BaseBps (0.5%) of what they put in. A lower rate needs a fee
// ticket signed by the signer: "this account is tier T until `expires`". The
// account submits it with ApplyTicket, normally in the same transaction as its
// stake. Mimir's server signs no tickets.
//
// Signatures are ed25519 over TicketMessage(account, tier, expires), which
// binds the chain id and this realm's path, so a ticket cannot be replayed on
// another network or another deployment.
//
// Trust: the signer can only lower an account's rate (BaseBps is the most
// anyone pays), so a stolen signer key costs the protocol revenue, never a user
// money. The owner revokes it at once (RevokeSigner); a new signer waits
// SignerTimelock, so a stolen owner key cannot install one quietly. Both retire
// every ticket the old signer issued (each ticket carries the signer epoch it
// was applied under).
package fees

import (
	"chain"
	"chain/runtime"
	"crypto/ed25519"
	"encoding/hex"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Deployer is the initial owner, the address that deploys these realms.
const Deployer = address("g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz")

const (
	BaseBps   = int64(50) // 0.5%
	HolderBps = int64(25) // 0.25%: tier 1 ticket
	WhaleBps  = int64(10) // 0.1%: tier 2 ticket

	// A ticket may not outlive this, so a discount ends within two days.
	MaxTicketSeconds         = int64(2 * 24 * 60 * 60)
	OwnershipTimelockSeconds = int64(2 * 24 * 60 * 60)
	SignerTimelockSeconds    = int64(2 * 24 * 60 * 60)
)

type Ticket struct {
	Tier    int
	Expires int64
	Epoch   int64
}

var (
	tickets avl.Tree // address -> *Ticket

	signer          []byte // ed25519 public key; nil when revoked or unset
	owner           address
	pendingOwner    address
	pendingOwnerEta int64
	// Bumped on every signer change or revoke: tickets applied under an earlier epoch pay BaseBps.
	signerEpoch      int64
	pendingSigner    []byte
	pendingSignerEta int64
	signerEverSet    bool
	selfPath         string
)

func init(cur realm) {
	owner = Deployer
	selfPath = cur.PkgPath()
	chain.Emit("OwnershipTransferred", "previous", "", "next", owner.String())
}

func now() int64 { return time.Now().Unix() }

func assertOwner(cur realm) {
	if cur.Previous().Address() != owner {
		panic("NotOwner")
	}
}

func decodeKey(pubHex string) []byte {
	k, err := hex.DecodeString(pubHex)
	if err != nil || len(k) != 32 {
		panic("BadSignerKey")
	}
	return k
}

// SetInitialSigner installs the first signer, once, as the Solidity
// constructor did. Every later change goes through the timelock.
func SetInitialSigner(cur realm, pubHex string) {
	assertOwner(cur)
	if signerEverSet {
		panic("SignerAlreadySet")
	}
	signer = decodeKey(pubHex)
	signerEverSet = true
	chain.Emit("SignerChanged", "previous", "", "next", pubHex)
}

// RevokeSigner is the emergency stop: no ticket verifies any more, and the
// ones applied stop counting.
func RevokeSigner(cur realm) {
	assertOwner(cur)
	chain.Emit("SignerChanged", "previous", hex.EncodeToString(signer), "next", "")
	signer = nil
	signerEverSet = true
	signerEpoch++
}

func QueueSigner(cur realm, pubHex string) {
	assertOwner(cur)
	pendingSigner = decodeKey(pubHex)
	pendingSignerEta = now() + SignerTimelockSeconds
	chain.Emit("SignerQueued", "next", pubHex, "eta", strconv.FormatInt(pendingSignerEta, 10))
}

// ExecuteSigner is permissionless once due, like the market realms' queued changes.
func ExecuteSigner(cur realm) {
	if pendingSignerEta == 0 {
		panic("NothingQueued")
	}
	if now() < pendingSignerEta {
		panic("Timelocked")
	}
	chain.Emit("SignerChanged", "previous", hex.EncodeToString(signer), "next", hex.EncodeToString(pendingSigner))
	signer = pendingSigner
	signerEverSet = true
	signerEpoch++
	pendingSigner = nil
	pendingSignerEta = 0
}

func TransferOwnership(cur realm, next address) {
	assertOwner(cur)
	if !next.IsValid() {
		panic("ZeroAddress")
	}
	pendingOwner = next
	pendingOwnerEta = now() + OwnershipTimelockSeconds
	chain.Emit("OwnershipTransferStarted", "previous", owner.String(), "next", next.String(),
		"eta", strconv.FormatInt(pendingOwnerEta, 10))
}

func CancelOwnershipTransfer(cur realm) {
	assertOwner(cur)
	if pendingOwner == "" {
		panic("NotPendingOwner")
	}
	chain.Emit("OwnershipTransferCancelled", "pending", pendingOwner.String())
	pendingOwner = ""
	pendingOwnerEta = 0
}

func AcceptOwnership(cur realm) {
	caller := cur.Previous().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("NotPendingOwner")
	}
	if now() < pendingOwnerEta {
		panic("Timelocked")
	}
	chain.Emit("OwnershipTransferred", "previous", owner.String(), "next", caller.String())
	owner = caller
	pendingOwner = ""
	pendingOwnerEta = 0
}

// TicketMessage is the exact byte string the signer signs for (account, tier, expires).
func TicketMessage(account address, tier int, expires int64) string {
	return ufmt.Sprintf("Mimir Fees v1|%s|%s|%s|%d|%d",
		runtime.ChainID(), selfPath, account.String(), tier, expires)
}

// ApplyTicket stores a signed tier for the caller: a ticket is bound to the
// account it was signed for.
func ApplyTicket(cur realm, tier int, expires int64, sigHex string) {
	account := cur.Previous().Address()
	if tier < 0 || tier > 2 {
		panic("BadTier")
	}
	if expires <= now() || expires > now()+MaxTicketSeconds {
		panic("BadExpiry")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != 64 || signer == nil {
		panic("BadSignature")
	}
	if !ed25519.Verify(signer, []byte(TicketMessage(account, tier, expires)), sig) {
		panic("BadSignature")
	}
	tickets.Set(account.String(), &Ticket{Tier: tier, Expires: expires, Epoch: signerEpoch})
	chain.Emit("TicketApplied", "account", account.String(), "tier", strconv.Itoa(tier),
		"expires", strconv.FormatInt(expires, 10))
}

// EntryBps is the account's entry fee in basis points right now.
func EntryBps(account address) int64 {
	v := tickets.Get(account.String())
	if v == nil {
		return BaseBps
	}
	t := v.(*Ticket)
	if t.Expires <= now() || t.Epoch != signerEpoch {
		return BaseBps
	}
	switch t.Tier {
	case 2:
		return WhaleBps
	case 1:
		return HolderBps
	}
	return BaseBps
}

func Owner() address        { return owner }
func PendingOwner() address { return pendingOwner }
func SignerEpoch() int64    { return signerEpoch }
func Signer() string        { return hex.EncodeToString(signer) }

func Render(path string) string {
	if path != "" {
		return ufmt.Sprintf("Entry fee for %s: %d bps\n", path, EntryBps(address(path)))
	}
	return ufmt.Sprintf("# Mimir fees\n\nBase entry fee: %d bps (0.5%%). Tier 1: %d bps. Tier 2: %d bps.\n\n"+
		"Owner: %s\n\nSigner epoch: %d\n\nLook up an account: `:<address>`\n",
		BaseBps, HolderBps, WhaleBps, owner.String(), signerEpoch)
}

package pool

import (
	mimir "gno.land/p/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/mimir"
)

// Role administration. The rules live in mimir.Roles; see its doc.

func TransferOwnership(cur realm, next address) { roles.TransferOwnership(caller(cur), next, now()) }
func CancelOwnershipTransfer(cur realm)         { roles.CancelOwnershipTransfer(caller(cur)) }
func AcceptOwnership(cur realm)                 { roles.AcceptOwnership(caller(cur), now()) }
func QueueOracle(cur realm, next address)       { roles.QueueOracle(caller(cur), next, now()) }
func RevokeOracle(cur realm)                    { roles.RevokeOracle(caller(cur)) }
func CancelOracle(cur realm)                    { roles.CancelOracle(caller(cur)) }
func ExecuteOracle(cur realm)                   { roles.ExecuteOracle(now()) }
func SetArbiter(cur realm, next address)        { roles.SetArbiter(caller(cur), next) }
func QueueFeeRecipient(cur realm, next address) { roles.QueueFeeRecipient(caller(cur), next, now()) }
func CancelFeeRecipient(cur realm)              { roles.CancelFeeRecipient(caller(cur)) }
func ExecuteFeeRecipient(cur realm)             { roles.ExecuteFeeRecipient(now()) }
func SetPaused(cur realm, p bool)               { roles.SetPaused(caller(cur), p) }

// SetAuditAgent appoints the reviewer that may dispute with a bond; "" disables it.
func SetAuditAgent(cur realm, next string) {
	roles.SetAuditAgent(caller(cur), mimir.ParseOptional(next))
}

// SetCaps sets guarded launch caps in net mUSD units (0 = none). They only gate new stakes.
func SetCaps(cur realm, market, account int64) { roles.SetCaps(caller(cur), market, account) }

// SetLockAt closes a market to new stakes early (kickoff), by its creator or
// the owner. Only ever earlier.
func SetLockAt(cur realm, id int64, at int64) {
	m := getMarket(id)
	c := caller(cur)
	if c != m.Creator && c != roles.Owner {
		panic("BadLock")
	}
	if m.State != StOpen || at < now() || at+LockSeconds > m.Deadline {
		panic("BadLock")
	}
	if m.LockAt != 0 && at > m.LockAt {
		panic("BadLock")
	}
	m.LockAt = at
	emit("LockSet", "id", itoa(id), "lockAt", itoa(at))
}

package pool

import (
	mimir "gno.land/p/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/mimir"
)

// owed is what `user` is owed from a resolved market: gross = stake back +
// share of the losing side. Full refund when either side is empty or on DRAW /
// UNRESOLVABLE. feeBase is the profit copy fees may be charged on: the user's
// NET profit (the share less their own stake on the losing side, so a hedger
// never pays a copy fee on their own money), counted only on the copied part
// of the winning stake. Deposits at or after the settlement cutoff are late:
// their net principal comes back and they share in nothing.
func owed(m *Market, p *Position) (gross, feeBase int64) {
	if p == nil {
		return 0, 0
	}
	raw := p.A + p.B
	if m.Outcome >= Draw {
		return raw, 0
	}
	totals := m.history.Before(m.SettlementCutoff)
	mine := p.history.Before(m.SettlementCutoff)
	if totals.A == 0 || totals.B == 0 {
		return raw, 0
	}
	late := raw - mine.A - mine.B
	win, lose, copied, opposite, winners := mine.A, mine.B, mine.CopiedA, totals.B, totals.A
	if m.Outcome == SideB {
		win, lose, copied, opposite, winners = mine.B, mine.A, mine.CopiedB, totals.A, totals.B
	}
	if win == 0 {
		return late, 0
	}
	profit := mimir.MulDiv(win, opposite, winners)
	gross = late + win + profit
	if profit > lose && copied != 0 {
		feeBase = mimir.MulDiv(profit-lose, copied, win)
	}
	return gross, feeBase
}

func winnerPayout(m *Market, p *Position) bool {
	if m.Outcome >= Draw || p == nil {
		return false
	}
	totals := m.history.Before(m.SettlementCutoff)
	if totals.A == 0 || totals.B == 0 {
		return false
	}
	mine := p.history.Before(m.SettlementCutoff)
	if m.Outcome == SideA {
		return mine.A != 0
	}
	return mine.B != 0
}

// copyFees are the copy-trade fees on the copied net profit: (to the
// referrer, to the platform). Nobody pays themselves: a referrer or fee
// recipient who is the user waives that leg.
func copyFees(user address, p *Position, feeBase int64) (toRef, toPlatform int64) {
	if feeBase == 0 || p.Referrer == "" || p.Referrer == user {
		return 0, 0
	}
	toRef = mimir.MulDiv(feeBase, ReferrerFeeBps, 10_000)
	if roles.FeeRecipient != user {
		toPlatform = mimir.MulDiv(feeBase, CopyFeeBps, 10_000)
	}
	return toRef, toPlatform
}

// Claim collects the caller's own payout.
func Claim(cur realm, id int64) {
	claimFor(cur, id, caller(cur))
}

// ClaimFor lets anyone push a user's payout to them. The money only ever goes to `user`.
func ClaimFor(cur realm, id int64, user address) {
	claimFor(cur, id, user)
}

func claimFor(cur realm, id int64, user address) {
	m := getMarket(id)
	if m.State != StResolved {
		panic("NotResolved")
	}
	p := m.position(user)
	// Paused: refunds still go out; a winner waits for the unpause.
	if roles.Paused && winnerPayout(m, p) {
		panic("IsPaused")
	}
	if p != nil && p.Claimed {
		panic("AlreadyClaimed")
	}
	gross, feeBase := owed(m, p)
	if gross == 0 {
		panic("NothingToClaim")
	}
	p.Claimed = true
	toRef, toPlatform := copyFees(user, p, feeBase)
	if toRef != 0 {
		accrue(id, p.Referrer, toRef)
	}
	if toPlatform != 0 {
		accrue(id, roles.FeeRecipient, toPlatform)
	}
	fee := toRef + toPlatform
	emit("Claimed", "id", itoa(id), "user", user.String(), "paid", itoa(gross-fee), "fee", itoa(fee))
	push(cur, user, gross-fee)
}

// ClaimFees pays the caller's accrued fees (entry fees, copy fees, forfeited bonds).
func ClaimFees(cur realm) {
	claimFeesTo(cur, caller(cur))
}

func ClaimFeesTo(cur realm, to address) {
	if !to.IsValid() {
		panic("ZeroAddress")
	}
	claimFeesTo(cur, to)
}

func claimFeesTo(cur realm, to address) {
	c := caller(cur)
	amount := feesOf(c)
	if amount == 0 {
		panic("NothingToWithdraw")
	}
	accruedFees.Set(c.String(), int64(0))
	lifetimeFeesClaimed = mimir.Add(lifetimeFeesClaimed, amount)
	emit("FeeClaimed", "recipient", c.String(), "to", to.String(), "amount", itoa(amount))
	push(cur, to, amount)
}

package pool

import (
	mimir "gno.land/p/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/mimir"
)

// CreateMarket opens a market with `amount` mUSD (pulled from the caller,
// less the entry fee) staked on `side` (SideA or SideB). `referrer` is the
// copied basket's creator, or "" for none. Returns the new market's id.
func CreateMarket(cur realm, question, labelA, labelB, resolutionURL, category string,
	deadline int64, side int, referrer string, amount int64) int64 {
	assertNotPaused()
	if question == "" {
		panic("EmptyQuestion")
	}
	// At most a year out, so a staked market never locks funds indefinitely.
	if deadline < now()+LockSeconds || deadline > now()+MaxDeadlineAhead {
		panic("BadDeadline")
	}
	marketCount++
	id := marketCount
	m := &Market{
		ID:            id,
		Creator:       caller(cur),
		Deadline:      deadline,
		CreatedAt:     now(),
		Question:      question,
		LabelA:        labelA,
		LabelB:        labelB,
		ResolutionURL: resolutionURL,
		Category:      category,
	}
	markets.Set(key(id), m)
	emit("MarketCreated", "id", itoa(id), "creator", m.Creator.String(), "deadline", itoa(deadline), "category", category)
	addStake(cur, m, side, parseReferrer(referrer), amount)
	return id
}

// Stake puts `amount` mUSD (less the entry fee) on `side`. Repeated stakes add up.
func Stake(cur realm, id int64, side int, referrer string, amount int64) {
	assertNotPaused()
	m := getMarket(id)
	if m.State != StOpen {
		panic("NotOpen")
	}
	if now()+LockSeconds > m.Deadline {
		panic("BettingClosed")
	}
	if m.LockAt != 0 && now() >= m.LockAt {
		panic("BettingClosed")
	}
	addStake(cur, m, side, parseReferrer(referrer), amount)
}

func addStake(cur realm, m *Market, side int, referrer address, amount int64) {
	if amount < MinStake {
		panic("StakeTooSmall")
	}
	user := caller(cur)
	pull(cur, user, amount)
	bps := entryBps(user)
	if bps > MaxEntryBps {
		panic("EntryFeeTooHigh")
	}
	fee := mimir.MulDiv(amount, bps, 10_000)
	if fee != 0 {
		m.EntryFees += fee
		accrue(m.ID, roles.FeeRecipient, fee)
	}
	net := amount - fee
	p := m.mustPosition(user)
	switch side {
	case SideA:
		p.A = mimir.Add(p.A, net)
		m.TotalA = mimir.Add(m.TotalA, net)
		if referrer != "" {
			p.CopyA += net
		}
	case SideB:
		p.B = mimir.Add(p.B, net)
		m.TotalB = mimir.Add(m.TotalB, net)
		if referrer != "" {
			p.CopyB += net
		}
	default:
		panic("BadSide")
	}
	if referrer != "" && p.Referrer == "" {
		p.Referrer = referrer
		emit("ReferrerSet", "id", itoa(m.ID), "user", user.String(), "referrer", referrer.String())
	}
	mine := p.A + p.B
	roles.CheckCaps(mine, m.TotalA+m.TotalB)
	m.history.Record(now(), mimir.Amounts{A: m.TotalA, B: m.TotalB})
	p.history.Record(now(), mimir.Amounts{A: p.A, B: p.B, CopiedA: p.CopyA, CopiedB: p.CopyB})
	emit("Staked", "id", itoa(m.ID), "user", user.String(), "side", itoa(int64(side)), "amount", itoa(net))
}

// Package pool is Mimir's two-sided pool prediction market, settled by an AI
// oracle: the gno.land port of contracts/MimirPoolErc20.sol. Stakes are mUSD
// (gno.land/r/.../musd, 6 decimals).
//
// Model
//   - A market has two sides, A and B (YES / NO). The creator opens it with a
//     stake on one side. Anyone, the creator included, can then stake on either
//     side until LockSeconds before the deadline. Stakes by the same address
//     add up per side.
//   - After the deadline the oracle proposes A, B, DRAW or UNRESOLVABLE. A
//     participant can dispute within the dispute window by posting
//     DisputeBond; the arbiter then rules. The bond comes back if the ruling
//     changes the verdict and goes to the platform otherwise. An undisputed
//     proposal is finalized by anyone.
//   - Escape hatch: ResolutionGraceSeconds after the deadline (or after the
//     proposal or dispute), anyone can refund the market in full. From that
//     moment the oracle and the arbiter can no longer rule.
//   - Fees: every stake pays an entry fee, fees.EntryBps(caller) of the amount
//     (0.5% by default, less with a signed ticket); the rest is staked. The
//     entry fee is kept on refunds. Winnings pay no fee, except copy trades: a
//     stake made with a referrer pays ReferrerFeeBps of its net profit to the
//     referrer and CopyFeeBps to the platform.
//   - Payout: a winner gets their stake back plus a pro-rata share of the
//     losing side, rounded down (dust stays in the realm). If either side is
//     empty, or on DRAW / UNRESOLVABLE, everyone gets their stake back.
//   - Settlement only records the outcome. Each staker is then paid by
//     Claim(id), or by anyone through ClaimFor(id, user).
//   - Roles: owner, arbiter (rules disputes), oracle (may never also be owner,
//     arbiter or fee recipient), fee recipient, and an optional audit agent
//     that may dispute. Ownership, oracle and fee-recipient changes are
//     timelocked; the owner can revoke the oracle at once, veto a proposal to
//     the arbiter, cap stakes, set an early lock and pause.
//   - Pause stops new markets and stakes AND settlement and winners' payouts;
//     refunds are still paid, and RefundExpired while paused refunds instead of
//     honouring a proposal.
//
// Differences from the EVM contract, all from the transport:
//   - Amounts are mUSD units in int64; MinStake, DisputeBond and caps are in
//     those units. The caller approves this realm on mUSD first; Adena sends
//     the approve and the call in one transaction, so there are no *WithPermit
//     variants.
//   - mUSD has no blacklist and no callbacks, so a payout cannot be refused and
//     cannot re-enter: payouts are sent directly (no parked withdrawals, no
//     gas stipend, no reentrancy lock).
//   - Times are block-time unix seconds.
package pool

import (
	"chain"
	"chain/runtime"
	"strconv"
	"time"

	mimir "gno.land/p/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/mimir"
	"gno.land/p/nt/avl/v0"
	"gno.land/r/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/fees"
	"gno.land/r/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/musd"
)

// Market states.
const (
	StOpen     = 0
	StProposed = 1
	StDisputed = 2
	StResolved = 3
)

// Sides and outcomes.
const (
	SideA        = 1
	SideB        = 2
	Draw         = 3
	Unresolvable = 4
)

const (
	// MinStake is the smallest gross stake: 0.1 mUSD.
	MinStake = int64(100_000)
	// DisputeBond is 2 mUSD, independent of the stake minimum so disputes stay costly to spam.
	DisputeBond = int64(2_000_000)
	// No new stakes in the final LockSeconds before the deadline (anti-sniping).
	LockSeconds      = int64(60)
	MaxDeadlineAhead = int64(365 * 24 * 60 * 60)
	// Entry fees above 1% are refused, whatever the fee realm answers.
	MaxEntryBps            = int64(100)
	ReferrerFeeBps         = int64(100)
	CopyFeeBps             = int64(100)
	ResolutionGraceSeconds = int64(7 * 24 * 60 * 60)
	MaxDisputeWindow       = int64(7 * 24 * 60 * 60)
	// On mainnet a proposal stays disputable at least this long.
	MinLiveDisputeWindow = int64(24 * 60 * 60)
	// TestnetDisputeWindow lets a testnet show the whole flow in minutes.
	TestnetDisputeWindow = int64(10 * 60)
)

// Initial roles. The owner can change each one afterwards.
const (
	Deployer       = address("g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz")
	InitialOracle  = address("g18pnec3atge4msr5hhanm790tljtdyd87s0wguh")
	InitialArbiter = address("g1af78r3tuv84mf3cd0kxrssmw6g2v2mvvc6phpv")
)

type Market struct {
	ID            int64
	Creator       address
	Deadline      int64
	CreatedAt     int64
	State         int
	Outcome       int // final, once resolved
	Proposed      int // the oracle's proposal
	ProposedAt    int64
	DisputedAt    int64
	Disputer      address
	Bond          int64
	TotalA        int64
	TotalB        int64
	EvidenceHash  string // hex sha256 of the oracle's evidence
	Question      string
	LabelA        string
	LabelB        string
	ResolutionURL string
	Category      string
	Summary       string
	// 0 includes all deposits; otherwise only deposits strictly before it compete.
	SettlementCutoff int64
	// Optional early close: stakes stop at LockAt instead of LockSeconds before the deadline.
	LockAt    int64
	EntryFees int64

	history   mimir.History // market totals over time
	positions avl.Tree      // address -> *Position
}

type Position struct {
	A, B         int64 // net stakes
	CopyA, CopyB int64 // the copied part of each
	Referrer     address
	Claimed      bool
	history      mimir.History
}

var (
	markets     avl.Tree // padded id -> *Market
	marketCount int64

	accruedFees         avl.Tree // address -> int64
	lifetimeFeesAccrued int64
	lifetimeFeesClaimed int64

	roles         *mimir.Roles
	disputeWindow int64
)

func init(cur realm) {
	roles = mimir.NewRoles(Deployer, InitialArbiter, InitialOracle, Deployer)
	disputeWindow = TestnetDisputeWindow
	if runtime.ChainID() == "gnoland-1" {
		disputeWindow = MinLiveDisputeWindow
	}
}

func now() int64 { return time.Now().Unix() }

func emit(typ string, attrs ...string) { chain.Emit(typ, attrs...) }

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func key(id int64) string {
	s := itoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func getMarket(id int64) *Market {
	v := markets.Get(key(id))
	if v == nil {
		panic("NoMarket")
	}
	return v.(*Market)
}

func (m *Market) position(user address) *Position {
	if v := m.positions.Get(user.String()); v != nil {
		return v.(*Position)
	}
	return nil
}

func (m *Market) mustPosition(user address) *Position {
	p := m.position(user)
	if p == nil {
		p = &Position{}
		m.positions.Set(user.String(), p)
	}
	return p
}

func feesOf(a address) int64 {
	if v := accruedFees.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

func accrue(id int64, to address, amount int64) {
	accruedFees.Set(to.String(), mimir.Add(feesOf(to), amount))
	lifetimeFeesAccrued = mimir.Add(lifetimeFeesAccrued, amount)
	emit("FeeAccrued", "id", itoa(id), "recipient", to.String(), "amount", itoa(amount))
}

// pull moves exactly amount mUSD from the caller into this realm (needs an allowance).
func pull(cur realm, from address, amount int64) {
	musd.TransferFrom(cross(cur), from, cur.Address(), amount)
}

func push(cur realm, to address, amount int64) {
	if amount == 0 {
		return
	}
	musd.Transfer(cross(cur), to, amount)
}

func caller(cur realm) address { return cur.Previous().Address() }

func assertOwner(cur realm) { roles.AssertOwner(caller(cur)) }

func assertNotPaused() { roles.AssertNotPaused() }

func parseReferrer(s string) address { return mimir.ParseOptional(s) }

func entryBps(a address) int64 { return fees.EntryBps(a) }

package pool

import (
	"strconv"
	"strings"
	"time"

	mimir "gno.land/p/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/mimir"
	"gno.land/p/nt/ufmt/v0"
)

var stateNames = []string{"Open", "Proposed", "Disputed", "Resolved"}

func outcomeName(m *Market, o int) string {
	switch o {
	case SideA:
		return mimir.Escape(m.LabelA)
	case SideB:
		return mimir.Escape(m.LabelB)
	case Draw:
		return "Draw (refund)"
	case Unresolvable:
		return "Unresolvable (refund)"
	}
	return "-"
}

func pct(a, b int64) int64 {
	if a+b == 0 {
		return 50
	}
	return mimir.MulDiv(a, 100, a+b)
}

func when(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04 UTC")
}

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil || id < 1 || id > marketCount {
		return "# Not found\n\n[All markets](:)\n"
	}
	return renderMarket(getMarket(id))
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Mimir pools\n\n")
	b.WriteString("Claim markets that settle themselves. Stake mUSD on either side of a question; ")
	b.WriteString("an AI roles.Oracle proposes the result after the deadline, anyone in the market can dispute it, ")
	b.WriteString("and draws or unclear questions refund everyone.\n\n")
	b.WriteString(ufmt.Sprintf("%d markets · minimum stake %s mUSD · dispute bond %s mUSD · dispute window %d min\n\n",
		marketCount, mimir.FormatUSD(MinStake), mimir.FormatUSD(DisputeBond), disputeWindow/60))
	if marketCount == 0 {
		b.WriteString("No markets yet.\n")
		return b.String()
	}
	b.WriteString("| # | Question | Sides | Pool (mUSD) | State | Closes |\n|---|---|---|---|---|---|\n")
	markets.ReverseIterateByOffset(0, 50, func(_ string, v any) bool {
		m := v.(*Market)
		b.WriteString(ufmt.Sprintf("| [%d](:%d) | %s | %s %d%% · %s %d%% | %s | %s | %s |\n",
			m.ID, m.ID, mimir.Escape(m.Question),
			mimir.Escape(m.LabelA), pct(m.TotalA, m.TotalB), mimir.Escape(m.LabelB), pct(m.TotalB, m.TotalA),
			mimir.FormatUSD(m.TotalA+m.TotalB), stateNames[m.State], when(m.Deadline)))
		return false
	})
	return b.String()
}

func renderMarket(m *Market) string {
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# %s\n\n", mimir.Escape(m.Question)))
	b.WriteString(ufmt.Sprintf("Market #%d · %s · %s\n\n", m.ID, mimir.Escape(m.Category), stateNames[m.State]))
	b.WriteString(ufmt.Sprintf("| Side | Pool (mUSD) | Implied |\n|---|---|---|\n| A: %s | %s | %d%% |\n| B: %s | %s | %d%% |\n\n",
		mimir.Escape(m.LabelA), mimir.FormatUSD(m.TotalA), pct(m.TotalA, m.TotalB),
		mimir.Escape(m.LabelB), mimir.FormatUSD(m.TotalB), pct(m.TotalB, m.TotalA)))
	b.WriteString(ufmt.Sprintf("- Closes: %s\n- Source: %s\n- Creator: %s\n- Participants: %d\n",
		when(m.Deadline), mimir.Escape(m.ResolutionURL), m.Creator.String(), m.positions.Size()))
	if m.LockAt != 0 {
		b.WriteString(ufmt.Sprintf("- Staking locks early: %s\n", when(m.LockAt)))
	}
	switch m.State {
	case StProposed:
		b.WriteString(ufmt.Sprintf("\n## Proposed: %s\n\nDisputable until %s.\n\n> %s\n\nEvidence: %s\n",
			outcomeName(m, m.Proposed), when(m.ProposedAt+disputeWindow), mimir.Escape(m.Summary), hashOrNone(m.EvidenceHash)))
	case StDisputed:
		b.WriteString(ufmt.Sprintf("\n## Disputed\n\nThe roles.Oracle proposed %s; the roles.Arbiter rules.\n\n> %s\n",
			outcomeName(m, m.Proposed), mimir.Escape(m.Summary)))
	case StResolved:
		b.WriteString(ufmt.Sprintf("\n## Result: %s\n\n> %s\n\nEvidence: %s\n",
			outcomeName(m, m.Outcome), mimir.Escape(m.Summary), hashOrNone(m.EvidenceHash)))
	}
	b.WriteString("\n## Act\n\n")
	b.WriteString("Approve this realm on mUSD first, then call:\n\n")
	b.WriteString(ufmt.Sprintf("- [Stake](%s) · [Claim](%s) · [Finalize](%s) · [Dispute](%s)\n\n[All markets](:)\n",
		helpLink("Stake", m.ID), helpLink("Claim", m.ID), helpLink("Finalize", m.ID), helpLink("Dispute", m.ID)))
	return b.String()
}

func helpLink(fn string, id int64) string {
	return ufmt.Sprintf("$help&func=%s&id=%d", fn, id)
}

func hashOrNone(h string) string {
	if h == "" {
		return "none"
	}
	return "`" + h + "`"
}

package pool

func validOutcome(outcome int) {
	if outcome < SideA || outcome > Unresolvable {
		panic("BadSide")
	}
}

func validHash(h string) {
	if h == "" {
		return
	}
	if len(h) != 64 {
		panic("BadEvidenceHash")
	}
	for _, c := range h {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			panic("BadEvidenceHash")
		}
	}
}

// refundAt is when RefundExpired opens: grace from the latest deadline, proposal or dispute.
func refundAt(m *Market) int64 {
	start := m.Deadline
	if m.ProposedAt > start {
		start = m.ProposedAt
	}
	if m.DisputedAt > start {
		start = m.DisputedAt
	}
	return start + ResolutionGraceSeconds
}

func setCutoff(m *Market, cutoff int64) {
	if cutoff > now() || cutoff < 0 {
		panic("BadCutoff")
	}
	m.SettlementCutoff = cutoff
	emit("SettlementCutoffSet", "id", itoa(m.ID), "cutoff", itoa(cutoff))
}

// Resolve is the oracle's verdict: final at once with no dispute window, else a proposal.
func Resolve(cur realm, id int64, outcome int, summary, evidenceHash string) {
	resolve(cur, id, outcome, summary, evidenceHash, 0)
}

// ResolveWithCutoff also sets the settlement cutoff: only deposits strictly
// before it compete; later ones get their net principal back.
func ResolveWithCutoff(cur realm, id int64, outcome int, summary, evidenceHash string, cutoff int64) {
	resolve(cur, id, outcome, summary, evidenceHash, cutoff)
}

func resolve(cur realm, id int64, outcome int, summary, evidenceHash string, cutoff int64) {
	assertNotPaused()
	roles.AssertOracle(caller(cur))
	m := getMarket(id)
	if m.State != StOpen {
		panic("NotOpen")
	}
	if now() < m.Deadline {
		panic("NotExpired")
	}
	if now() >= refundAt(m) {
		panic("GraceOver")
	}
	validOutcome(outcome)
	validHash(evidenceHash)
	setCutoff(m, cutoff)
	if disputeWindow == 0 {
		settle(m, outcome, summary, evidenceHash)
		return
	}
	m.State = StProposed
	m.Proposed = outcome
	m.ProposedAt = now()
	m.EvidenceHash = evidenceHash
	m.Summary = summary
	emit("ResolutionProposed", "id", itoa(id), "outcome", itoa(int64(outcome)),
		"evidenceHash", evidenceHash, "disputableUntil", itoa(now()+disputeWindow))
}

// Dispute escalates the proposal to the arbiter, pulling DisputeBond mUSD.
// Open to the market's participants, the audit agent and the arbiter.
func Dispute(cur realm, id int64) {
	m := getMarket(id)
	if m.State != StProposed {
		panic("NotProposed")
	}
	if now() >= m.ProposedAt+disputeWindow {
		panic("WindowClosed")
	}
	c := caller(cur)
	p := m.position(c)
	staked := p != nil && (p.A != 0 || p.B != 0)
	if !staked && (roles.AuditAgent == "" || c != roles.AuditAgent) && c != roles.Arbiter {
		panic("NotParticipant")
	}
	pull(cur, c, DisputeBond)
	m.State = StDisputed
	m.Disputer = c
	m.DisputedAt = now()
	m.Bond = DisputeBond
	emit("ResolutionDisputed", "id", itoa(id), "disputer", c.String(), "bond", itoa(DisputeBond))
}

// VetoProposal lets the owner send a proposal it believes wrong to the
// arbiter, inside the window. No bond; if the arbiter never rules,
// RefundExpired refunds every stake rather than honouring the vetoed proposal.
func VetoProposal(cur realm, id int64) {
	assertOwner(cur)
	m := getMarket(id)
	if m.State != StProposed {
		panic("NotProposed")
	}
	if now() >= m.ProposedAt+disputeWindow {
		panic("WindowClosed")
	}
	m.State = StDisputed
	m.DisputedAt = now()
	emit("ResolutionDisputed", "id", itoa(id), "disputer", "", "bond", "0")
}

// Finalize settles an undisputed proposal once the window has closed. Anyone may call it.
func Finalize(cur realm, id int64) {
	assertNotPaused()
	m := getMarket(id)
	if m.State != StProposed {
		panic("NotProposed")
	}
	if now() < m.ProposedAt+disputeWindow {
		panic("WindowOpen")
	}
	settle(m, m.Proposed, m.Summary, m.EvidenceHash)
}

// ResolveDispute is the arbiter's final word on a disputed market.
func ResolveDispute(cur realm, id int64, outcome int, summary, evidenceHash string) {
	m := getMarket(id)
	resolveDispute(cur, m, outcome, summary, evidenceHash, m.SettlementCutoff)
}

func ResolveDisputeWithCutoff(cur realm, id int64, outcome int, summary, evidenceHash string, cutoff int64) {
	resolveDispute(cur, getMarket(id), outcome, summary, evidenceHash, cutoff)
}

func resolveDispute(cur realm, m *Market, outcome int, summary, evidenceHash string, cutoff int64) {
	assertNotPaused()
	roles.AssertArbiter(caller(cur))
	if m.State != StDisputed {
		panic("NotDisputed")
	}
	if now() >= refundAt(m) {
		panic("GraceOver")
	}
	validOutcome(outcome)
	validHash(evidenceHash)
	disputerRight := outcome != m.Proposed || cutoff != m.SettlementCutoff
	setCutoff(m, cutoff)
	emit("DisputeResolved", "id", itoa(m.ID), "outcome", itoa(int64(outcome)), "disputerRight", boolStr(disputerRight))
	// Settled before the bond moves.
	settle(m, outcome, summary, evidenceHash)
	settleBond(cur, m, disputerRight)
}

// RefundExpired is the escape hatch, open to anyone once the grace has passed.
// A market the oracle never resolved is refunded in full; a dispute the
// arbiter never ruled on settles to the oracle's proposal and the bond is
// forfeited, so a cheap dispute cannot turn a loss into a free refund. A
// vetoed proposal, or any proposal while paused, refunds instead.
func RefundExpired(cur realm, id int64) {
	m := getMarket(id)
	disputed := m.State == StDisputed
	if !disputed && m.State != StOpen && !(roles.Paused && m.State == StProposed) {
		panic("NotOpen")
	}
	if now() < refundAt(m) {
		panic("GraceNotOver")
	}
	switch {
	case disputed && !roles.Paused && m.Disputer != "":
		emit("DisputeResolved", "id", itoa(id), "outcome", itoa(int64(m.Proposed)), "disputerRight", "false")
		settle(m, m.Proposed, m.Summary, m.EvidenceHash)
		settleBond(cur, m, false)
	case disputed:
		emit("DisputeResolved", "id", itoa(id), "outcome", itoa(Unresolvable), "disputerRight", "true")
		settle(m, Unresolvable, "Refunded: vetoed or paused", "")
		settleBond(cur, m, true)
	default:
		emit("MarketExpiredRefund", "id", itoa(id), "caller", caller(cur).String())
		settle(m, Unresolvable, "Refunded: not resolved within the grace period", "")
	}
}

func settle(m *Market, outcome int, summary, evidenceHash string) {
	m.State = StResolved
	m.Outcome = outcome
	m.Summary = summary
	m.EvidenceHash = evidenceHash
	emit("MarketResolved", "id", itoa(m.ID), "outcome", itoa(int64(outcome)), "summary", summary, "evidenceHash", evidenceHash)
}

func settleBond(cur realm, m *Market, returnIt bool) {
	bond := m.Bond
	if bond == 0 {
		return
	}
	m.Bond = 0
	if returnIt {
		push(cur, m.Disputer, bond)
	} else {
		accrue(m.ID, roles.FeeRecipient, bond)
	}
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

