		kv("lifetimeFeesAccrued", itoa(lifetimeFeesAccrued)),
		kv("lifetimeFeesClaimed", itoa(lifetimeFeesClaimed)),
		kv("now", itoa(now())),
	}, ",") + "}"
}

func ClaimJSON(id int64) string { return claimJSON(getClaim(id)) }

// ClaimsJSON lists claims newest first: `offset` skips that many from the newest.
func ClaimsJSON(offset, limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	if offset < 0 {
		offset = 0
	}
	var out []string
	claims.ReverseIterateByOffset(offset, limit, func(_ string, v any) bool {
		out = append(out, claimJSON(v.(*Claim)))
		return false
	})
	return "[" + strings.Join(out, ",") + "]"
}

// ChallengersJSON lists a claim's challengers in the order they joined.
func ChallengersJSON(id int64) string {
	c := getClaim(id)
	out := make([]string, 0, len(c.challengers))
	for _, ch := range c.challengers {
		out = append(out, "{"+strings.Join([]string{
			kv("address", mimir.Quote(ch.Addr.String())),
			kv("stake", itoa(ch.Stake)),
			kv("at", itoa(ch.At)),
			kv("referrer", mimir.Quote(ch.Referrer.String())),
		}, ",")+"}")
	}
	return "[" + strings.Join(out, ",") + "]"
}

func claimJSON(c *Claim) string {
	ea, eb := eligibleTotals(c)
	p := c.Proposal
	return "{" + strings.Join([]string{
		kv("id", itoa(c.ID)),
		kv("creator", mimir.Quote(c.Creator.String())),
		kv("question", mimir.Quote(c.Question)),
		kv("creatorPosition", mimir.Quote(c.CreatorPosition)),
		kv("counterPosition", mimir.Quote(c.CounterPosition)),
		kv("resolutionUrl", mimir.Quote(c.ResolutionURL)),
		kv("creatorStake", itoa(c.CreatorStake)),
		kv("totalChallengerStake", itoa(c.TotalChallengerStake)),
		kv("reservedCreatorLiability", itoa(c.ReservedCreatorLiability)),
		kv("eligibleCreator", itoa(ea)),
		kv("eligibleChallengers", itoa(eb)),
		kv("deadline", itoa(c.Deadline)),
		kv("state", itoa(int64(c.State))),
		kv("winnerSide", itoa(int64(c.WinnerSide))),
		kv("resolutionSummary", mimir.Quote(c.ResolutionSummary)),
		kv("confidence", itoa(int64(c.Confidence))),
		kv("category", mimir.Quote(c.Category)),
		kv("parentId", itoa(c.ParentID)),
		kv("challengerCount", itoa(int64(len(c.challengers)))),
		kv("createdAt", itoa(c.CreatedAt)),
		kv("marketType", mimir.Quote(c.MarketType)),
		kv("oddsMode", mimir.Quote(c.OddsMode)),
		kv("challengerPayoutBps", itoa(c.ChallengerPayoutBps)),
		kv("handicapLine", mimir.Quote(c.HandicapLine)),
		kv("settlementRule", mimir.Quote(c.SettlementRule)),
		kv("maxChallengers", itoa(int64(c.MaxChallengers))),
		kv("isPrivate", boolStr(c.IsPrivate)),
		kv("evidenceHash", mimir.Quote(c.EvidenceHash)),
		kv("referrer", mimir.Quote(c.Referrer.String())),
		kv("entryFees", itoa(c.EntryFees)),
		kv("settlementCutoff", itoa(c.SettlementCutoff)),
		kv("lockAt", itoa(c.LockAt)),
		kv("proposal", "{"+strings.Join([]string{
			kv("winnerSide", itoa(int64(p.WinnerSide))),
			kv("confidence", itoa(int64(p.Confidence))),
			kv("proposedAt", itoa(p.ProposedAt)),
			kv("disputedAt", itoa(p.DisputedAt)),
			kv("disputer", mimir.Quote(p.Disputer.String())),
			kv("bond", itoa(p.Bond)),
			kv("evidenceHash", mimir.Quote(p.EvidenceHash)),
			kv("summary", mimir.Quote(p.Summary)),
		}, ",")+"}"),
	}, ",") + "}"
}

func kv(k, v string) string { return mimir.Quote(k) + ":" + v }

// Package vs is Mimir's VS (duel) market, settled by an AI oracle: the
// gno.land port of contracts/MimirV3Erc20.sol. Stakes are mUSD.
//
// A creator opens a claim with a stake on their position. Challengers take the
// other side, each once, up to the claim's maxChallengers (at most 100):
//   - pool odds: challengers share the creator's stake pro rata, and together
//     may stake at most MaxPoolMultiple times the creator's stake;
//   - fixed odds: each challenger is paid challengerPayoutBps of their stake
//     (2x by default, at most 10x), and the creator's unreserved stake must
//     cover every challenger's profit when they join.
//
// After the deadline the oracle proposes CREATOR, CHALLENGERS, DRAW or
// UNRESOLVABLE with a confidence and the hash of its evidence. A participant
// may dispute within the dispute window by posting DisputeBond; the arbiter
// rules. An undisputed proposal is finalized by anyone. Settlement pays every
// participant in the same transaction. Draws, unresolvable questions and
// claims nobody challenged before the cutoff refund every stake.
//
// Fees: an entry fee on every stake that opens or joins a claim
// (fees.EntryBps, 0.5% by default), kept on refunds. No fee on winnings,
// except copy trades: ReferrerFeeBps of the profit to the referrer and
// CopyFeeBps to the platform.
//
// Private claims: only wallets the creator invites may challenge. Market data
// and transactions stay public.
//
// Differences from the EVM contract come from the transport, as in the pool
// realm: mUSD with an approve in the same transaction (no permit variants),
// payouts sent directly (mUSD cannot refuse or re-enter), block-time seconds.
// SetInvited takes a comma-separated address list.
package vs

import (
	"chain"
	"chain/runtime"
	"strconv"
	"time"

	mimir "gno.land/p/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/mimir"
	"gno.land/p/nt/avl/v0"
	"gno.land/r/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/fees"
	"gno.land/r/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/musd"
)

// Claim states.
const (
	StOpen      = 0
	StActive    = 1
	StResolved  = 2
	StCancelled = 3
	StProposed  = 4 // the oracle has proposed a verdict; disputable until the window closes
	StDisputed  = 5 // a participant disputed; the arbiter decides
)

// Winner sides.
const (
	SideNone         = 0
	SideCreator      = 1
	SideChallengers  = 2
	SideDraw         = 3
	SideUnresolvable = 4
)

const (
	MaxChallengers  = 100
	MaxPoolMultiple = int64(5)
	// MinStake is the smallest gross stake that opens or joins a claim: 0.1 mUSD.
	MinStake         = int64(100_000)
	DisputeBond      = int64(2_000_000)
	DefaultPayoutBps = int64(20_000) // 2x
	// Fixed odds pay at most 10x.
	MaxPayoutBps     = int64(100_000)
	MaxDeadlineAhead = int64(365 * 24 * 60 * 60)
	MaxEntryBps      = int64(100)
	// Anti-sniping: no new challenges in the final seconds before the deadline.
	ChallengeLockSeconds   = int64(60)
	ReferrerFeeBps         = int64(100)
	CopyFeeBps             = int64(100)
	ResolutionGraceSeconds = int64(7 * 24 * 60 * 60)
	MinLiveDisputeWindow   = int64(24 * 60 * 60)
	TestnetDisputeWindow   = int64(10 * 60)
)

const (
	Deployer       = address("g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz")
	InitialOracle  = address("g18pnec3atge4msr5hhanm790tljtdyd87s0wguh")
	InitialArbiter = address("g1af78r3tuv84mf3cd0kxrssmw6g2v2mvvc6phpv")
)

type Challenger struct {
	Addr     address
	Stake    int64 // net
	At       int64
	Referrer address
}

type Proposal struct {
	WinnerSide   int
	Confidence   int
	ProposedAt   int64
	DisputedAt   int64
	Disputer     address
	Bond         int64
	EvidenceHash string
	Summary      string
}

type Claim struct {
	ID                       int64
	Creator                  address
	Question                 string
	CreatorPosition          string
	CounterPosition          string
	ResolutionURL            string
	CreatorStake             int64
	TotalChallengerStake     int64
	ReservedCreatorLiability int64
	Deadline                 int64
	State                    int
	WinnerSide               int
	ResolutionSummary        string
	Confidence               int
	Category                 string
	ParentID                 int64
	CreatedAt                int64
	MarketType               string // binary | moneyline | spread | total | prop | custom
	OddsMode                 string // pool | fixed
	ChallengerPayoutBps      int64  // fixed odds, e.g. 20000 = 2x
	HandicapLine             string
	SettlementRule           string
	MaxChallengers           int
	IsPrivate                bool
	EvidenceHash             string
	Referrer                 address // the creator's referrer
	EntryFees                int64
	SettlementCutoff         int64
	LockAt                   int64
	Proposal                 Proposal

	challengers []*Challenger
	joined      avl.Tree // address -> true
	invited     avl.Tree // address -> bool
}

var (
	claims        avl.Tree // padded id -> *Claim
	claimCount    int64
	totalResolved int64

	wins   avl.Tree // address -> int64
	losses avl.Tree

	accruedFees         avl.Tree // address -> int64
	lifetimeFeesAccrued int64
	lifetimeFeesClaimed int64

	roles         *mimir.Roles
	disputeWindow int64
)

func init(cur realm) {
	roles = mimir.NewRoles(Deployer, InitialArbiter, InitialOracle, Deployer)
	disputeWindow = TestnetDisputeWindow
	if runtime.ChainID() == "gnoland-1" {
		disputeWindow = MinLiveDisputeWindow
	}
}

func now() int64                       { return time.Now().Unix() }
func emit(typ string, attrs ...string) { chain.Emit(typ, attrs...) }
func itoa(n int64) string              { return strconv.FormatInt(n, 10) }
func caller(cur realm) address         { return cur.Previous().Address() }

func key(id int64) string {
	s := itoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func getClaim(id int64) *Claim {
	v := claims.Get(key(id))
	if v == nil {
		panic("ClaimNotFound")
	}
	return v.(*Claim)
}

func (c *Claim) hasJoined(a address) bool { return c.joined.Has(a.String()) }

func (c *Claim) isInvited(a address) bool {
	v := c.invited.Get(a.String())
	return v != nil && v.(bool)
}

func counter(t *avl.Tree, a address) int64 {
	if v := t.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

func bump(t *avl.Tree, a address) { t.Set(a.String(), counter(t, a)+1) }

func accrue(id int64, to address, amount int64) {
	accruedFees.Set(to.String(), mimir.Add(counter(&accruedFees, to), amount))
	lifetimeFeesAccrued = mimir.Add(lifetimeFeesAccrued, amount)
	emit("FeeAccrued", "id", itoa(id), "recipient", to.String(), "amount", itoa(amount))
}

func pull(cur realm, from address, amount int64) {
	musd.TransferFrom(cross(cur), from, cur.Address(), amount)
}

func push(cur realm, to address, amount int64) {
	if amount == 0 {
		return
	}
	musd.Transfer(cross(cur), to, amount)
}

// takeEntry pulls `amount` from the caller, keeps the caller's entry fee and
// returns the rest: the stake that is recorded and can be won or refunded.
func takeEntry(cur realm, c *Claim, user address, amount int64) int64 {
	pull(cur, user, amount)
	bps := fees.EntryBps(user)
	if bps > MaxEntryBps {
		panic("EntryFeeTooHigh")
	}
	fee := mimir.MulDiv(amount, bps, 10_000)
	if fee != 0 {
		accrue(c.ID, roles.FeeRecipient, fee)
		c.EntryFees += fee
	}
	return amount - fee
}

func grossPayout(stake, bps int64) int64 { return mimir.MulDiv(stake, bps, 10_000) }

// payWinner pays a winner. Only a copy trade pays a fee on winnings:
// ReferrerFeeBps of the profit to the referrer and CopyFeeBps to the platform.
// Profit is gross - principal floored at zero, so a refund and a break-even
// win are free. Nobody pays themselves.
func payWinner(cur realm, id int64, to address, gross, principal int64, referrer address) (paid, taken int64) {
	profit := int64(0)
	if gross > principal {
		profit = gross - principal
	}
	if profit != 0 && referrer != "" && referrer != to {
		refFee := mimir.MulDiv(profit, ReferrerFeeBps, 10_000)
		if refFee != 0 {
			accrue(id, referrer, refFee)
		}
		copyFee := int64(0)
		if roles.FeeRecipient != to {
			copyFee = mimir.MulDiv(profit, CopyFeeBps, 10_000)
		}
		if copyFee != 0 {
			accrue(id, roles.FeeRecipient, copyFee)
		}
		taken = refFee + copyFee
	}
	paid = gross - taken
	push(cur, to, paid)
	return paid, taken
}

// Package agentpay pays a Mimir agent for one Mimir API call in mUSD: the
// gno.land port of contracts/MimirAgentPay.sol.
//
// The caller asks Mimir for a quote (GET /api/launch/:id/call), which names
// the agent's wallet, the price, a fresh `secret` and
// callId = hex(sha256(secret)). It approves this realm on mUSD and calls Pay
// in the same transaction, then sends the transaction hash and the secret to
// Mimir in `X-Mimir-Payment: gno:<tx>:<secret>`. Mimir reads the Paid event
// and counts it only if its callId is the hash of that secret, so a
// transaction seen on chain is useless to anyone without the secret.
//
// Non-custodial: mUSD moves from the payer straight to the agent in the same
// call; this realm never holds funds, takes no fee and has no owner. The only
// state is the call ids each payer has used, so a quote is paid once. Ids are
// kept per payer, so nobody can spend someone else's pending id first.
package agentpay

import (
	"chain"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz/musd"
)

// used: payer + "/" + callId -> true
var used avl.Tree

func Pay(cur realm, agent address, amount int64, callID string) {
	payer := cur.Previous().Address()
	if !agent.IsValid() {
		panic("ZeroAddress")
	}
	if agent == cur.Address() {
		panic("BadAgent")
	}
	if amount <= 0 {
		panic("ZeroAmount")
	}
	if !isHash(callID) {
		panic("BadCallId")
	}
	k := payer.String() + "/" + callID
	if used.Has(k) {
		panic("CallIdUsed")
	}
	used.Set(k, true)
	musd.TransferFrom(cross(cur), payer, agent, amount)
	chain.Emit("Paid", "callId", callID, "agent", agent.String(), "payer", payer.String(),
		"amount", strconv.FormatInt(amount, 10))
}

// Used reports whether payer has already paid for callID.
func Used(payer address, callID string) bool { return used.Has(payer.String() + "/" + callID) }

// isHash accepts a lowercase hex sha256 digest, never the zero hash.
func isHash(s string) bool {
	if len(s) != 64 {
		return false
	}
	zero := true
	for _, c := range s {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
		if c != '0' {
			zero = false
		}
	}
	return !zero
}

func Render(path string) string {
	return "# Mimir agent pay\n\nPays a Mimir agent for one API call in mUSD, straight from the payer to the agent. " +
		"No custody, no fee, no owner. Each call id is paid once per payer.\n"
}

// Package escrow is the pure escrow state machine behind Tavern Quests.
//
// It is a stateless library: it owns the quest record type and every rule
// for how a quest may move through its lifecycle, but it holds no chain
// state and moves no coins. The Tavern Quests realm (gno.land/r/nym-tavern777/quests)
// stores the records, verifies payments, and performs the actual coin
// transfers; every authorization and transition decision is delegated here
// so the rules can be unit-tested in isolation and reused by other realms.
//
// Lifecycle:
//
//	Open --Claim(claimer != poster)--> Claimed
//	Open --Cancel(poster)--> Cancelled            (escrow refunded by realm)
//	Claimed --Submit(claimant)--> Submitted
//	Submitted --Approve(poster)--> Completed      (escrow released by realm)
//	Submitted --Reject(poster)--> Claimed         (submission cleared, retry)
//
// Every transition validates first and mutates only on success, so a
// rejected transition never leaves partial state behind.
package escrow

import (
	"errors"
	"strings"
)

// Status is the lifecycle state of a quest.
type Status int

const (
	Open Status = iota
	Claimed
	Submitted
	Completed
	Cancelled
)

// String returns the lowercase board label for the status.
func (s Status) String() string {
	switch s {
	case Open:
		return "open"
	case Claimed:
		return "claimed"
	case Submitted:
		return "submitted"
	case Completed:
		return "completed"
	case Cancelled:
		return "cancelled"
	}
	return "unknown"
}

// Quest is a single escrowed task on the board. Reward is denominated in
// ugnot and is held by the hosting realm between posting and payout/refund.
type Quest struct {
	ID          int64
	Poster      address
	Claimant    address
	Title       string
	Description string
	Reward      int64 // ugnot
	Status      Status
	Submission  string // claimant's delivery note / proof reference
}

// ValidateNew checks the fields of a quest that is about to be posted.
// reward is the ugnot amount the poster actually sent, verified by the
// realm against the transaction before calling this.
func ValidateNew(title, description string, reward int64) error {
	if strings.TrimSpace(title) == "" {
		return errors.New("title must not be empty")
	}
	if len(title) > 140 {
		return errors.New("title too long (max 140 chars)")
	}
	if len(description) > 2048 {
		return errors.New("description too long (max 2048 chars)")
	}
	if reward <= 0 {
		return errors.New("reward must be a positive ugnot amount")
	}
	return nil
}

// Claim moves an Open quest to Claimed for actor. The poster cannot claim
// their own quest, and a quest can have only one claimant.
func Claim(q *Quest, actor address) error {
	if q.Status != Open {
		return errors.New("quest is not open")
	}
	if actor == q.Poster {
		return errors.New("poster cannot claim their own quest")
	}
	q.Claimant = actor
	q.Status = Claimed
	return nil
}

// Submit records the claimant's delivery note and moves a Claimed quest
// to Submitted.
func Submit(q *Quest, actor address, note string) error {
	if q.Status != Claimed {
		return errors.New("quest is not in claimed state")
	}
	if actor != q.Claimant {
		return errors.New("only the claimant can submit work")
	}
	if strings.TrimSpace(note) == "" {
		return errors.New("submission note must not be empty")
	}
	if len(note) > 1024 {
		return errors.New("submission note too long (max 1024 chars)")
	}
	q.Submission = note
	q.Status = Submitted
	return nil
}

// Approve marks a Submitted quest Completed. The hosting realm releases
// the escrowed reward to the claimant when this succeeds.
func Approve(q *Quest, actor address) error {
	if q.Status != Submitted {
		return errors.New("quest is not in submitted state")
	}
	if actor != q.Poster {
		return errors.New("only the poster can approve")
	}
	q.Status = Completed
	return nil
}

// Reject sends a Submitted quest back to Claimed, clearing the delivery
// note so the claimant can fix and resubmit.
func Reject(q *Quest, actor address) error {
	if q.Status != Submitted {
		return errors.New("quest is not in submitted state")
	}
	if actor != q.Poster {
		return errors.New("only the poster can reject")
	}
	q.Submission = ""
	q.Status = Claimed
	return nil
}

// Cancel closes an Open quest. The hosting realm refunds the escrowed
// reward to the poster when this succeeds. A quest that has been claimed
// can no longer be cancelled.
func Cancel(q *Quest, actor address) error {
	if q.Status != Open {
		return errors.New("only an open quest can be cancelled")
	}
	if actor != q.Poster {
		return errors.New("only the poster can cancel")
	}
	q.Status = Cancelled
	return nil
}

package escrow

import (
	"strings"
	"testing"
)

const (
	posterAddr   = address("g1wdjkuer9wgc47h6lta047h6lta047h6l56jtjc")
	claimerAddr  = address("g1wfjkx6tsd9jkuap3ta047h6lta047h6lkk20gv")
	strangerAddr = address("g1wfjkx6tsd9jkuapjta047h6lta047h6lducc3v")
)

func newQuest() *Quest {
	return &Quest{
		ID:          1,
		Poster:      posterAddr,
		Title:       "Write the tavern chronicle",
		Description: "A short history of the tavern, in markdown.",
		Reward:      1000,
		Status:      Open,
	}
}

func mustOK(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

func mustErr(t *testing.T, err error, want string) {
	t.Helper()
	if err == nil {
		t.Fatalf("expected error containing %q, got nil", want)
	}
	if !strings.Contains(err.Error(), want) {
		t.Fatalf("expected error containing %q, got %q", want, err.Error())
	}
}

func TestValidateNew(t *testing.T) {
	mustOK(t, ValidateNew("A quest", "details", 1))
	mustErr(t, ValidateNew("", "details", 1), "title must not be empty")
	mustErr(t, ValidateNew("   ", "details", 1), "title must not be empty")
	mustErr(t, ValidateNew("A quest", "details", 0), "reward must be a positive")
	mustErr(t, ValidateNew("A quest", "details", -5), "reward must be a positive")
}

func TestHappyPath(t *testing.T) {
	q := newQuest()

	mustOK(t, Claim(q, claimerAddr))
	if q.Status != Claimed || q.Claimant != claimerAddr {
		t.Fatalf("after claim: status=%v claimant=%v", q.Status, q.Claimant)
	}

	mustOK(t, Submit(q, claimerAddr, "delivered: ipfs://chronicle-v1"))
	if q.Status != Submitted || q.Submission == "" {
		t.Fatalf("after submit: status=%v submission=%q", q.Status, q.Submission)
	}

	mustOK(t, Approve(q, posterAddr))
	if q.Status != Completed {
		t.Fatalf("after approve: status=%v", q.Status)
	}
}

func TestRejectReopensForResubmit(t *testing.T) {
	q := newQuest()
	mustOK(t, Claim(q, claimerAddr))
	mustOK(t, Submit(q, claimerAddr, "first draft"))

	mustOK(t, Reject(q, posterAddr))
	if q.Status != Claimed {
		t.Fatalf("after reject: status=%v, want claimed", q.Status)
	}
	if q.Submission != "" {
		t.Fatalf("after reject: submission not cleared: %q", q.Submission)
	}

	mustOK(t, Submit(q, claimerAddr, "second draft"))
	mustOK(t, Approve(q, posterAddr))
	if q.Status != Completed {
		t.Fatalf("final status=%v, want completed", q.Status)
	}
}

func TestCancelOpen(t *testing.T) {
	q := newQuest()
	mustOK(t, Cancel(q, posterAddr))
	if q.Status != Cancelled {
		t.Fatalf("after cancel: status=%v", q.Status)
	}
}

func TestDoubleClaimRejected(t *testing.T) {
	q := newQuest()
	mustOK(t, Claim(q, claimerAddr))
	mustErr(t, Claim(q, strangerAddr), "quest is not open")
	if q.Claimant != claimerAddr {
		t.Fatalf("claimant changed after double claim: %v", q.Claimant)
	}
}

func TestPosterCannotClaimOwn(t *testing.T) {
	q := newQuest()
	mustErr(t, Claim(q, posterAddr), "poster cannot claim their own quest")
	if q.Status != Open {
		t.Fatalf("status changed after self-claim attempt: %v", q.Status)
	}
}

func TestWrongApproverRejected(t *testing.T) {
	q := newQuest()
	mustOK(t, Claim(q, claimerAddr))
	mustOK(t, Submit(q, claimerAddr, "done"))
	mustErr(t, Approve(q, claimerAddr), "only the poster can approve")
	mustErr(t, Approve(q, strangerAddr), "only the poster can approve")
	mustErr(t, Reject(q, claimerAddr), "only the poster can reject")
	if q.Status != Submitted {
		t.Fatalf("status changed after wrong-approver attempts: %v", q.Status)
	}
}

func TestCancelAfterClaimRejected(t *testing.T) {
	q := newQuest()
	mustOK(t, Claim(q, claimerAddr))
	mustErr(t, Cancel(q, posterAddr), "only an open quest can be cancelled")
	if q.Status != Claimed {
		t.Fatalf("status changed after cancel-after-claim: %v", q.Status)
	}
}

func TestSubmitRules(t *testing.T) {
	q := newQuest()
	mustErr(t, Submit(q, claimerAddr, "too early"), "quest is not in claimed state")
	mustOK(t, Claim(q, claimerAddr))
	mustErr(t, Submit(q, strangerAddr, "not mine"), "only the claimant can submit work")
	mustErr(t, Submit(q, claimerAddr, "  "), "submission note must not be empty")
}

func TestTerminalStatesAreFinal(t *testing.T) {
	q := newQuest()
	mustOK(t, Cancel(q, posterAddr))
	mustErr(t, Claim(q, claimerAddr), "quest is not open")
	mustErr(t, Cancel(q, posterAddr), "only an open quest can be cancelled")

	q2 := newQuest()
	mustOK(t, Claim(q2, claimerAddr))
	mustOK(t, Submit(q2, claimerAddr, "done"))
	mustOK(t, Approve(q2, posterAddr))
	mustErr(t, Approve(q2, posterAddr), "quest is not in submitted state")
	mustErr(t, Cancel(q2, posterAddr), "only an open quest can be cancelled")
}

package cutpurse

import (
	"chain"
	"chain/banker"
)

// CreateJob opens a job and seats the creator (seat 0).
func CreateJob(cur realm, name string, fee int64) int64 {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	if _, busy := active[who]; busy {
		panic(ErrSameJob)
	}
	if liveCount >= LiveJobsMax {
		panic(ErrTooManyLive)
	}
	if fee < 0 {
		panic(ErrBadFee)
	}

	f := clampFee(fee)
	nm := cleanName(name)
	height := mustHeight()

	payIn(cur, f)

	id := nextID
	nextID++

	j := &Job{
		ID:       id,
		Name:     nm,
		Creator:  who,
		Fee:      f,
		Pot:      f,
		Phase:    PhaseOpen,
		Deadline: height + JoinBlocks,
		Traitor:  -1,
		OpenedAt: height,
	}
	j.Seats[0] = Seat{Addr: who}
	j.NSeats = 1

	jobs[id] = j
	active[who] = id
	liveCount++

	return id
}

// JoinJob seats the caller in an open job.
func JoinJob(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)

	if j.Phase != PhaseOpen {
		panic(ErrBadPhase)
	}
	if mustHeight() > j.Deadline {
		panic(ErrDeadlinePassed)
	}
	if j.NSeats >= Seats {
		panic(ErrFull)
	}
	if seatOf(j, who) >= 0 {
		panic(ErrAlreadySeated)
	}
	if _, busy := active[who]; busy {
		panic(ErrSameJob)
	}
	if j.Pot+j.Fee > int64(MaxFee*Seats) {
		panic(ErrPotCap)
	}

	payIn(cur, j.Fee)

	j.Seats[j.NSeats] = Seat{Addr: who}
	j.NSeats++
	j.Pot += j.Fee
	active[who] = id
}

// Kick drops a seat during Open and refunds that seat's fee (creator only).
func Kick(cur realm, id int64, seat int8) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)

	if j.Creator != who {
		panic(ErrNotCreator)
	}
	if j.Phase != PhaseOpen {
		panic(ErrBadPhase)
	}
	if seat < 0 || int(seat) >= int(j.NSeats) {
		panic(ErrNotSeated)
	}

	idx := int(seat)
	kicked := j.Seats[idx]
	for i := idx; i < int(j.NSeats)-1; i++ {
		j.Seats[i] = j.Seats[i+1]
	}
	j.Seats[j.NSeats-1] = Seat{}
	j.NSeats--
	j.Pot -= j.Fee
	delete(active, kicked.Addr)

	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), kicked.Addr, chain.NewCoins(chain.NewCoin(Denom, j.Fee)))
}

// Start moves an open job into round 1 (creator only).
func Start(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	j := mustJob(id)

	if j.Creator != here(cur) {
		panic(ErrNotCreator)
	}
	if j.Phase != PhaseOpen {
		panic(ErrBadPhase)
	}
	if j.NSeats < 2 {
		panic(ErrNotReady)
	}

	j.Phase = PhaseCommit
	j.Round = 1
	j.Deadline = mustHeight() + CommitBlocks
}

// Commit stores the caller's sealed choice hash for the current round.
func Commit(cur realm, id int64, hash string) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)
	idx := seatOf(j, who)

	if idx < 0 {
		panic(ErrNotSeated)
	}
	if j.Phase != PhaseCommit {
		panic(ErrBadPhase)
	}
	if mustHeight() > j.Deadline {
		panic(ErrDeadlinePassed)
	}
	if j.Seats[idx].Committed {
		panic(ErrAlreadyComitted)
	}
	if !isHex64(hash) {
		panic(ErrBadHash)
	}

	j.Seats[idx].Committed = true
	j.Seats[idx].CommitHash = hash

	if countCommitted(j) == int(j.NSeats) {
		closeCommitRound(j)
	}
}

// Reveal opens the caller's sealed choice and applies nothing yet.
func Reveal(cur realm, id int64, action uint8, salt string) {
	if !cur.IsCurrent() {
		panic(ErrSpoofed)
	}
	who := here(cur)
	j := mustJob(id)
	idx := seatOf(j, who)

	if idx < 0 {
		panic(ErrNotSeated)
	}
	if j.Phase != PhaseReveal {
		panic(ErrBadPhase)
	}
	if mustHeight() > j.Deadline {
		panic(ErrDeadlinePassed)
	}
	if j.Seats[idx].Action != ActNone {
		panic(ErrAlreadyComitted)
	}
	if !j.Seats[idx].Committed {
		// §8: an uncommitted reveal is a hash mismatch, not a readiness error
		panic(ErrHashMismatch)
	}
	if action < uint8(ActScout) || action > uint8(ActWatch) {
		panic(ErrBadAction)
	}
	if !validSalt(salt) {
		panic(ErrBadSalt)
	}
	if commitHash(j.ID, action, salt, who.String(), j.Round) != j.Seats[idx].CommitHash {
		panic(ErrHashMismatch)
	}

	j.Seats[idx].Action = Action(action)
	j.Seats[idx].Auto = false

	if countRevealed(j) == int(j.NSeats) {
		closeRevealRound(j, false)
	}
}

package cutpurse

import (
	"chain"
	"strings"
	"testing"
)

// Guard coverage note (§10 R3).
//
// A crossing call must be written `f(cur)` or `f(cross(rlm))`, and cross()
// validates the realm pointer before the body runs — so an outside caller can
// never hand a mutator a bad realm. The `if !cur.IsCurrent()` guard therefore
// protects against *stale captures* inside the realm (the case the banker
// stdlib docs warn about). What is assertable here is the predicate plus the
// fact that the live-cur path clears every mutator.

func TestStaleRealmIsNotCurrent(cur realm, t *testing.T) {
	if !cur.IsCurrent() {
		t.Fatal("the injected cur must be current")
	}
	if cur.Previous().IsCurrent() {
		t.Fatal("a previous realm must not report IsCurrent")
	}
}

func TestMutatorsRunOnLiveCur(cur realm, t *testing.T) {
	testing.SetHeight(700)
	actor := address("g1guard")
	testing.SetOriginCaller(actor)
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(Denom, MinFee)))

	id := CreateJob(cur, "guard", MinFee)
	if _, ok := jobView(id); !ok {
		t.Fatal("CreateJob must work on the live cur")
	}

	testing.SetOriginCaller(address("g1guard2"))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(Denom, MinFee)))
	JoinJob(cur, id)

	testing.SetOriginCaller(actor)
	testing.SetOriginSend(chain.NewCoins())
	Start(cur, id)
	Tick(cur, id) // inside the commit deadline: no-op, must not panic

	jv, _ := jobView(id)
	if jv.Phase != uint8(PhaseCommit) || jv.NSeats != 2 {
		t.Fatalf("expected an open commit round with 2 seats, got phase %d nseats %d", jv.Phase, jv.NSeats)
	}
}

// seed() fills the globals directly (no caller realm needed) so render probes
// can address a realistic board. Idempotent.
func seed() {
	if len(jobs) > 0 {
		return
	}
	hostile := "a|b *c* _d_ `e` <gno-x> [f](g) " + strings.Repeat("z", 30)
	who0 := address("g1qrmldr7hh985wngaklzfkzlt588z4gewtlgwg0")
	other := address("g1seedother")

	for i := int64(0); i < 9; i++ {
		j := &Job{
			ID:       i,
			Name:     hostile,
			Creator:  who0,
			Fee:      MinFee,
			Pot:      MinFee * 4,
			Phase:    PhaseCommit,
			Round:    2,
			Deadline: 900,
			Alarm:    i % 4,
			Loot:     12,
			Secured:  4,
			Traitor:  1,
			OpenedAt: 100,
		}
		j.NSeats = 4
		for s := 0; s < 4; s++ {
			j.Seats[s] = Seat{Addr: who0, Committed: true, CommitHash: hostile}
			if s%2 == 1 {
				j.Seats[s].Addr = other
				j.Seats[s].Action = Action(1 + s%4)
				j.Seats[s].Contribution = 3
			}
		}
		jobs[i] = j
		active[j.Seats[0].Addr] = i
	}
	nextID = 9
	liveCount = 9
}

