// Distinct throwaway test addresses per test: the test banker persists
// across tests in a run, so reusing addresses would leak balances.
//
// NOTE on style: testing.SetRealm / SetOriginSend and every cross(cur)
// call are written inline in each test body, mirroring the upstream
// atomicswap tests — the realm value must be the test's own `cur`,
// mutated in place by SetRealm; routing it through a helper function
// breaks the user-call context that PostQuest verifies.
const (
	alice   = address("g1wdjkuer9wgc47h6lta047h6lta047h6l56jtjc")
	bob     = address("g1wfjkx6tsd9jkuap3ta047h6lta047h6lkk20gv")
	carol   = address("g1wdjkuer9wge97h6lta047h6lta047h6ltfacad")
	dave    = address("g1wfjkx6tsd9jkuapjta047h6lta047h6lducc3v")
	eve     = address("g1wdjkuer9wge47h6lta047h6lta047h6l5rk38l")
	frank   = address("g1wfjkx6tsd9jkuapnta047h6lta047h6ly6k4pv")
	grace   = address("g1v9kxjcm9ta047h6lta047h6lta047h6lzd40gh")
	heidi   = address("g1vfhkyh6lta047h6lta047h6lta047h6l03vdhu")
	ivan    = address("g1vd5xzunv09047h6lta047h6lta047h6lhsyveh")
	pkgPath = "gno.land/r/nym-tavern777/quests"
)

func resetState() {
	quests = nil
	counter = 0
}

func fundRealm(t *testing.T, amt int64) address {
	t.Helper()
	pkgAddr := chain.PackageAddress(pkgPath)
	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: denom, Amount: amt}})
	return pkgAddr
}

func balance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, denom)
}

// assertPanics asserts fn aborts (panics across the realm boundary) with
// a message containing want. Cross-realm aborts cannot be caught with
// recover(); the revive builtin captures the abort value instead.
func assertPanics(t *testing.T, want string, fn func()) {
	t.Helper()
	r := revive(fn)
	if r == nil {
		t.Fatalf("expected panic containing %q, got none", want)
	}
	var msg string
	switch v := r.(type) {
	case string:
		msg = v
	case error:
		msg = v.Error()
	default:
		t.Fatalf("expected panic containing %q, got non-string panic", want)
	}
	if !strings.Contains(msg, want) {
		t.Fatalf("expected panic containing %q, got %q", want, msg)
	}
}

func TestHappyPath(cur realm, t *testing.T) {
	defer resetState()
	pkgAddr := fundRealm(t, 100_000)
	realmBefore := balance(pkgAddr)

	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 1000}})
	id := PostQuest(cross(cur), "Write the tavern chronicle", "A short history of the tavern.")
	if id != 1 {
		t.Fatalf("first quest id = %d, want 1", id)
	}
	q := quests[0]
	if q.Status != escrow.Open || q.Poster != alice || q.Reward != 1000 {
		t.Fatalf("after post: status=%v poster=%v reward=%d", q.Status, q.Poster, q.Reward)
	}

	testing.SetRealm(testing.NewUserRealm(bob))
	ClaimQuest(cross(cur), id)
	if q.Status != escrow.Claimed || q.Claimant != bob {
		t.Fatalf("after claim: status=%v claimant=%v", q.Status, q.Claimant)
	}

	SubmitWork(cross(cur), id, "delivered: https://example.org/chronicle")
	if q.Status != escrow.Submitted {
		t.Fatalf("after submit: status=%v", q.Status)
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	ApproveQuest(cross(cur), id)
	if q.Status != escrow.Completed {
		t.Fatalf("after approve: status=%v", q.Status)
	}
	if got := balance(bob); got != 1000 {
		t.Fatalf("claimant balance = %d, want 1000 (escrow released)", got)
	}
	if got := balance(pkgAddr); got != realmBefore-1000 {
		t.Fatalf("realm balance = %d, want %d", got, realmBefore-1000)
	}

	board := Render("")
	if !strings.Contains(board, "Write the tavern chronicle") {
		t.Fatalf("board render missing quest title:\n%s", board)
	}
	detail := Render("1")
	if !strings.Contains(detail, "completed") {
		t.Fatalf("detail render missing status:\n%s", detail)
	}
}

func TestCancelRefundsPoster(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(carol))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 500}})
	id := PostQuest(cross(cur), "Sweep the tavern floor", "Broom provided.")
	CancelQuest(cross(cur), id) // carol is still the current user realm

	if quests[0].Status != escrow.Cancelled {
		t.Fatalf("after cancel: status=%v", quests[0].Status)
	}
	if got := balance(carol); got != 500 {
		t.Fatalf("poster balance = %d, want 500 (escrow refunded)", got)
	}
}

func TestDoubleClaimPanics(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(dave))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 700}})
	id := PostQuest(cross(cur), "Sharpen the tavern knives", "Careful, they bite.")

	testing.SetRealm(testing.NewUserRealm(eve))
	ClaimQuest(cross(cur), id)

	testing.SetRealm(testing.NewUserRealm(frank))
	assertPanics(t, "quest is not open", func() {
		ClaimQuest(cross(cur), id)
	})
	if quests[0].Claimant != eve {
		t.Fatalf("claimant changed after double claim: %v", quests[0].Claimant)
	}
}

func TestPosterSelfClaimPanics(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(grace))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 300}})
	id := PostQuest(cross(cur), "Brew the house ale", "One barrel, not too hoppy.")

	assertPanics(t, "poster cannot claim their own quest", func() {
		ClaimQuest(cross(cur), id)
	})
	if quests[0].Status != escrow.Open {
		t.Fatalf("status changed after self-claim attempt: %v", quests[0].Status)
	}
}

func TestWrongApproverPanics(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(heidi))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 900}})
	id := PostQuest(cross(cur), "Paint the tavern sign", "Gold leaf, purple background.")

	testing.SetRealm(testing.NewUserRealm(ivan))
	ClaimQuest(cross(cur), id)
	SubmitWork(cross(cur), id, "done: https://example.org/sign")

	// The claimant cannot approve their own work.
	assertPanics(t, "only the poster can approve", func() {
		ApproveQuest(cross(cur), id)
	})
	// Nor reject it.
	assertPanics(t, "only the poster can reject", func() {
		RejectQuest(cross(cur), id)
	})
	if quests[0].Status != escrow.Submitted {
		t.Fatalf("status changed after wrong-approver attempts: %v", quests[0].Status)
	}
	if got := balance(ivan); got != 0 {
		t.Fatalf("claimant paid out despite no approval: %d", got)
	}
}

func TestCancelAfterClaimPanics(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 400}})
	id := PostQuest(cross(cur), "Mend the tavern roof", "Mind the leak over the bar.")

	testing.SetRealm(testing.NewUserRealm(bob))
	ClaimQuest(cross(cur), id)

	testing.SetRealm(testing.NewUserRealm(alice))
	assertPanics(t, "only an open quest can be cancelled", func() {
		CancelQuest(cross(cur), id)
	})
	if quests[0].Status != escrow.Claimed {
		t.Fatalf("status changed after cancel-after-claim: %v", quests[0].Status)
	}
}

func TestPostQuestPaymentRules(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(carol))

	// No coins sent at all.
	testing.SetOriginSend(chain.Coins{})
	assertPanics(t, "send exactly "+denom, func() {
		PostQuest(cross(cur), "Free quest", "no reward")
	})

	// Wrong denom sent.
	testing.SetOriginSend(chain.Coins{{Denom: "uatom", Amount: 100}})
	assertPanics(t, "send exactly "+denom, func() {
		PostQuest(cross(cur), "Wrong coin quest", "paid in uatom")
	})

	if len(quests) != 0 {
		t.Fatalf("quests recorded despite bad payments: %d", len(quests))
	}
}

func TestRejectThenResubmit(cur realm, t *testing.T) {
	defer resetState()
	fundRealm(t, 100_000)

	testing.SetRealm(testing.NewUserRealm(dave))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 800}})
	id := PostQuest(cross(cur), "Catalog the wine cellar", "Every bottle, counted twice.")

	testing.SetRealm(testing.NewUserRealm(eve))
	ClaimQuest(cross(cur), id)
	SubmitWork(cross(cur), id, "v1: partial list")

	testing.SetRealm(testing.NewUserRealm(dave))
	RejectQuest(cross(cur), id)
	if quests[0].Status != escrow.Claimed {
		t.Fatalf("after reject: status=%v, want claimed", quests[0].Status)
	}

	testing.SetRealm(testing.NewUserRealm(eve))
	SubmitWork(cross(cur), id, "v2: complete list")

	testing.SetRealm(testing.NewUserRealm(dave))
	ApproveQuest(cross(cur), id)
	if got := balance(eve); got != 800 {
		t.Fatalf("claimant balance = %d, want 800", got)
	}
}

package hearthescrow

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	nextID        seqid.ID
	escrows       *avl.Tree // seqid.ID.String() -> *Escrow
	addressIndex  *avl.Tree // address.String() -> []uint64
	stats         Stats
	realmPkgPath  string
	realmLinkBase string
)

func init() {
	escrows = avl.NewTree()
	addressIndex = avl.NewTree()
	realmPkgPath = unsafe.CurrentRealm().PkgPath()
	if realmPkgPath == "" {
		realmPkgPath = "gno.land/r/g1x7ud67jym95qh9zf0swmq6ck07s3ly3lksxc5n/hearthescrow"
	}
	realmLinkBase = strings.TrimPrefix(realmPkgPath, runtime.ChainDomain())
	if realmLinkBase == "" {
		realmLinkBase = "/r/g1x7ud67jym95qh9zf0swmq6ck07s3ly3lksxc5n/hearthescrow"
	}
}

// CreateEscrow locks the attached ugnot deposit into a new milestone escrow.
// milestoneTitles and milestoneBps are comma-separated lists of equal length;
// basis points must each be positive and sum to exactly 10000 (100%).
// Pass an empty arbiter address ("") if no dispute arbiter is desired.
func CreateEscrow(
	cur realm,
	title string,
	recipient address,
	arbiter address,
	deadlineHeight int64,
	milestoneTitles string,
	milestoneBps string,
) uint64 {
	if !cur.Previous().IsUserCall() {
		panic(ErrDirectUserCallRequired)
	}

	depositor := cur.Previous().Address()
	title = strings.TrimSpace(title)
	if len(title) == 0 || len(title) > MaxTitleLen {
		panic(ErrInvalidTitle)
	}
	if !recipient.IsValid() {
		panic(ErrInvalidRecipient)
	}
	if recipient == depositor {
		panic(ErrSelfEscrow)
	}
	if arbiter != "" {
		if !arbiter.IsValid() || arbiter == depositor || arbiter == recipient {
			panic(ErrInvalidArbiter)
		}
	}

	nowHeight := runtime.ChainHeight()
	if deadlineHeight <= nowHeight {
		panic(ErrInvalidDeadline)
	}

	milestones := parseMilestones(milestoneTitles, milestoneBps)

	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != DenomUGNOT || sent[0].Amount <= 0 {
		panic(ErrInvalidDeposit)
	}
	amount := sent[0].Amount
	if amount > MaxEscrowAmount {
		panic(ErrDepositTooLarge)
	}

	realmAddr := cur.Address()
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if b.GetCoin(realmAddr, DenomUGNOT) < stats.TotalLocked+amount {
		panic(ErrInsufficientRealmBalance)
	}

	id := uint64(nextID.Next())
	e := &Escrow{
		ID:             id,
		Title:          title,
		Depositor:      depositor,
		Recipient:      recipient,
		Arbiter:        arbiter,
		TotalAmount:    amount,
		CreatedHeight:  nowHeight,
		DeadlineHeight: deadlineHeight,
		Status:         StatusActive,
		Milestones:     milestones,
	}

	escrows.Set(seqid.ID(id).String(), e)
	indexAddress(depositor, id)
	indexAddress(recipient, id)
	if arbiter != "" {
		indexAddress(arbiter, id)
	}

	stats.TotalEscrows++
	stats.ActiveCount++
	stats.TotalLocked += amount

	chain.Emit(
		"EscrowCreated",
		"id", strconv.FormatUint(id, 10),
		"depositor", depositor.String(),
		"recipient", recipient.String(),
		"arbiter", arbiter.String(),
		"amount", strconv.FormatInt(amount, 10),
		"deadline", strconv.FormatInt(deadlineHeight, 10),
		"milestones", strconv.Itoa(len(milestones)),
	)

	return id
}

// SubmitMilestone lets the recipient submit a deliverable note or URI for a pending milestone.
func SubmitMilestone(cur realm, id uint64, milestoneIndex int, deliverable string) {
	e := mustGetEscrow(id)
	caller := cur.Previous().Address()
	if caller != e.Recipient {
		panic(ErrUnauthorized)
	}
	if e.Status != StatusActive {
		panic(ErrEscrowNotActive)
	}
	if milestoneIndex < 0 || milestoneIndex >= len(e.Milestones) {
		panic(ErrMilestoneOutOfRange)
	}

	deliverable = strings.TrimSpace(deliverable)
	if len(deliverable) == 0 || len(deliverable) > MaxDeliverable {
		panic(ErrInvalidDeliverable)
	}

	m := &e.Milestones[milestoneIndex]
	if m.Status != MilestonePending {
		panic(ErrMilestoneNotPending)
	}

	m.Status = MilestoneSubmitted
	m.Deliverable = deliverable
	m.SubmittedHeight = runtime.ChainHeight()

	chain.Emit(
		"MilestoneSubmitted",
		"id", strconv.FormatUint(id, 10),
		"milestone", strconv.Itoa(milestoneIndex),
		"recipient", caller.String(),
	)
}

// ApproveMilestone lets the depositor approve a milestone and release its ugnot tranche to the recipient.
// Approving the final unapproved milestone sweeps any integer-division remainder so zero dust is trapped.
func ApproveMilestone(cur realm, id uint64, milestoneIndex int) int64 {
	e := mustGetEscrow(id)
	caller := cur.Previous().Address()
	if caller != e.Depositor {
		panic(ErrUnauthorized)
	}
	if e.Status != StatusActive {
		panic(ErrEscrowNotActive)
	}
	if milestoneIndex < 0 || milestoneIndex >= len(e.Milestones) {
		panic(ErrMilestoneOutOfRange)
	}

	m := &e.Milestones[milestoneIndex]
	if m.Status == MilestoneApproved {
		panic(ErrMilestoneAlreadyApproved)
	}

	remaining := e.RemainingAmount()
	if remaining <= 0 {
		panic(ErrNothingToRelease)
	}

	unapprovedBefore := len(e.Milestones) - e.ApprovedCount()
	var payout int64
	if unapprovedBefore == 1 {
		payout = remaining
	} else {
		payout = (e.TotalAmount * m.Bps) / BasisPointsTotal
		if payout > remaining {
			payout = remaining
		}
	}

	nowHeight := runtime.ChainHeight()
	// Effects before interactions (CEI)
	m.Status = MilestoneApproved
	m.ApprovedHeight = nowHeight
	m.PaidAmount = payout
	e.ReleasedAmount += payout
	stats.TotalLocked -= payout
	stats.TotalReleased += payout

	completed := unapprovedBefore == 1
	if completed {
		e.Status = StatusCompleted
		e.ClosedHeight = nowHeight
		stats.ActiveCount--
		stats.CompletedCount++
	}

	chain.Emit(
		"MilestoneApproved",
		"id", strconv.FormatUint(id, 10),
		"milestone", strconv.Itoa(milestoneIndex),
		"payout", strconv.FormatInt(payout, 10),
		"recipient", e.Recipient.String(),
	)
	if completed {
		chain.Emit(
			"EscrowCompleted",
			"id", strconv.FormatUint(id, 10),
			"total_released", strconv.FormatInt(e.ReleasedAmount, 10),
		)
	}

	if payout > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(cur.Address(), e.Recipient, chain.NewCoins(chain.NewCoin(DenomUGNOT, payout)))
	}

	return payout
}

// OpenDispute freezes an active escrow for arbiter resolution. Either depositor or recipient may call it.
func OpenDispute(cur realm, id uint64, reason string) {
	e := mustGetEscrow(id)
	caller := cur.Previous().Address()
	if caller != e.Depositor && caller != e.Recipient {
		panic(ErrUnauthorized)
	}
	if e.Status != StatusActive {
		panic(ErrEscrowNotActive)
	}
	if e.Arbiter == "" {
		panic(ErrNoArbiter)
	}
	if e.RemainingAmount() <= 0 {
		panic(ErrNothingToRelease)
	}

	reason = strings.TrimSpace(reason)
	if len(reason) == 0 || len(reason) > MaxNoteLen {
		panic(ErrInvalidDisputeReason)
	}

	nowHeight := runtime.ChainHeight()
	e.Status = StatusDisputed
	e.Dispute = &DisputeRecord{
		OpenedBy:     caller,
		Reason:       reason,
		OpenedHeight: nowHeight,
	}
	stats.ActiveCount--
	stats.DisputedCount++

	chain.Emit(
		"DisputeOpened",
		"id", strconv.FormatUint(id, 10),
		"opened_by", caller.String(),
		"arbiter", e.Arbiter.String(),
	)
}

// ResolveDispute lets the designated arbiter split all remaining locked funds between
// recipient (recipientBps out of 10000) and depositor (the remainder).
func ResolveDispute(cur realm, id uint64, recipientBps int64, resolutionNote string) (int64, int64) {
	e := mustGetEscrow(id)
	caller := cur.Previous().Address()
	if e.Arbiter == "" || caller != e.Arbiter {
		panic(ErrUnauthorized)
	}
	if e.Status != StatusDisputed {
		panic(ErrEscrowNotDisputed)
	}
	if recipientBps < 0 || recipientBps > BasisPointsTotal {
		panic(ErrInvalidSplitBps)
	}

	resolutionNote = strings.TrimSpace(resolutionNote)
	if len(resolutionNote) > MaxNoteLen {
		panic(ErrInvalidResolutionNote)
	}

	remaining := e.RemainingAmount()
	if remaining <= 0 {
		panic(ErrNothingToRelease)
	}

	recipientShare := (remaining * recipientBps) / BasisPointsTotal
	depositorShare := remaining - recipientShare
	nowHeight := runtime.ChainHeight()

	// Effects before interactions (CEI)
	e.Status = StatusResolved
	e.ReleasedAmount += recipientShare
	e.RefundedAmount += depositorShare
	e.ClosedHeight = nowHeight
	if e.Dispute != nil {
		e.Dispute.ResolvedHeight = nowHeight
		e.Dispute.RecipientBps = recipientBps
		e.Dispute.RecipientPayout = recipientShare
		e.Dispute.DepositorRefund = depositorShare
		e.Dispute.ResolutionNote = resolutionNote
	}

	stats.TotalLocked -= remaining
	stats.TotalReleased += recipientShare
	stats.TotalRefunded += depositorShare
	stats.DisputedCount--
	stats.ResolvedCount++

	chain.Emit(
		"DisputeResolved",
		"id", strconv.FormatUint(id, 10),
		"arbiter", caller.String(),
		"recipient_bps", strconv.FormatInt(recipientBps, 10),
		"recipient_payout", strconv.FormatInt(recipientShare, 10),
		"depositor_refund", strconv.FormatInt(depositorShare, 10),
	)

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := cur.Address()
	if recipientShare > 0 {
		b.SendCoins(realmAddr, e.Recipient, chain.NewCoins(chain.NewCoin(DenomUGNOT, recipientShare)))
	}
	if depositorShare > 0 {
		b.SendCoins(realmAddr, e.Depositor, chain.NewCoins(chain.NewCoin(DenomUGNOT, depositorShare)))
	}

	return recipientShare, depositorShare
}

// ClaimRefund lets the depositor reclaim all remaining unapproved funds once deadlineHeight is reached.
// Cannot be called while a dispute is open.
func ClaimRefund(cur realm, id uint64) int64 {
	e := mustGetEscrow(id)
	caller := cur.Previous().Address()
	if caller != e.Depositor {
		panic(ErrUnauthorized)
	}
	if e.Status != StatusActive {
		panic(ErrEscrowNotActive)
	}
	if runtime.ChainHeight() < e.DeadlineHeight {
		panic(ErrDeadlineNotReached)
	}

	remaining := e.RemainingAmount()
	if remaining <= 0 {
		panic(ErrNothingToRelease)
	}

	nowHeight := runtime.ChainHeight()
	// Effects before interactions (CEI)
	e.Status = StatusRefunded
	e.RefundedAmount += remaining
	e.ClosedHeight = nowHeight
	stats.TotalLocked -= remaining
	stats.TotalRefunded += remaining
	stats.ActiveCount--
	stats.RefundedCount++

	chain.Emit(
		"RefundClaimed",
		"id", strconv.FormatUint(id, 10),
		"depositor", e.Depositor.String(),
		"refunded", strconv.FormatInt(remaining, 10),
	)

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), e.Depositor, chain.NewCoins(chain.NewCoin(DenomUGNOT, remaining)))

	return remaining
}

// GetEscrow returns a read-only copy of an escrow by ID, or nil if not found.
func GetEscrow(id uint64) *Escrow {
	raw := escrows.Get(seqid.ID(id).String())
	if raw == nil {
		return nil
	}
	src := raw.(*Escrow)
	cp := *src
	cp.Milestones = make([]Milestone, len(src.Milestones))
	copy(cp.Milestones, src.Milestones)
	if src.Dispute != nil {
		d := *src.Dispute
		cp.Dispute = &d
	}
	return &cp
}

// GetStats returns a snapshot of protocol-wide accounting and counts.
func GetStats() Stats {
	return stats
}

// GetAddressEscrowIDs returns a copy of escrow IDs associated with addr.
func GetAddressEscrowIDs(addr address) []uint64 {
	raw := addressIndex.Get(addr.String())
	if raw == nil {
		return nil
	}
	src := raw.([]uint64)
	out := make([]uint64, len(src))
	copy(out, src)
	return out
}

func mustGetEscrow(id uint64) *Escrow {
	raw := escrows.Get(seqid.ID(id).String())
	if raw == nil {
		panic(ErrEscrowNotFound)
	}
	return raw.(*Escrow)
}

func indexAddress(addr address, id uint64) {
	key := addr.String()
	var ids []uint64
	if raw := addressIndex.Get(key); raw != nil {
		ids = raw.([]uint64)
	}
	ids = append(ids, id)
	addressIndex.Set(key, ids)
}

func parseMilestones(titlesCSV string, bpsCSV string) []Milestone {
	rawTitles := strings.Split(titlesCSV, ",")
	rawBps := strings.Split(bpsCSV, ",")
	if len(rawTitles) == 0 || len(rawTitles) > MaxMilestones || len(rawTitles) != len(rawBps) {
		panic(ErrInvalidMilestones)
	}

	milestones := make([]Milestone, len(rawTitles))
	var sumBps int64
	for i := range rawTitles {
		t := strings.TrimSpace(rawTitles[i])
		if len(t) == 0 || len(t) > MaxMilestoneLen {
			panic(ErrInvalidMilestones)
		}
		b, err := strconv.ParseInt(strings.TrimSpace(rawBps[i]), 10, 64)
		if err != nil || b <= 0 || b > BasisPointsTotal {
			panic(ErrInvalidMilestones)
		}
		sumBps += b
		milestones[i] = Milestone{
			Index:  i,
			Title:  t,
			Bps:    b,
			Status: MilestonePending,
		}
	}

	if sumBps != BasisPointsTotal {
		panic(ErrInvalidMilestones)
	}

	return milestones
}

package hearthescrow

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const testPkgPath = "gno.land/r/g1x7ud67jym95qh9zf0swmq6ck07s3ly3lksxc5n/hearthescrow"

func resetState() {
	nextID = 0
	escrows = avl.NewTree()
	addressIndex = avl.NewTree()
	stats = Stats{}
}

func fundAndCreate(
	cur realm,
	depositor address,
	title string,
	recipient address,
	arbiter address,
	deadlineOffset int64,
	titles string,
	bps string,
	amount int64,
) uint64 {
	pkgAddr := chain.PackageAddress(testPkgPath)
	coins := chain.NewCoins(chain.NewCoin(DenomUGNOT, amount))
	testing.IssueCoins(pkgAddr, coins)
	testing.SetRealm(testing.NewUserRealm(depositor))
	testing.SetOriginSend(coins)
	deadline := runtime.ChainHeight() + deadlineOffset
	return CreateEscrow(cross(cur), title, recipient, arbiter, deadline, titles, bps)
}

func TestHappyPath_MultiMilestoneAndDustSweep(cur realm, t *testing.T) {
	defer resetState()

	depositor := testutils.TestAddress("dep_happy")
	recipient := testutils.TestAddress("rec_happy")
	arbiter := testutils.TestAddress("arb_happy")
	ro := banker.NewReadonlyBanker()
	recBefore := ro.GetCoin(recipient, DenomUGNOT)

	// 1,000,001 ugnot split 3333 / 3333 / 3334 bps tests rounding-dust sweep on final approval
	id := fundAndCreate(
		cur, depositor,
		"Tavern Website Build",
		recipient, arbiter, 100,
		"Wireframes,Frontend,Audit",
		"3333,3333,3334",
		1_000_001,
	)
	urequire.Equal(t, uint64(1), id)

	e := GetEscrow(id)
	urequire.True(t, e != nil)
	uassert.Equal(t, string(StatusActive), string(e.Status))
	uassert.Equal(t, int64(1_000_001), e.RemainingAmount())
	uassert.Equal(t, 3, len(e.Milestones))

	// Recipient submits milestone 0
	testing.SetRealm(testing.NewUserRealm(recipient))
	SubmitMilestone(cross(cur), id, 0, "https://example.com/wireframes")
	e = GetEscrow(id)
	uassert.Equal(t, string(MilestoneSubmitted), string(e.Milestones[0].Status))
	uassert.Equal(t, "https://example.com/wireframes", e.Milestones[0].Deliverable)

	// Depositor approves milestone 0
	testing.SetRealm(testing.NewUserRealm(depositor))
	p0 := ApproveMilestone(cross(cur), id, 0)
	uassert.Equal(t, int64(333_300), p0)

	// Out-of-order approval: approve milestone 2 directly without submission
	p2 := ApproveMilestone(cross(cur), id, 2)
	uassert.Equal(t, int64(333_400), p2)

	// Final unapproved milestone (index 1) must sweep the remaining 333,301 ugnot (zero dust trapped)
	p1 := ApproveMilestone(cross(cur), id, 1)
	uassert.Equal(t, int64(333_301), p1)
	uassert.Equal(t, int64(1_000_001), p0+p1+p2)

	e = GetEscrow(id)
	uassert.Equal(t, string(StatusCompleted), string(e.Status))
	uassert.Equal(t, int64(0), e.RemainingAmount())
	uassert.Equal(t, int64(1_000_001), e.ReleasedAmount)
	uassert.Equal(t, recBefore+1_000_001, ro.GetCoin(recipient, DenomUGNOT))

	st := GetStats()
	uassert.Equal(t, 1, st.TotalEscrows)
	uassert.Equal(t, 0, st.ActiveCount)
	uassert.Equal(t, 1, st.CompletedCount)
	uassert.Equal(t, int64(0), st.TotalLocked)
	uassert.Equal(t, int64(1_000_001), st.TotalReleased)

	// Double-approve or refund on completed escrow must abort
	uassert.AbortsWithMessage(t, cur, ErrEscrowNotActive.Error(), func() {
		ApproveMilestone(cross(cur), id, 0)
	})
	uassert.AbortsWithMessage(t, cur, ErrEscrowNotActive.Error(), func() {
		ClaimRefund(cross(cur), id)
	})
}

func TestDisputeAndArbiterSplit(cur realm, t *testing.T) {
	defer resetState()

	depositor := testutils.TestAddress("dep_disp")
	recipient := testutils.TestAddress("rec_disp")
	arbiter := testutils.TestAddress("arb_disp")
	outsider := testutils.TestAddress("out_disp")
	ro := banker.NewReadonlyBanker()

	id := fundAndCreate(
		cur, depositor,
		"Smart Contract Audit",
		recipient, arbiter, 100,
		"Draft Report,Final Report",
		"4000,6000",
		1_000_000,
	)

	// Approve milestone 0 (400,000 ugnot) first
	testing.SetRealm(testing.NewUserRealm(depositor))
	p0 := ApproveMilestone(cross(cur), id, 0)
	uassert.Equal(t, int64(400_000), p0)

	// Outsider cannot open dispute
	testing.SetRealm(testing.NewUserRealm(outsider))
	uassert.AbortsWithMessage(t, cur, ErrUnauthorized.Error(), func() {
		OpenDispute(cross(cur), id, "Not my escrow")
	})

	// Recipient opens dispute over the remaining 600,000 ugnot
	testing.SetRealm(testing.NewUserRealm(recipient))
	OpenDispute(cross(cur), id, "Final report delivered but depositor unresponsive")

	e := GetEscrow(id)
	uassert.Equal(t, string(StatusDisputed), string(e.Status))
	urequire.True(t, e.Dispute != nil)
	uassert.Equal(t, recipient, e.Dispute.OpenedBy)

	// Depositor cannot bypass open dispute with ClaimRefund even after deadline
	testing.SkipHeights(150)
	testing.SetRealm(testing.NewUserRealm(depositor))
	uassert.AbortsWithMessage(t, cur, ErrEscrowNotActive.Error(), func() {
		ClaimRefund(cross(cur), id)
	})

	// Non-arbiter cannot resolve dispute
	uassert.AbortsWithMessage(t, cur, ErrUnauthorized.Error(), func() {
		ResolveDispute(cross(cur), id, 0, "Depositor trying to self-resolve")
	})

	// Invalid split bps rejected
	testing.SetRealm(testing.NewUserRealm(arbiter))
	uassert.AbortsWithMessage(t, cur, ErrInvalidSplitBps.Error(), func() {
		ResolveDispute(cross(cur), id, 10_001, "Too high")
	})
	uassert.AbortsWithMessage(t, cur, ErrInvalidSplitBps.Error(), func() {
		ResolveDispute(cross(cur), id, -1, "Negative")
	})

	depBefore := ro.GetCoin(depositor, DenomUGNOT)
	recBefore := ro.GetCoin(recipient, DenomUGNOT)

	// Arbiter splits remaining 600,000 ugnot: 70% (420,000) to recipient, 30% (180,000) to depositor
	recPay, depRef := ResolveDispute(cross(cur), id, 7000, "Substantial completion verified")
	uassert.Equal(t, int64(420_000), recPay)
	uassert.Equal(t, int64(180_000), depRef)
	uassert.Equal(t, recBefore+420_000, ro.GetCoin(recipient, DenomUGNOT))
	uassert.Equal(t, depBefore+180_000, ro.GetCoin(depositor, DenomUGNOT))

	e = GetEscrow(id)
	uassert.Equal(t, string(StatusResolved), string(e.Status))
	uassert.Equal(t, int64(0), e.RemainingAmount())
	uassert.Equal(t, int64(820_000), e.ReleasedAmount)
	uassert.Equal(t, int64(180_000), e.RefundedAmount)

	// Cannot resolve twice
	uassert.AbortsWithMessage(t, cur, ErrEscrowNotDisputed.Error(), func() {
		ResolveDispute(cross(cur), id, 5000, "Double resolve")
	})
}

func TestDeadlineRefund(cur realm, t *testing.T) {
	defer resetState()

	depositor := testutils.TestAddress("dep_ref")
	recipient := testutils.TestAddress("rec_ref")
	ro := banker.NewReadonlyBanker()

	// No arbiter configured ("")
	id := fundAndCreate(
		cur, depositor,
		"Icon Pack",
		recipient, "", 25,
		"Set A,Set B",
		"5000,5000",
		2_000_000,
	)

	// Cannot open dispute without arbiter
	testing.SetRealm(testing.NewUserRealm(depositor))
	uassert.AbortsWithMessage(t, cur, ErrNoArbiter.Error(), func() {
		OpenDispute(cross(cur), id, "Need arbiter")
	})

	// Approve milestone 0 (1,000,000 ugnot)
	ApproveMilestone(cross(cur), id, 0)

	// Refund before deadline must abort
	uassert.AbortsWithMessage(t, cur, ErrDeadlineNotReached.Error(), func() {
		ClaimRefund(cross(cur), id)
	})

	// Advance past deadline
	testing.SkipHeights(25)

	// Recipient cannot claim refund
	testing.SetRealm(testing.NewUserRealm(recipient))
	uassert.AbortsWithMessage(t, cur, ErrUnauthorized.Error(), func() {
		ClaimRefund(cross(cur), id)
	})

	// Depositor reclaims remaining 1,000,000 ugnot
	depBefore := ro.GetCoin(depositor, DenomUGNOT)
	testing.SetRealm(testing.NewUserRealm(depositor))
	refunded := ClaimRefund(cross(cur), id)
	uassert.Equal(t, int64(1_000_000), refunded)
	uassert.Equal(t, depBefore+1_000_000, ro.GetCoin(depositor, DenomUGNOT))

	e := GetEscrow(id)
	uassert.Equal(t, string(StatusRefunded), string(e.Status))
	uassert.Equal(t, int64(0), e.RemainingAmount())
	uassert.Equal(t, int64(1_000_000), e.RefundedAmount)

	// Double refund must abort
	uassert.AbortsWithMessage(t, cur, ErrEscrowNotActive.Error(), func() {
		ClaimRefund(cross(cur), id)
	})
}

func TestValidationAndAuthGuards(cur realm, t *testing.T) {
	defer resetState()

	depositor := testutils.TestAddress("dep_guard")
